arguments.command:
@'
import json, glob, os, sqlite3

ev_dir = r"C:\Users\ngantla\.copilot\session-state\4c8ab7fc-bd1f-480c-99ab-4458bfed9b0e\files\projector_artifacts\rea_evidence"
for p in sorted(glob.glob(os.path.join(ev_dir, "*.json"))):
    with open(p, "r", encoding="utf-8") as f:
        d = json.load(f)
    name = os.path.basename(p)
    ev_id = d.get("evidence_id")
    subj = d.get("subject") or {}
    sha = subj.get("sha256", "")[:16]
    nr = d.get("normalized_result") or {}
    print(f"=== {name} | evidence_id={ev_id} | sha256={sha}... ===")
    print("  keys:", list(nr.keys()))
    members = []
    for k in ("entries", "members", "files", "archive_entries"):
        if isinstance(nr.get(k), list):
            members = nr[k]
            break
    # Walk nested inventory if present
    if not members and isinstance(nr.get("inventory"), dict):
        for k, v in nr["inventory"].items():
            if isinstance(v, list):
                members = v
                break
    if not members:
        # print top-level summary excluding huge arrays
        for k, v in nr.items():
            if isinstance(v, list):
                print(f"  {k}: list[{len(v)}], sample={str(v[:3])[:300]}")
            elif isinstance(v, dict):
                print(f"  {k}: dict keys={list(v.keys())[:15]}")
            else:
                print(f"  {k}: {v}")
    else:
        interesting = []
        for m in members:
            mp = m.get("path") or m.get("name") or str(m)
            if any(x in mp.lower() for x in ("lib/", "assets/", ".so", ".bin", ".param", ".mnn", ".ncnn", ".tflite", ".onnx", ".model", ".cfg", ".ini", ".json", "classes")):
                interesting.append((mp, m.get("size") or m.get("uncompressed_size")))
        print(f"  total_members={len(members)}, interesting={len(interesting)}")
        for mp, sz in interesting[:45]:
            print(f"    - {mp} ({sz})")

print("\n=== SQLITE tvpq.db ===")
db_path = r"C:\Users\ngantla\.copilot\session-state\4c8ab7fc-bd1f-480c-99ab-4458bfed9b0e\files\projector_artifacts\configs\tvpq.db"
con = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
cur = con.cursor()
tables = [r[0] for r in cur.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()]
print("Tables:", tables)
for t in tables:
    cols = [r[1] for r in cur.execute(f"PRAGMA table_info('{t}')").fetchall()]
    rows = cur.execute(f"SELECT * FROM '{t}' LIMIT 10").fetchall()
    print(f"  Table {t} cols={cols} sample_rows({len(rows)}): {rows[:5]}")
'@ | python -

