arguments.command:
@'
const fs = require("fs");
const path = require("path");

const evDir = "C:\\Users\\ngantla\\.copilot\\session-state\\4c8ab7fc-bd1f-480c-99ab-4458bfed9b0e\\files\\projector_artifacts\\rea_evidence";
for (const file of fs.readdirSync(evDir).filter(f => f.endsWith(".json")).sort()) {
  const raw = fs.readFileSync(path.join(evDir, file), "utf8").replace(/^\uFEFF/, "");
  const firstBrace = raw.indexOf("{");
  const d = JSON.parse(raw.slice(firstBrace));
  const sha = d.subject?.sha256?.slice(0, 16) || "none";
  const nr = d.normalized_result || {};
  console.log(`=== ${file} | evidence_id=${d.evidence_id} | sha256=${sha}... ===`);
  console.log("  nr keys:", Object.keys(nr));
  const entries = nr.entries || nr.members || nr.archive?.entries || nr.inventory?.entries || [];
  if (entries.length) {
    const interesting = entries.filter(e => {
      const p = (e.path || e.name || "").toLowerCase();
      return p.startsWith("lib/") || p.startsWith("assets/") || p.endsWith(".dex") ||
             /\.(so|bin|param|mnn|ncnn|tflite|onnx|model|cfg|ini|json|xml|pb|dlc)$/.test(p) && !p.startsWith("res/");
    });
    console.log(`  total_entries=${entries.length}, interesting=${interesting.length}`);
    for (const e of interesting.slice(0, 50)) {
      console.log(`    - ${e.path || e.name} (${e.size ?? e.uncompressed_size ?? "?"})`);
    }
  } else {
    console.log("  summary:", JSON.stringify(nr).slice(0, 800));
  }
}

try {
  const { DatabaseSync } = require("node:sqlite");
  const db = new DatabaseSync("C:\\Users\\ngantla\\.copilot\\session-state\\4c8ab7fc-bd1f-480c-99ab-4458bfed9b0e\\files\\projector_artifacts\\configs\\tvpq.db", { open: true, readOnly: true });
  const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all();
  console.log("\n=== tvpq.db TABLES ===", tables.map(t => t.name));
  for (const { name } of tables) {
    const rows = db.prepare(`SELECT * FROM "${name}" LIMIT 15`).all();
    console.log(`  Table ${name} (${rows.length} rows):`, JSON.stringify(rows.slice(0, 8)));
  }
} catch (err) {
  console.log("SQLite err:", err.message);
}
