@'
const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");

const evDir = "C:\\Users\\ngantla\\.copilot\\session-state\\4c8ab7fc-bd1f-480c-99ab-4458bfed9b0e\\files\\projector_artifacts\\rea_evidence";
const dexdump = "C:\\Users\\ngantla\\AppData\\Local\\Android\\Sdk\\build-tools\\36.0.0\\dexdump.exe";

for (const f of fs.readdirSync(evDir).filter(x => x.startsWith("extract_") && x.endsWith(".json")).sort()) {
  const raw = fs.readFileSync(path.join(evDir, f), "utf8").replace(/^\uFEFF/, "");
  const d = JSON.parse(raw.slice(raw.indexOf("{")));
  const nr = d.normalized_result || {};
  const outRoot = nr.output_directory || nr.extracted_path || nr.directory || nr.root_path;
  console.log(`=== ${f} | evidence_id=${d.evidence_id} | outRoot=${outRoot} ===`);
  if (!outRoot) {
    console.log("  keys:", Object.keys(nr), JSON.stringify(nr).slice(0, 400));
    continue;
  }
  const dexFiles = fs.readdirSync(outRoot).filter(x => x.endsWith(".dex")).sort();
  for (const dex of dexFiles) {
    const out = execFileSync(dexdump, [path.join(outRoot, dex)], { encoding: "utf8", maxBuffer: 80 * 1024 * 1024 });
    const classes = out.split(/\r?\n/)
      .filter(l => l.includes("Class descriptor"))
      .map(l => l.split("'")[1] || l)
      .filter(c => /^L(com\/hysd|com\/htp|com\/softwinner|com\/allwinner|vendor\/|cn\/|org\/opencv)/.test(c));
    console.log(`  [${dex}] matched OEM classes (${classes.length}):`);
    for (const c of classes.slice(0, 80)) console.log("   ", c);
  }
}
