const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");

const extDir = "C:\\Users\\ngantla\\.copilot\\session-state\\4c8ab7fc-bd1f-480c-99ab-4458bfed9b0e\\files\\projector_artifacts\\extracted\\com.hysd.screen";
const dexdump = "C:\\Users\\ngantla\\AppData\\Local\\Android\\Sdk\\build-tools\\36.0.0\\dexdump.exe";

// 1. Inspect com/hysd/vafocus/* and VAFBase / VAF2S / HYSDkeystone in classes.dex & classes2.dex
for (const dex of ["classes.dex", "classes2.dex"]) {
  const p = path.join(extDir, dex);
  if (!fs.existsSync(p)) continue;
  const hdr = execFileSync(dexdump, [p], { encoding: "utf8", maxBuffer: 120 * 1024 * 1024 });
  const classes = hdr.split(/\r?\n/).filter(l => l.includes("Class descriptor")).map(l => l.split("'")[1]).filter(c => c && c.startsWith("Lcom/hysd/") && !c.includes("ExternalSynthetic"));
  if (classes.length) console.log(`=== ${dex} com/hysd classes (${classes.length}) ===\n`, classes);

  const blocks = hdr.split(/Class #\d+\s+-/);
  for (const b of blocks) {
    const m = b.match(/Class descriptor\s+:\s+'([^']+)'/);
    if (!m) continue;
    if (/^Lcom\/hysd\/(vafocus\/.*|hyscreen\/VAFBase|hyscreen\/VAF2S|hyscreen\/VAF4S);$/.test(m[1])) {
      console.log(`\n--- HEADER ${m[1]} ---`);
      for (const line of b.split(/\r?\n/)) {
        if (/^\s+(name|type)\s+:\s+'/.test(line)) console.log(" ", line.trim());
      }
    }
  }
}

// 2. C++ symbols (_Z*) and log/algorithm strings in libfocusvahysd.so
const buf = fs.readFileSync(path.join(extDir, "lib", "armeabi-v7a", "libfocusvahysd.so"));
const str = buf.toString("latin1");
const cppSyms = [...new Set(str.match(/_Z[A-Za-z0-9_]+/g) || [])]
  .filter(s => !/^_Z(?:NSt|NKSt|St|TI|TS|TV|Thn|GV)/.test(s) && !/opencv|cv[0-9]|eigen|ceres/i.test(s));
console.log(`\n=== libfocusvahysd.so custom C++ symbols (${cppSyms.length}) ===`);
for (const s of cppSyms.slice(0, 140)) console.log(" ", s);

const logs = [...new Set(str.match(/[ -~]{8,100}/g) || [])]
  .filter(s => /sfk|obs|avoid|curtain|screen|border|corner|homography|chess|trap|keystone|rect|mask|yolo|ncnn|mnn|onnx|cnn|onnx|contour|canny|thresh|inscrib|maxrect/i.test(s) && !s.startsWith("_Z") && !s.includes("opencv"));
console.log(`\n=== libfocusvahysd.so algorithm/log strings (${logs.length}) ===`);
for (const s of logs.slice(0, 100)) console.log(" ", s);
