arguments.command:
@'
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const { execFileSync, spawnSync } = require("child_process");

const adb = path.join(process.env.LOCALAPPDATA, "Android\\Sdk\\platform-tools\\adb.exe");
const serial = "192.168.137.81:5555";
const root = "C:\\Users\\ngantla\\Backups\\Wzatco-Yuva-Blaze";

// 1. Re-create clean binary etc_configs.tar via cmd /c binary redirection & verify with tar -tf
const tarPath = path.join(root, "configs", "etc_configs.tar");
execFileSync("cmd.exe", ["/c", `"${adb}" -s ${serial} exec-out "tar -cf - /vendor/etc /system/etc /product/etc 2>/dev/null" > "${tarPath}"`]);
const tarList = execFileSync("tar.exe", ["-tf", tarPath], { encoding: "utf8", maxBuffer: 20 * 1024 * 1024 }).trim().split(/\r?\n/);
console.log(`Verified binary etc_configs.tar: ${fs.statSync(tarPath).size} bytes, ${tarList.length} entries`);

// 2. Enumerate every installed package and pull ALL APK splits (base.apk + any split_*.apk) + APEX modules
const pkgLines = execFileSync(adb, ["-s", serial, "shell", "pm list packages -u"], { encoding: "utf8" })
  .trim().split(/\r?\n/).map(l => l.replace(/^package:/, "").trim()).filter(Boolean).sort();

console.log(`Found ${pkgLines.length} total packages to back up...`);
let totalApks = 0;
let totalBytes = 0;
const apkManifest = [];

for (const pkg of pkgLines) {
  const pathsOut = execFileSync(adb, ["-s", serial, "shell", `pm path ${pkg}`], { encoding: "utf8" }).trim();
  const remotePaths = pathsOut.split(/\r?\n/).map(l => l.replace(/^package:/, "").trim()).filter(Boolean);
  for (const rp of remotePaths) {
    // Classify bucket by mount root
    let bucket = "other";
    if (rp.startsWith("/data/app/")) bucket = "user_data_app";
    else if (rp.startsWith("/system/priv-app/")) bucket = "system_priv_app";
    else if (rp.startsWith("/system/app/")) bucket = "system_app";
    else if (rp.startsWith("/system/system_ext/")) bucket = "system_ext";
    else if (rp.startsWith("/system/framework/")) bucket = "system_framework";
    else if (rp.startsWith("/product/")) bucket = "product";
    else if (rp.startsWith("/vendor/")) bucket = "vendor";
    else if (rp.startsWith("/apex/")) bucket = "apex_app";

    const pkgDir = path.join(root, "apks", bucket, pkg);
    fs.mkdirSync(pkgDir, { recursive: true });
    const leaf = path.basename(rp);
    const localFile = path.join(pkgDir, leaf);
    execFileSync(adb, ["-s", serial, "pull", rp, localFile], { stdio: "pipe" });
    const sz = fs.statSync(localFile).size;
    totalApks++;
    totalBytes += sz;
    apkManifest.push({ pkg, remotePath: rp, localPath: path.relative(root, localFile), size: sz });
  }
}

// 3. Also pull raw /system/apex/*.apex / *.capex packages if present
const apexOut = execFileSync(adb, ["-s", serial, "shell", "ls /system/apex/* 2>/dev/null || true"], { encoding: "utf8" }).trim();
const apexFiles = apexOut.split(/\r?\n/).map(s => s.trim()).filter(s => s.endsWith(".apex") || s.endsWith(".capex"));
const apexDir = path.join(root, "apks", "system_apex_containers");
fs.mkdirSync(apexDir, { recursive: true });
