@'
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const { execFileSync, spawnSync } = require("child_process");

const adb = path.join(process.env.LOCALAPPDATA, "Android\\Sdk\\platform-tools\\adb.exe");
const serial = "192.168.137.81:5555";
const root = "C:\\Users\\ngantla\\Backups\\Wzatco-Yuva-Blaze";
const partDir = path.join(root, "partitions");
fs.mkdirSync(partDir, { recursive: true });

// 1. Query exact kernel sysfs start/size (in 512-byte sectors) and /dev/block/by-name mapping
const mapCmd = `
for link in /dev/block/by-name/*; do
  name=$(basename "$link")
  target=$(readlink -f "$link")
  dev=$(basename "$target")
  if [ -f "/sys/block/mmcblk0/$dev/start" ]; then
    start=$(cat "/sys/block/mmcblk0/$dev/start")
    size=$(cat "/sys/block/mmcblk0/$dev/size")
    echo "$name|$dev|$start|$size"
  fi
done
`;
const lines = execFileSync(adb, ["-s", serial, "shell", mapCmd], { encoding: "utf8" }).trim().split(/\r?\n/).filter(Boolean);
const parts = lines.map(l => {
  const [name, dev, start, size] = l.trim().split("|");
  return { name, dev, start: Number(start), size: Number(size), bytes: Number(size) * 512 };
}).sort((a, b) => a.start - b.start);

fs.writeFileSync(path.join(root, "metadata", "gpt_partition_map.json"), JSON.stringify(parts, null, 2));
console.log(`Mapped ${parts.length} GPT partitions:`);
for (const p of parts) {
  console.log(`  ${p.name.padEnd(18)} ${p.dev.padEnd(12)} start=${String(p.start).padStart(9)} sectors=${String(p.size).padStart(9)} (${(p.bytes/1048576).toFixed(2)} MiB)`);
}

function sha256File(filePath) {
  const hash = crypto.createHash("sha256");
  const fd = fs.openSync(filePath, "r");
  const buf = Buffer.allocUnsafe(4 * 1024 * 1024);
  let bytesRead = 0;
  while ((bytesRead = fs.readSync(fd, buf, 0, buf.length, null)) > 0) {
    hash.update(bytesRead === buf.length ? buf : buf.subarray(0, bytesRead));
  }
  fs.closeSync(fd);
  return hash.digest("hex");
}

// 2. Dump Primary GPT Header/Table (first 2048 sectors = 1 MiB before p1)
{
  const gptFile = path.join(partDir, "mmcblk0_gpt_primary_1MiB.bin");
  const fd = fs.openSync(gptFile, "w");
  spawnSync(adb, ["-s", serial, "exec-out", "dd if=/dev/block/mmcblk0 bs=512 count=2048 2>/dev/null"], { stdio: ["ignore", fd, "pipe"] });
  fs.closeSync(fd);
  const devSha = execFileSync(adb, ["-s", serial, "shell", "dd if=/dev/block/mmcblk0 bs=512 count=2048 2>/dev/null | sha256sum"], { encoding: "utf8" }).trim().split(/\s+/)[0];
  const pcSha = sha256File(gptFile);
  if (devSha !== pcSha) throw new Error(`GPT SHA mismatch: dev=${devSha} pc=${pcSha}`);
  console.log(`VERIFIED mmcblk0_gpt_primary_1MiB.bin (${fs.statSync(gptFile).size}B) sha256=${pcSha.slice(0,16)}...`);
}

// 3. Dump all partitions EXCEPT super and userdata first (using exact 4096-byte block alignment where divisible)
const verified = [];
for (const p of parts) {
  if (p.name === "super" || p.name === "userdata") continue;
  const outImg = path.join(partDir, `${p.name}.img`);
  // Use bs=4096 when start & size are multiples of 8 sectors (all GPT partitions are 4K-aligned!)
  const bs = (p.start % 8 === 0 && p.size % 8 === 0) ? 4096 : 512;
  const skip = (bs === 4096) ? (p.start / 8) : p.start;
  const count = (bs === 4096) ? (p.size / 8) : p.size;

  const fd = fs.openSync(outImg, "w");
  spawnSync(adb, ["-s", serial, "exec-out", `dd if=/dev/block/mmcblk0 bs=${bs} skip=${skip} count=${count} 2>/dev/null`], { stdio: ["ignore", fd, "pipe"] });
  fs.closeSync(fd);

  const devSha = execFileSync(adb, ["-s", serial, "shell", `dd if=/dev/block/mmcblk0 bs=${bs} skip=${skip} count=${count} 2>/dev/null | sha256sum`], { encoding: "utf8" }).trim().split(/\s+/)[0];
  const pcSha = sha256File(outImg);
  const actualBytes = fs.statSync(outImg).size;
  if (actualBytes !== p.bytes || devSha !== pcSha) {
    throw new Error(`Mismatch on ${p.name}: bytes=${actualBytes}/${p.bytes} dev=${devSha} pc=${pcSha}`);
  }
  verified.push({ ...p, sha256: pcSha, file: `partitions\\${p.name}.img` });
  console.log(`VERIFIED ${p.name.padEnd(18)} ${(actualBytes/1048576).toFixed(2).padStart(7)} MiB | sha256=${pcSha.slice(0,16)}...`);
}
fs.writeFileSync(path.join(root, "metadata", "verified_small_partitions.json"), JSON.stringify(verified, null, 2));
