package com.hysd.hyscreen.alcove;

import android.graphics.Bitmap;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.util.Log;

import java.io.File;
import java.io.FileOutputStream;
import java.io.FileWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Multi-cue fast on-device alcove sidewall + obstacle avoidance solver.
 *
 * Combines 4 physical signals on 640x480 raw YUYV luma frames:
 *   1. Ambient-canceled irradiance map W = max(0, Y_white - Y_dark)
 *   2. 91-dot self-calibrating fiducial lattice + RANSAC planar homography H_back
 *      (detects 3D depth steps & non-coplanar side-wall slope kinks via parallax residual)
 *   3. Photometric straight-line corner crease detection (Lambertian cos(theta) normal step
 *      at alcove side walls, protruding pillars, and top soffits)
 *   4. High-frequency vertical grating contrast S(x,y) (Depth-from-Defocus + oblique grazing blur,
 *      with optional 2-step focus-motor DfD ratio S_near / S_0)
 */
public final class AlcoveVisionPipeline {
    private static final String TAG = "TurboAlcove";

    public static final int CAM_W = 640;
    public static final int CAM_H = 480;
    public static final int CAM_N = CAM_W * CAM_H;

    // 192 x 108 working grid in projector space (1 cell = 10x10 projector pixels)
    public static final int GW = 192;
    public static final int GH = 108;
    public static final int CELL_PX = 10;

    public static final class Result {
        public final boolean success;
        public final int[] insets; // [ltx, lty, lbx, lby, rbx, rby, rtx, rty]
        public final int rectLeftPx;
        public final int rectTopPx;
        public final int rectRightPx;
        public final int rectBottomPx;
        public final int detectedLeftWallPx;
        public final int detectedRightWallPx;
        public final int detectedTopWallPx;
        public final int detectedBottomWallPx;
        public final int matchedDots;
        public final long solveTimeMs;
        public final String summary;

        public Result(
                boolean success, int[] insets,
                int l, int t, int r, int b,
                int lw, int rw, int tw, int bw,
                int matchedDots, long solveTimeMs, String summary) {
            this.success = success;
            this.insets = insets;
            this.rectLeftPx = l;
            this.rectTopPx = t;
            this.rectRightPx = r;
            this.rectBottomPx = b;
            this.detectedLeftWallPx = lw;
            this.detectedRightWallPx = rw;
            this.detectedTopWallPx = tw;
            this.detectedBottomWallPx = bw;
            this.matchedDots = matchedDots;
            this.solveTimeMs = solveTimeMs;
            this.summary = summary;
        }
    }

    private static final class Blob {
        float u, v;
        int area;
        float peakD2;
        float meanD3;
        int assignedCol = -1;
        int assignedRow = -1;
    }

    public static void extractLuma(byte[] yuyv, int[] outY) {
        final int n = Math.min(CAM_N, yuyv.length >> 1);
        for (int i = 0, j = 0; i < n; i++, j += 2) {
            outY[i] = yuyv[j] & 0xFF;
        }
    }

    /**
     * Fast Tenengrad focus metric on central 160x120 camera ROI (~0.08 ms) for closed-loop AF.
     */
    public static double computeCenterFocusScore(byte[] yuyv) {
        int u0 = (CAM_W - 160) / 2, u1 = u0 + 160;
        int v0 = (CAM_H - 120) / 2, v1 = v0 + 120;
        long sum = 0;
        for (int v = v0 + 1; v < v1 - 1; v++) {
            int row = v * CAM_W;
            for (int u = u0 + 1; u < u1 - 1; u++) {
                int gx = (yuyv[((row + u + 1) << 1)] & 0xFF) - (yuyv[((row + u - 1) << 1)] & 0xFF);
                int gy = (yuyv[((row + CAM_W + u) << 1)] & 0xFF) - (yuyv[((row - CAM_W + u) << 1)] & 0xFF);
                sum += gx * gx + gy * gy;
            }
        }
        return sum / (double) (158 * 118);
    }

    public static Result solve(
            int[] yDark, int[] yWhite, int[] yGrid, int[] yAnchorSharp,
            int[] yNearSharpOptional, float minAreaRatio, boolean saveDebug) {
        final long t0 = System.nanoTime();

        // 1. Ambient-canceled beam radiance W = max(0, yWhite - yDark) and normalized dot responses D2, D3
        int[] W = new int[CAM_N];
        int[] D2 = new int[CAM_N];
        int[] D3 = new int[CAM_N];
        int[] histW = new int[256];
        int centerSamples = 0;
        for (int v = CAM_H / 5; v < (CAM_H * 4) / 5; v++) {
            int off = v * CAM_W;
            for (int u = CAM_W / 5; u < (CAM_W * 4) / 5; u++) {
                int w = yWhite[off + u] - yDark[off + u];
                if (w < 0) w = 0;
                if (w > 255) w = 255;
                histW[w]++;
                centerSamples++;
            }
        }
        int targetRank = (int) (centerSamples * 0.88f);
        int cum = 0, wP88 = 40;
        for (int b = 0; b < 256; b++) {
            cum += histW[b];
            if (cum >= targetRank) {
                wP88 = b;
                break;
            }
        }
        final int beamThresh = Math.max(12, Math.round(wP88 * 0.18f));
        final int normFloor = Math.max(16, Math.round(wP88 * 0.22f));

        for (int i = 0; i < CAM_N; i++) {
            int w = yWhite[i] - yDark[i];
            if (w < 0) w = 0;
            W[i] = w;
            if (w >= beamThresh) {
                int denom = Math.max(w, normFloor);
                int diff2 = yWhite[i] - yGrid[i];
                if (diff2 > 0) {
                    int v2 = (diff2 * 255) / denom;
                    D2[i] = v2 > 255 ? 255 : v2;
                }
                int diff3 = yWhite[i] - yAnchorSharp[i];
                if (diff3 > 0) {
                    int v3 = (diff3 * 255) / denom;
                    D3[i] = v3 > 255 ? 255 : v3;
                }
            }
        }

        // 2. Extract fiducial dot blobs from D2 and match the 13x7 coded lattice
        List<Blob> blobs = detectBlobs(D2, D3, 78);
        int[][] gridToBlob = new int[PatternOverlayView.GRID_COLS][PatternOverlayView.GRID_ROWS];
        for (int c = 0; c < PatternOverlayView.GRID_COLS; c++) Arrays.fill(gridToBlob[c], -1);

        int matchedDots = assignLattice(blobs, gridToBlob);
        Log.i(TAG, "Blobs=" + blobs.size() + " matchedLatticeDots=" + matchedDots + " wP88=" + wP88 + " beamThresh=" + beamThresh);

        // 3. Fit main back-wall planar homography H_back (Projector X,Y -> Camera u,v)
        double[] Hback = null;
        if (matchedDots >= 6) {
            double[] allX = new double[matchedDots];
            double[] allY = new double[matchedDots];
            double[] allU = new double[matchedDots];
            double[] allV = new double[matchedDots];
            boolean[] seedMask = new boolean[matchedDots];
            int k = 0;
            for (int c = 0; c < PatternOverlayView.GRID_COLS; c++) {
                for (int r = 0; r < PatternOverlayView.GRID_ROWS; r++) {
                    int bi = gridToBlob[c][r];
                    if (bi < 0) continue;
                    Blob b = blobs.get(bi);
                    allX[k] = PatternOverlayView.dotProjX(c);
                    allY[k] = PatternOverlayView.dotProjY(r);
                    allU[k] = b.u;
                    allV[k] = b.v;
                    // Seed RANSAC on central back-wall zone around (6,3) so side walls never dominate H_back
                    seedMask[k] = (c >= 3 && c <= 8 && r >= 1 && r <= 5);
                    k++;
                }
            }
            Hback = HomographySolver.fitRansac(allX, allY, allU, allV, seedMask, k, 2.2);
        }

        // Fallback homography from outer illuminated beam quad in W if lattice had < 6 dots
        if (Hback == null) {
            Hback = fitBeamQuadFallbackHomography(W, beamThresh);
        }
        if (Hback == null) {
            long ms = (System.nanoTime() - t0) / 1_000_000L;
            return new Result(false, new int[8], 0, 0, 1920, 1080, 0, 1920, 0, 1080,
                    matchedDots, ms, "Homography fallback failed (insufficient beam contrast)");
        }

        // 4. Compute per-lattice-node homography parallax & spacing foreshortening kink
        float[][] dotParallax = new float[PatternOverlayView.GRID_COLS][PatternOverlayView.GRID_ROWS];
        boolean[][] dotObserved = new boolean[PatternOverlayView.GRID_COLS][PatternOverlayView.GRID_ROWS];
        double[] uvPred = new double[2];
        double[] uvNextPred = new double[2];

        for (int c = 0; c < PatternOverlayView.GRID_COLS; c++) {
            for (int r = 0; r < PatternOverlayView.GRID_ROWS; r++) {
                int bi = gridToBlob[c][r];
                if (bi < 0) continue;
                Blob b = blobs.get(bi);
                HomographySolver.project(Hback, PatternOverlayView.dotProjX(c), PatternOverlayView.dotProjY(r), uvPred);
                float err = (float) Math.hypot(b.u - uvPred[0], b.v - uvPred[1]);

                // Also measure horizontal spacing foreshortening / angle kink across neighbors (sidewall crease!)
                float kinkScore = 0f;
                if (c + 1 < PatternOverlayView.GRID_COLS && gridToBlob[c + 1][r] >= 0) {
                    Blob bNext = blobs.get(gridToBlob[c + 1][r]);
                    HomographySolver.project(Hback, PatternOverlayView.dotProjX(c + 1), PatternOverlayView.dotProjY(r), uvNextPred);
                    double obsDu = bNext.u - b.u, obsDv = bNext.v - b.v;
                    double expDu = uvNextPred[0] - uvPred[0], expDv = uvNextPred[1] - uvPred[1];
                    double obsLen = Math.hypot(obsDu, obsDv);
                    double expLen = Math.max(4.0, Math.hypot(expDu, expDv));
                    // Scale change (foreshortening on 90-deg side wall) + vector difference
                    double vecDiff = Math.hypot(obsDu - expDu, obsDv - expDv);
                    double scaleRatioDiff = Math.abs(obsLen / expLen - 1.0) * 10.0;
                    kinkScore = (float) Math.max(vecDiff, scaleRatioDiff);
                }
                dotParallax[c][r] = Math.max(err, kinkScore * 0.75f);
                dotObserved[c][r] = true;
            }
        }

        // 5. Compute camera-space horizontal micro-stripe sharpness map S0 (and optional DfD ratio S_near / S0)
        float[] camSharp0 = computeHorizontalAcutance(yAnchorSharp, W, beamThresh, normFloor);
        float[] camDfdRatio = null;
        if (yNearSharpOptional != null) {
            float[] camSharpNear = computeHorizontalAcutance(yNearSharpOptional, W, beamThresh, normFloor);
            camDfdRatio = new float[CAM_N];
            for (int i = 0; i < CAM_N; i++) {
                if (camSharp0[i] > 0.03f) {
                    camDfdRatio[i] = (camSharpNear[i] + 0.02f) / (camSharp0[i] + 0.02f);
                } else {
                    camDfdRatio[i] = 1.0f;
                }
            }
        }

        // 6. Warp W, sharpness, DfD, and dot parallax onto the 192x108 projector grid
        float[][] projW = new float[GW][GH];
        float[][] projSharp = new float[GW][GH];
        float[][] projDfd = new float[GW][GH];
        float[][] projParallax = new float[GW][GH];
        boolean[][] inCameraBounds = new boolean[GW][GH];

        for (int gx = 0; gx < GW; gx++) {
            double px = (gx + 0.5) * CELL_PX;
            for (int gy = 0; gy < GH; gy++) {
                double py = (gy + 0.5) * CELL_PX;
                HomographySolver.project(Hback, px, py, uvPred);
                float u = (float) uvPred[0];
                float v = (float) uvPred[1];
                if (u >= 2f && u < CAM_W - 3f && v >= 2f && v < CAM_H - 3f) {
                    inCameraBounds[gx][gy] = true;
                    projW[gx][gy] = sampleBilinearInt(W, u, v);
                    projSharp[gx][gy] = sampleBilinearFloat(camSharp0, u, v);
                    projDfd[gx][gy] = (camDfdRatio != null) ? sampleBilinearFloat(camDfdRatio, u, v) : 1.0f;
                }
                projParallax[gx][gy] = interpolateGridParallax(dotParallax, dotObserved, (float) px, (float) py);
            }
        }

        // Smooth radial lens vignetting compensation relative to center main wall [gx in 64..118, gy in 30..78]
        float centerW = percentileGrid(projW, 64, 118, 30, 78, 0.65f);
        if (centerW < 15f) centerW = Math.max(20f, wP88);
        // Estimate natural optical corner falloff factor safely bounded in [0.68..1.0]
        float[][] normW = new float[GW][GH];
        for (int gx = 0; gx < GW; gx++) {
            float dx = (gx - GW * 0.5f) / (GW * 0.5f);
            for (int gy = 0; gy < GH; gy++) {
                float dy = (gy - GH * 0.5f) / (GH * 0.5f);
                float r2 = dx * dx + dy * dy;
                float vignette = Math.max(0.70f, 1.0f - 0.16f * r2);
                normW[gx][gy] = projW[gx][gy] / (centerW * vignette);
            }
        }

        // Reference sharpness on main wall outside the central 3x3 white-halo anchor zone
        float refSharp = Math.max(
                percentileGrid(projSharp, 42, 70, 24, 82, 0.65f),
                percentileGrid(projSharp, 120, 140, 24, 82, 0.65f));
        if (refSharp < 0.04f) refSharp = percentileGrid(projSharp, 30, 160, 18, 90, 0.70f);

        // 7. Detect Alcove Sidewall / Pillar / Soffit Seams (fusing photometric crease + parallax kink + defocus!)
        int leftSeamGx = detectVerticalWallSeam(normW, projW, projParallax, projSharp, projDfd,
                beamThresh, refSharp, true);
        int rightSeamGx = detectVerticalWallSeam(normW, projW, projParallax, projSharp, projDfd,
                beamThresh, refSharp, false);
        int topSeamGy = detectHorizontalWallSeam(normW, projW, projParallax, projSharp, projDfd,
                beamThresh, refSharp, true, leftSeamGx, rightSeamGx);
        int bottomSeamGy = detectHorizontalWallSeam(normW, projW, projParallax, projSharp, projDfd,
                beamThresh, refSharp, false, leftSeamGx, rightSeamGx);

        // 8. Build Interior Obstacle + Sidewall Exclusion Mask on 192x108 Grid
        float[][] smoothNormW = boxSmooth(normW, 7);
        boolean[][] rawValid = new boolean[GW][GH];
        for (int gx = 0; gx < GW; gx++) {
            for (int gy = 0; gy < GH; gy++) {
                if (!inCameraBounds[gx][gy]) continue;
                if (gx < leftSeamGx || gx > rightSeamGx || gy < topSeamGy || gy > bottomSeamGy) continue;
                if (projW[gx][gy] < beamThresh * 1.15f) continue;

                float nw = normW[gx][gy];
                float localBg = Math.max(0.35f, smoothNormW[gx][gy]);
                // Dark obstacle / curtain / cord / furniture silhouette
                if (nw < 0.62f || nw < localBg * 0.76f) continue;
                // Strong local edge/relief obstacle (e.g., electrical switchplate / frame border)
                if (gx > 1 && gx < GW - 2 && gy > 1 && gy < GH - 2) {
                    float grad = Math.abs(normW[gx + 1][gy] - normW[gx - 1][gy])
                               + Math.abs(normW[gx][gy + 1] - normW[gx][gy - 1]);
                    if (grad > 0.30f) continue;
                }
                // 3D non-coplanar protrusion via homography parallax or DfD closer-focus spike
                if (projParallax[gx][gy] > 3.1f) continue;
                if (camDfdRatio != null && projDfd[gx][gy] > 1.16f) continue;
                // Severe localized defocus / oblique wall grazing blur despite normal brightness
                if (refSharp > 0.08f && !isInsideCentralAnchorHalo(gx, gy)
                        && projSharp[gx][gy] < refSharp * 0.46f) {
                    continue;
                }
                rawValid[gx][gy] = true;
            }
        }

        // Fill isolated 1-cell pinhole noise, then erode by 2 cells (20 projector px safety buffer)
        boolean[][] closed = morphClose1(rawValid);
        boolean[][] safeValid = erode(closed, 2);

        // 9. Exact O(GW * GH) Monotonic-Stack Largest Sharpness-Aware 16:9 Rectangle Solver
        int[] bestRectCells = findOptimal16x9Rect(safeValid, leftSeamGx, rightSeamGx, topSeamGy, bottomSeamGy);
        int gx0 = bestRectCells[0], gy0 = bestRectCells[1], gx1 = bestRectCells[2], gy1 = bestRectCells[3];

        int lPx = clamp(gx0 * CELL_PX, 0, 880);
        int tPx = clamp(gy0 * CELL_PX, 0, 480);
        int rPx = clamp((gx1 + 1) * CELL_PX, lPx + 480, PatternOverlayView.PROJ_W);
        int bPx = clamp((gy1 + 1) * CELL_PX, tPx + 270, PatternOverlayView.PROJ_H);

        float areaRatio = ((rPx - lPx) * (bPx - tPx)) / (float) (PatternOverlayView.PROJ_W * PatternOverlayView.PROJ_H);
        long solveMs = (System.nanoTime() - t0) / 1_000_000L;

        if (areaRatio < minAreaRatio) {
            Log.w(TAG, "Area ratio " + areaRatio + " below floor " + minAreaRatio + "; clamping to safe floor.");
            // Expand symmetrically around detected alcove center up to minAreaRatio if over-constrained
            int targetW = Math.min(1920, (int) Math.round(Math.sqrt(minAreaRatio * 1920.0 * 1080.0 * 16.0 / 9.0)));
            int targetH = Math.round(targetW * 9f / 16f);
            int cx = (lPx + rPx) / 2;
            int cy = (tPx + bPx) / 2;
            lPx = clamp(cx - targetW / 2, 0, 1920 - targetW);
            tPx = clamp(cy - targetH / 2, 0, 1080 - targetH);
            rPx = lPx + targetW;
            bPx = tPx + targetH;
        }

        // Convert [lPx, tPx, rPx, bPx] to AwTvDisplayManager / HYSDInterface.setkey inward offsets:
        // [ltx, lty, lbx, lby, rbx, rby, rtx, rty]
        int ltx = lPx;
        int lty = tPx;
        int lbx = lPx;
        int lby = PatternOverlayView.PROJ_H - bPx;
        int rbx = PatternOverlayView.PROJ_W - rPx;
        int rby = PatternOverlayView.PROJ_H - bPx;
        int rtx = PatternOverlayView.PROJ_W - rPx;
        int rty = tPx;
        int[] insets = new int[] { ltx, lty, lbx, lby, rbx, rby, rtx, rty };

        String summary = String.format(
                "Alcove 16:9 [%d..%d x %d..%d] (%dx%d, %.0f%%) | Walls L=%d R=%d T=%d B=%d | Dots=%d | %dms",
                lPx, rPx, tPx, bPx, (rPx - lPx), (bPx - tPx),
                100f * ((rPx - lPx) * (bPx - tPx)) / (1920f * 1080f),
                leftSeamGx * CELL_PX, (rightSeamGx + 1) * CELL_PX,
                topSeamGy * CELL_PX, (bottomSeamGy + 1) * CELL_PX,
                matchedDots, solveMs);
        Log.i(TAG, summary);

        if (saveDebug) {
            saveDiagnosticArtifact(W, blobs, gridToBlob, dotParallax, Hback,
                    safeValid, leftSeamGx, rightSeamGx, topSeamGy, bottomSeamGy,
                    lPx, tPx, rPx, bPx, insets, summary);
        }

        return new Result(
                true, insets, lPx, tPx, rPx, bPx,
                leftSeamGx * CELL_PX, (rightSeamGx + 1) * CELL_PX,
                topSeamGy * CELL_PX, (bottomSeamGy + 1) * CELL_PX,
                matchedDots, solveMs, summary);
    }

    /**
     * Scans outward from the center main wall to detect vertical alcove boundaries:
     *   - Left protruding pillar / wall return (scanLeft = true: gx from 80 down to 3)
     *   - Right perpendicular side wall / corner crease (scanLeft = false: gx from 112 up to 188)
     */
    private static int detectVerticalWallSeam(
            float[][] normW, float[][] projW, float[][] projParallax,
            float[][] projSharp, float[][] projDfd,
            int beamThresh, float refSharp, boolean scanLeft) {

        int defaultEdge = scanLeft ? 1 : (GW - 2);
        int startGx = scanLeft ? 82 : 110;
        int endGx = scanLeft ? 4 : (GW - 5);
        int step = scanLeft ? -1 : 1;

        int bestGx = defaultEdge;
        float bestScore = 0f;

        for (int gx = startGx; gx != endGx; gx += step) {
            // Compare a 5-cell inner strip (on the back wall side) vs 5-cell outer strip (on the sidewall side)
            int inStart = scanLeft ? (gx + 1) : (gx - 5);
            int outStart = scanLeft ? (gx - 5) : (gx + 1);
            if (inStart < 1 || inStart + 4 >= GW || outStart < 1 || outStart + 4 >= GW) continue;

            float sumInW = 0, sumOutW = 0;
            float sumEdge = 0, consistentSign = 0;
            float sumOutParallax = 0, sumInParallax = 0;
            float sumOutSharp = 0;
            float sumOutDfd = 0;
            int sharpCount = 0;
            int activeRows = 0;
            int unlitOuterRows = 0;

            for (int gy = 14; gy < GH - 16; gy++) {
                float inVal = 0, outVal = 0;
                for (int k = 0; k < 5; k++) {
                    inVal += normW[inStart + k][gy];
                    outVal += normW[outStart + k][gy];
                }
                inVal *= 0.2f;
                outVal *= 0.2f;

                if (projW[inStart + 2][gy] < beamThresh) continue;
                activeRows++;
                if (projW[outStart + 2][gy] < beamThresh * 0.9f) {
                    unlitOuterRows++;
                }

                sumInW += inVal;
                sumOutW += outVal;
                float diff = inVal - outVal;
                sumEdge += Math.abs(diff);
                consistentSign += diff;

                sumInParallax += projParallax[inStart + 2][gy];
                sumOutParallax += projParallax[outStart + 2][gy];

                if (!isInsideCentralAnchorHalo(outStart + 2, gy)) {
                    sumOutSharp += projSharp[outStart + 2][gy];
                    sumOutDfd += projDfd[outStart + 2][gy];
                    sharpCount++;
                }
            }

            if (activeRows < 22) continue;

            // Case A: Beam falls off physical wall edge / dark alcove border
            if (unlitOuterRows > activeRows * 0.65f) {
                return scanLeft ? (gx + 1) : (gx - 1);
            }

            float meanInW = sumInW / activeRows;
            float meanOutW = sumOutW / activeRows;
            // Photometric crease coherence: straight 90-deg corner has consistent sign all the way top-to-bottom!
            float signedJump = Math.abs(consistentSign) / Math.max(0.25f, sumInW);
            float localGrad = Math.abs(meanInW - meanOutW) / Math.max(0.25f, meanInW);
            float coherence = Math.abs(consistentSign) / Math.max(1e-4f, sumEdge);

            float meanOutPar = sumOutParallax / activeRows;
            float parRise = Math.max(0f, meanOutPar - (sumInParallax / activeRows));

            float sharpRatio = (sharpCount > 8 && refSharp > 0.05f)
                    ? ((sumOutSharp / sharpCount) / refSharp) : 1.0f;
            float meanDfd = (sharpCount > 8) ? (sumOutDfd / sharpCount) : 1.0f;

            // Multi-cue fusion score for a true 3D wall/pillar crease:
            //   1. Straight photometric normal step (coherence > 0.72 & signedJump > 0.085)
            //   2. Homography parallax / grid foreshortening kink (meanOutPar > 1.8 or parRise > 0.9)
            //   3. Side-wall defocus / grazing blur (sharpRatio < 0.80 or DfD > 1.08)
            float cueCrease = (coherence > 0.70f && localGrad > 0.075f) ? (signedJump * coherence * 4.2f) : 0f;
            float cueParallax = (meanOutPar > 1.65f) ? ((meanOutPar - 1.3f) * 0.85f + parRise * 0.6f) : 0f;
            float cueBlur = (sharpRatio < 0.82f) ? ((0.85f - sharpRatio) * 2.4f) : 0f;
            if (meanDfd > 1.07f) cueBlur += (meanDfd - 1.05f) * 3.0f;

            // Require either strong geometric+blur evidence OR a crisp straight photometric crease backed by blur/parallax/albedo step
            float totalScore = 0f;
            if (cueCrease > 0.28f && (cueBlur > 0.14f || cueParallax > 0.25f || localGrad > 0.13f)) {
                totalScore = cueCrease + cueParallax + cueBlur;
            } else if (cueParallax > 0.85f && (cueBlur > 0.15f || cueCrease > 0.12f)) {
                totalScore = cueCrease + cueParallax + cueBlur;
            }

            if (totalScore > 0.52f && totalScore > bestScore) {
                bestScore = totalScore;
                bestGx = gx;
                // Once we pass the clear peak of the innermost wall crease, lock onto it so outer switchboards don't steal it
            } else if (bestScore > 0.65f && Math.abs(gx - bestGx) >= 6 && totalScore < bestScore * 0.6f) {
                break;
            }
        }

        if (bestGx != defaultEdge) {
            Log.i(TAG, (scanLeft ? "LEFT" : "RIGHT") + " sidewall/pillar seam locked at X="
                    + (bestGx * CELL_PX) + "px (score=" + String.format("%.2f", bestScore) + ")");
        }
        return bestGx;
    }

    private static int detectHorizontalWallSeam(
            float[][] normW, float[][] projW, float[][] projParallax,
            float[][] projSharp, float[][] projDfd,
            int beamThresh, float refSharp, boolean scanTop, int gxMin, int gxMax) {

        int defaultEdge = scanTop ? 1 : (GH - 2);
        int startGy = scanTop ? 40 : 68;
        int endGy = scanTop ? 3 : (GH - 4);
        int step = scanTop ? -1 : 1;

        int x0 = Math.max(8, gxMin + 4);
        int x1 = Math.min(GW - 9, gxMax - 4);
        if (x1 - x0 < 20) {
            x0 = 32; x1 = GW - 32;
        }

        int bestGy = defaultEdge;
        float bestScore = 0f;

        for (int gy = startGy; gy != endGy; gy += step) {
            int inStart = scanTop ? (gy + 1) : (gy - 4);
            int outStart = scanTop ? (gy - 4) : (gy + 1);
            if (inStart < 1 || inStart + 3 >= GH || outStart < 1 || outStart + 3 >= GH) continue;

            float sumInW = 0, sumOutW = 0, sumEdge = 0, consistentSign = 0;
            float sumOutPar = 0, sumOutSharp = 0;
            int sharpCnt = 0, activeCols = 0, unlitOuter = 0;

            for (int gx = x0; gx <= x1; gx++) {
                if (projW[gx][inStart + 1] < beamThresh) continue;
                activeCols++;
                if (projW[gx][outStart + 1] < beamThresh * 0.9f) unlitOuter++;

                float inV = 0.25f * (normW[gx][inStart] + normW[gx][inStart + 1] + normW[gx][inStart + 2] + normW[gx][inStart + 3]);
                float outV = 0.25f * (normW[gx][outStart] + normW[gx][outStart + 1] + normW[gx][outStart + 2] + normW[gx][outStart + 3]);
                sumInW += inV;
                sumOutW += outV;
                float d = inV - outV;
                sumEdge += Math.abs(d);
                consistentSign += d;
                sumOutPar += projParallax[gx][outStart + 1];
                if (!isInsideCentralAnchorHalo(gx, outStart + 1)) {
                    sumOutSharp += projSharp[gx][outStart + 1];
                    sharpCnt++;
                }
            }

            if (activeCols < 18) continue;
            if (unlitOuter > activeCols * 0.65f) {
                return scanTop ? (gy + 1) : (gy - 1);
            }

            float coherence = Math.abs(consistentSign) / Math.max(1e-4f, sumEdge);
            float localGrad = Math.abs(sumInW - sumOutW) / Math.max(0.25f, sumInW);
            float meanPar = sumOutPar / activeCols;
            float sharpRatio = (sharpCnt > 8 && refSharp > 0.05f) ? ((sumOutSharp / sharpCnt) / refSharp) : 1.0f;

            float score = 0f;
            if (coherence > 0.72f && localGrad > 0.09f && (sharpRatio < 0.84f || meanPar > 1.8f || localGrad > 0.16f)) {
                score = localGrad * coherence * 4.0f + Math.max(0f, meanPar - 1.5f) * 0.7f + Math.max(0f, 0.85f - sharpRatio) * 2.0f;
            }
            if (score > 0.58f && score > bestScore) {
                bestScore = score;
                bestGy = gy;
            } else if (bestScore > 0.70f && Math.abs(gy - bestGy) >= 5 && score < bestScore * 0.6f) {
                break;
            }
        }
        if (bestGy != defaultEdge) {
            Log.i(TAG, (scanTop ? "TOP" : "BOTTOM") + " horizontal seam locked at Y="
                    + (bestGy * CELL_PX) + "px (score=" + String.format("%.2f", bestScore) + ")");
        }
        return bestGy;
    }

    /**
     * Exact O(GW * GH) monotonic-stack largest 16:9 unobstructed rectangle solver,
     * weighted slightly toward optical center to maximize lens corner sharpness.
     */
    private static int[] findOptimal16x9Rect(boolean[][] valid, int gxMin, int gxMax, int gyMin, int gyMax) {
        int[] heights = new int[GW];
        int[] stack = new int[GW + 1];

        double bestScore = -1.0;
        int bestL = Math.max(0, gxMin), bestT = Math.max(0, gyMin);
        int bestR = Math.min(GW - 1, gxMax), bestB = Math.min(GH - 1, gyMax);

        for (int gy = 0; gy < GH; gy++) {
            for (int gx = 0; gx < GW; gx++) {
                heights[gx] = valid[gx][gy] ? (heights[gx] + 1) : 0;
            }
            int top = -1;
            for (int gx = 0; gx <= GW; gx++) {
                int h = (gx == GW) ? 0 : heights[gx];
                while (top >= 0 && h < heights[stack[top]]) {
                    int rectH = heights[stack[top--]];
                    int rectL = (top < 0) ? 0 : (stack[top] + 1);
                    int rectR = gx - 1;
                    int rectW = rectR - rectL + 1;
                    int rectT = gy - rectH + 1;
                    int rectB = gy;

                    // Fit largest 16:9 rectangle inside [rectL..rectR] x [rectT..rectB]
                    int w16 = Math.min(rectW, (rectH * 16) / 9);
                    int h9 = (w16 * 9) / 16;
                    if (h9 < 18 || w16 < 32) continue;
                    w16 = (h9 * 16) / 9;

                    // Slide the 16:9 box inside the free box toward projector center (96, 54) for minimal lens blur!
                    int idealL = Math.round(GW * 0.5f - w16 * 0.5f);
                    int subL = clamp(idealL, rectL, rectR - w16 + 1);
                    int subR = subL + w16 - 1;

                    int idealT = Math.round(GH * 0.5f - h9 * 0.5f);
                    int subT = clamp(idealT, rectT, rectB - h9 + 1);
                    int subB = subT + h9 - 1;

                    double area = (double) w16 * h9;
                    double cx = (subL + subR) * 0.5;
                    double cy = (subT + subB) * 0.5;
                    double offAxisDist = Math.hypot((cx - GW * 0.5) / GW, (cy - GH * 0.5) / GH);
                    // Primary objective: maximize unobstructed 16:9 area; tie-break: stay near optical center
                    double score = area * (1.0 - 0.06 * offAxisDist);
                    if (score > bestScore) {
                        bestScore = score;
                        bestL = subL;
                        bestT = subT;
                        bestR = subR;
                        bestB = subB;
                    }
                }
                stack[++top] = gx;
            }
        }
        return new int[] { bestL, bestT, bestR, bestB };
    }

    private static List<Blob> detectBlobs(int[] D2, int[] D3, int thresh) {
        boolean[] visited = new boolean[CAM_N];
        int[] queue = new int[4096];
        List<Blob> out = new ArrayList<>(128);

        for (int v = 4; v < CAM_H - 4; v++) {
            int rowOff = v * CAM_W;
            for (int u = 4; u < CAM_W - 4; u++) {
                int idx = rowOff + u;
                if (D2[idx] < thresh || visited[idx]) continue;

                int head = 0, tail = 0;
                queue[tail++] = idx;
                visited[idx] = true;

                double sumW = 0, sumU = 0, sumV = 0, sumD3 = 0;
                int peak = 0, area = 0;
                int minU = u, maxU = u, minV = v, maxV = v;

                while (head < tail) {
                    int cur = queue[head++];
                    int cv = cur / CAM_W;
                    int cu = cur - cv * CAM_W;
                    int val = D2[cur];
                    area++;
                    sumW += val;
                    sumU += cu * (double) val;
                    sumV += cv * (double) val;
                    sumD3 += D3[cur];
                    if (val > peak) peak = val;
                    if (cu < minU) minU = cu;
                    if (cu > maxU) maxU = cu;
                    if (cv < minV) minV = cv;
                    if (cv > maxV) maxV = cv;

                    if (tail + 4 < queue.length) {
                        int n1 = cur - 1, n2 = cur + 1, n3 = cur - CAM_W, n4 = cur + CAM_W;
                        if (cu > 2 && !visited[n1] && D2[n1] >= thresh) { visited[n1] = true; queue[tail++] = n1; }
                        if (cu < CAM_W - 3 && !visited[n2] && D2[n2] >= thresh) { visited[n2] = true; queue[tail++] = n2; }
                        if (cv > 2 && !visited[n3] && D2[n3] >= thresh) { visited[n3] = true; queue[tail++] = n3; }
                        if (cv < CAM_H - 3 && !visited[n4] && D2[n4] >= thresh) { visited[n4] = true; queue[tail++] = n4; }
                    }
                }

                int bw = maxU - minU + 1;
                int bh = maxV - minV + 1;
                // Expected 28x28 projector dot -> ~4x4 to 14x14 camera pixels
                if (area >= 4 && area <= 260 && bw <= 24 && bh <= 24 && bw <= bh * 3 && bh <= bw * 3) {
                    Blob b = new Blob();
                    b.u = (float) (sumU / sumW);
                    b.v = (float) (sumV / sumW);
                    b.area = area;
                    b.peakD2 = peak;
                    b.meanD3 = (float) (sumD3 / area);
                    out.add(b);
                }
            }
        }
        return out;
    }

    /**
     * Identifies the L-triad {(6,3), (7,3), (6,4)} from Frame 3's exclusive central anchors,
     * then propagates outward across all walls using local step extrapolation.
     */
    private static int assignLattice(List<Blob> blobs, int[][] gridToBlob) {
        final int n = blobs.size();
        if (n < 6) return 0;

        // Score every ordered triple (iOrigin, iPlusX, iPlusY) for L-triad match:
        //   1. High D3 on all 3 triad members
        //   2. Nearly orthogonal ~equal-scale step vectors ex = P_x - P_o, ey = P_y - P_o
        //   3. Positive orientation det(ex, ey) > 0 (standard non-mirrored camera) or highest support
        //   4. Opposite neighbors P_o - ex and P_o - ey exist in D2 blobs with LOW D3 (white halo!)
        int bestO = -1, bestX = -1, bestY = -1;
        double bestTriadScore = -1.0;

        for (int i = 0; i < n; i++) {
            Blob bo = blobs.get(i);
            if (bo.meanD3 < 55f) continue;
            for (int j = 0; j < n; j++) {
                if (j == i) continue;
                Blob bx = blobs.get(j);
                if (bx.meanD3 < 55f) continue;
                float exU = bx.u - bo.u, exV = bx.v - bo.v;
                float lenX = (float) Math.hypot(exU, exV);
                if (lenX < 12f || lenX > 95f) continue;

                for (int k = 0; k < n; k++) {
                    if (k == i || k == j) continue;
                    Blob by = blobs.get(k);
                    if (by.meanD3 < 55f) continue;
                    float eyU = by.u - bo.u, eyV = by.v - bo.v;
                    float lenY = (float) Math.hypot(eyU, eyV);
                    if (lenY < 12f || lenY > 95f) continue;

                    float ratio = lenX / lenY;
                    if (ratio < 0.62f || ratio > 1.55f) continue;

                    float cosAng = (exU * eyU + exV * eyV) / (lenX * lenY);
                    if (Math.abs(cosAng) > 0.42f) continue;

                    // Verify opposite lattice neighbors (-X = (5,3) and -Y = (6,2)) exist in D2 and have LOW D3!
                    int minusX = findNearestBlob(blobs, bo.u - exU, bo.v - exV, lenX * 0.35f);
                    int minusY = findNearestBlob(blobs, bo.u - eyU, bo.v - eyV, lenY * 0.35f);
                    double haloBonus = 0.0;
                    if (minusX >= 0 && blobs.get(minusX).meanD3 < 45f) haloBonus += 80.0;
                    if (minusY >= 0 && blobs.get(minusY).meanD3 < 45f) haloBonus += 80.0;

                    // Check cross-orientation: in standard front camera view, +X is right and +Y is down (cross > 0)
                    float cross = exU * eyV - exV * eyU;
                    double orientWeight = (cross > 0) ? 1.15 : 0.90;

                    double score = orientWeight * (bo.meanD3 + bx.meanD3 + by.meanD3 + haloBonus
                            - Math.abs(cosAng) * 90.0 - Math.abs(lenX - lenY) * 1.5);
                    if (score > bestTriadScore) {
                        bestTriadScore = score;
                        bestO = i;
                        bestX = j;
                        bestY = k;
                    }
                }
            }
        }

        if (bestO < 0) {
            Log.w(TAG, "L-triad anchor not found via D3; attempting central geometric lattice seed.");
            int centerIdx = findNearestBlob(blobs, CAM_W * 0.5f, CAM_H * 0.5f, 120f);
            if (centerIdx < 0) return 0;
            Blob bo = blobs.get(centerIdx);
            int rightIdx = -1, downIdx = -1;
            float bestRx = 999f, bestDy = 999f;
            for (int i = 0; i < n; i++) {
                if (i == centerIdx) continue;
                Blob b = blobs.get(i);
                float du = b.u - bo.u, dv = b.v - bo.v;
                float dist = (float) Math.hypot(du, dv);
                if (dist >= 14f && dist <= 85f) {
                    if (du > Math.abs(dv) * 1.5f && dist < bestRx) { bestRx = dist; rightIdx = i; }
                    if (dv > Math.abs(du) * 1.5f && dist < bestDy) { bestDy = dist; downIdx = i; }
                }
            }
            if (rightIdx < 0 || downIdx < 0) return 0;
            bestO = centerIdx; bestX = rightIdx; bestY = downIdx;
        }

        // Seed BFS lattice assignment from {(6,3), (7,3), (6,4)}
        int oc = PatternOverlayView.CENTER_COL;
        int or = PatternOverlayView.CENTER_ROW;
        assignNode(blobs, gridToBlob, oc, or, bestO);
        assignNode(blobs, gridToBlob, oc + 1, or, bestX);
        assignNode(blobs, gridToBlob, oc, or + 1, bestY);

        int[] qCol = new int[PatternOverlayView.GRID_COLS * PatternOverlayView.GRID_ROWS * 2];
        int[] qRow = new int[PatternOverlayView.GRID_COLS * PatternOverlayView.GRID_ROWS * 2];
        int qHead = 0, qTail = 0;
        qCol[qTail] = oc; qRow[qTail++] = or;
        qCol[qTail] = oc + 1; qRow[qTail++] = or;
        qCol[qTail] = oc; qRow[qTail++] = or + 1;

        float baseStepX = (float) Math.hypot(
                blobs.get(bestX).u - blobs.get(bestO).u,
                blobs.get(bestX).v - blobs.get(bestO).v);
        float baseStepY = (float) Math.hypot(
                blobs.get(bestY).u - blobs.get(bestO).u,
                blobs.get(bestY).v - blobs.get(bestO).v);
        float globalExU = blobs.get(bestX).u - blobs.get(bestO).u;
        float globalExV = blobs.get(bestX).v - blobs.get(bestO).v;
        float globalEyU = blobs.get(bestY).u - blobs.get(bestO).u;
        float globalEyV = blobs.get(bestY).v - blobs.get(bestO).v;

        int[][] dirs = { {1, 0}, {-1, 0}, {0, 1}, {0, -1} };
        int matched = 3;

        while (qHead < qTail) {
            int c = qCol[qHead];
            int r = qRow[qHead++];
            Blob cur = blobs.get(gridToBlob[c][r]);

            for (int[] d : dirs) {
                int nc = c + d[0];
                int nr = r + d[1];
                if (nc < 0 || nc >= PatternOverlayView.GRID_COLS || nr < 0 || nr >= PatternOverlayView.GRID_ROWS) continue;
                if (gridToBlob[nc][nr] >= 0) continue;

                // Extrapolate locally from immediate back-neighbor so side-wall slope kinks still track cleanly!
                float stepU, stepV;
                int backC = c - d[0], backR = r - d[1];
                if (backC >= 0 && backC < PatternOverlayView.GRID_COLS
                        && backR >= 0 && backR < PatternOverlayView.GRID_ROWS
                        && gridToBlob[backC][backR] >= 0) {
                    Blob prev = blobs.get(gridToBlob[backC][backR]);
                    stepU = cur.u - prev.u;
                    stepV = cur.v - prev.v;
                } else {
                    stepU = d[0] * globalExU + d[1] * globalEyU;
                    stepV = d[0] * globalExV + d[1] * globalEyV;
                }

                float predU = cur.u + stepU;
                float predV = cur.v + stepV;
                float tol = Math.max(8f, 0.42f * (d[0] != 0 ? baseStepX : baseStepY));
                int cand = findNearestUnassignedBlob(blobs, predU, predV, tol);
                if (cand >= 0) {
                    assignNode(blobs, gridToBlob, nc, nr, cand);
                    qCol[qTail] = nc;
                    qRow[qTail++] = nr;
                    matched++;
                }
            }
        }
        return matched;
    }

    private static void assignNode(List<Blob> blobs, int[][] gridToBlob, int c, int r, int idx) {
        gridToBlob[c][r] = idx;
        Blob b = blobs.get(idx);
        b.assignedCol = c;
        b.assignedRow = r;
    }

    private static int findNearestBlob(List<Blob> blobs, float u, float v, float maxDist) {
        int best = -1;
        float bestD2 = maxDist * maxDist;
        for (int i = 0; i < blobs.size(); i++) {
            Blob b = blobs.get(i);
            float du = b.u - u, dv = b.v - v;
            float d2 = du * du + dv * dv;
            if (d2 < bestD2) {
                bestD2 = d2;
                best = i;
            }
        }
        return best;
    }

    private static int findNearestUnassignedBlob(List<Blob> blobs, float u, float v, float maxDist) {
        int best = -1;
        float bestD2 = maxDist * maxDist;
        for (int i = 0; i < blobs.size(); i++) {
            Blob b = blobs.get(i);
            if (b.assignedCol >= 0) continue;
            float du = b.u - u, dv = b.v - v;
            float d2 = du * du + dv * dv;
            if (d2 < bestD2) {
                bestD2 = d2;
                best = i;
            }
        }
        return best;
    }

    private static float[] computeHorizontalAcutance(int[] ySharp, int[] W, int beamThresh, int normFloor) {
        float[] raw = new float[CAM_N];
        for (int v = 2; v < CAM_H - 2; v++) {
            int off = v * CAM_W;
            for (int u = 2; u < CAM_W - 2; u++) {
                int i = off + u;
                if (W[i] < beamThresh) continue;
                int g1 = Math.abs(ySharp[i + 1] - ySharp[i - 1]);
                int g2 = Math.abs(ySharp[i + 2] - ySharp[i - 2]);
                raw[i] = Math.max(g1, g2 * 0.7f) / (float) Math.max(W[i], normFloor);
            }
        }
        // 5x5 local box average to convert periodic stripe gradients into smooth envelope modulation S(u,v)
        float[] tmp = new float[CAM_N];
        float[] out = new float[CAM_N];
        for (int v = 2; v < CAM_H - 2; v++) {
            int off = v * CAM_W;
            for (int u = 2; u < CAM_W - 2; u++) {
                tmp[off + u] = 0.2f * (raw[off + u - 2] + raw[off + u - 1] + raw[off + u] + raw[off + u + 1] + raw[off + u + 2]);
            }
        }
        for (int v = 2; v < CAM_H - 2; v++) {
            int off = v * CAM_W;
            for (int u = 2; u < CAM_W - 2; u++) {
                out[off + u] = 0.2f * (tmp[off - 2 * CAM_W + u] + tmp[off - CAM_W + u]
                        + tmp[off + u] + tmp[off + CAM_W + u] + tmp[off + 2 * CAM_W + u]);
            }
        }
        return out;
    }

    private static float interpolateGridParallax(float[][] dotPar, boolean[][] obs, float px, float py) {
        float fc = (px - PatternOverlayView.GRID_X0) / PatternOverlayView.GRID_STEP_X;
        float fr = (py - PatternOverlayView.GRID_Y0) / PatternOverlayView.GRID_STEP_Y;
        int c0 = clamp((int) Math.floor(fc), 0, PatternOverlayView.GRID_COLS - 2);
        int r0 = clamp((int) Math.floor(fr), 0, PatternOverlayView.GRID_ROWS - 2);
        float tx = clampFloat(fc - c0, 0f, 1f);
        float ty = clampFloat(fr - r0, 0f, 1f);

        float sum = 0f, wSum = 0f;
        float[] wx = { 1f - tx, tx };
        float[] wy = { 1f - ty, ty };
        for (int dc = 0; dc <= 1; dc++) {
            for (int dr = 0; dr <= 1; dr++) {
                int c = c0 + dc, r = r0 + dr;
                if (obs[c][r]) {
                    float w = wx[dc] * wy[dr] + 0.05f;
                    sum += dotPar[c][r] * w;
                    wSum += w;
                }
            }
        }
        return wSum > 0f ? (sum / wSum) : 0f;
    }

    private static double[] fitBeamQuadFallbackHomography(int[] W, int beamThresh) {
        // Find 4 extreme illuminated corners of W > beamThresh via diagonal projections u+v, u-v
        double tlScore = 1e9, brScore = -1e9, trScore = -1e9, blScore = 1e9;
        double tlU = 0, tlV = 0, brU = 0, brV = 0, trU = 0, trV = 0, blU = 0, blV = 0;
        int count = 0;
        for (int v = 4; v < CAM_H - 4; v++) {
            int off = v * CAM_W;
            for (int u = 4; u < CAM_W - 4; u++) {
                if (W[off + u] < beamThresh * 1.4f) continue;
                count++;
                double s1 = u + v;
                double s2 = u - v;
                if (s1 < tlScore) { tlScore = s1; tlU = u; tlV = v; }
                if (s1 > brScore) { brScore = s1; brU = u; brV = v; }
                if (s2 > trScore) { trScore = s2; trU = u; trV = v; }
                if (s2 < blScore) { blScore = s2; blU = u; blV = v; }
            }
        }
        if (count < 800) return null;
        double[] sx = { 0, 1919, 1919, 0 };
        double[] sy = { 0, 0, 1079, 1079 };
        double[] du = { tlU, trU, brU, blU };
        double[] dv = { tlV, trV, brV, blV };
        return HomographySolver.solveLeastSquares(sx, sy, du, dv, 4);
    }

    private static boolean isInsideCentralAnchorHalo(int gx, int gy) {
        float px = (gx + 0.5f) * CELL_PX;
        float py = (gy + 0.5f) * CELL_PX;
        return px >= 770f && px <= 1150f && py >= 345f && py <= 735f;
    }

    private static float[][] boxSmooth(float[][] src, int radius) {
        float[][] tmp = new float[GW][GH];
        float[][] out = new float[GW][GH];
        for (int gx = 0; gx < GW; gx++) {
            for (int gy = 0; gy < GH; gy++) {
                float s = 0; int c = 0;
                for (int k = Math.max(0, gx - radius); k <= Math.min(GW - 1, gx + radius); k++) {
                    s += src[k][gy]; c++;
                }
                tmp[gx][gy] = s / c;
            }
        }
        for (int gx = 0; gx < GW; gx++) {
            for (int gy = 0; gy < GH; gy++) {
                float s = 0; int c = 0;
                for (int k = Math.max(0, gy - radius); k <= Math.min(GH - 1, gy + radius); k++) {
                    s += tmp[gx][k]; c++;
                }
                out[gx][gy] = s / c;
            }
        }
        return out;
    }

    private static boolean[][] morphClose1(boolean[][] src) {
        boolean[][] dil = new boolean[GW][GH];
        for (int x = 1; x < GW - 1; x++) {
            for (int y = 1; y < GH - 1; y++) {
                int trues = 0;
                for (int dx = -1; dx <= 1; dx++) {
                    for (int dy = -1; dy <= 1; dy++) {
                        if (src[x + dx][y + dy]) trues++;
                    }
                }
                dil[x][y] = src[x][y] || trues >= 6;
            }
        }
        return dil;
    }

    private static boolean[][] erode(boolean[][] src, int radius) {
        boolean[][] out = new boolean[GW][GH];
        for (int x = radius; x < GW - radius; x++) {
            for (int y = radius; y < GH - radius; y++) {
                boolean ok = true;
                for (int dx = -radius; dx <= radius && ok; dx++) {
                    for (int dy = -radius; dy <= radius; dy++) {
                        if (!src[x + dx][y + dy]) { ok = false; break; }
                    }
                }
                out[x][y] = ok;
            }
        }
        return out;
    }

    private static float percentileGrid(float[][] g, int x0, int x1, int y0, int y1, float q) {
        int cap = Math.max(1, (x1 - x0 + 1) * (y1 - y0 + 1));
        float[] vals = new float[cap];
        int n = 0;
        for (int x = Math.max(0, x0); x <= Math.min(GW - 1, x1); x++) {
            for (int y = Math.max(0, y0); y <= Math.min(GH - 1, y1); y++) {
                if (g[x][y] > 0f) vals[n++] = g[x][y];
            }
        }
        if (n == 0) return 0f;
        Arrays.sort(vals, 0, n);
        return vals[clamp((int) (n * q), 0, n - 1)];
    }

    private static float sampleBilinearInt(int[] img, float u, float v) {
        int u0 = (int) u, v0 = (int) v;
        float fu = u - u0, fv = v - v0;
        int off = v0 * CAM_W + u0;
        float a = img[off] * (1f - fu) + img[off + 1] * fu;
        float b = img[off + CAM_W] * (1f - fu) + img[off + CAM_W + 1] * fu;
        return a * (1f - fv) + b * fv;
    }

    private static float sampleBilinearFloat(float[] img, float u, float v) {
        int u0 = (int) u, v0 = (int) v;
        float fu = u - u0, fv = v - v0;
        int off = v0 * CAM_W + u0;
        float a = img[off] * (1f - fu) + img[off + 1] * fu;
        float b = img[off + CAM_W] * (1f - fu) + img[off + CAM_W + 1] * fu;
        return a * (1f - fv) + b * fv;
    }

    private static int clamp(int v, int lo, int hi) {
        return v < lo ? lo : (v > hi ? hi : v);
    }

    private static float clampFloat(float v, float lo, float hi) {
        return v < lo ? lo : (v > hi ? hi : v);
    }

    private static void saveDiagnosticArtifact(
            int[] W, List<Blob> blobs, int[][] gridToBlob, float[][] dotParallax, double[] Hback,
            boolean[][] safeValid, int leftGx, int rightGx, int topGy, int botGy,
            int lPx, int tPx, int rPx, int bPx, int[] insets, String summary) {
        try {
            // Side-by-side 1280x480 diagnostic PNG:
            //   Left 640x480: Camera ambient-canceled W(u,v) + detected fiducial dots + projected solution quad
            //   Right 640x480: Projector-space 192x108 valid mask + sidewall seams (cyan) + 16:9 box (yellow)
            Bitmap bmp = Bitmap.createBitmap(1280, 480, Bitmap.Config.ARGB_8888);
            int[] px = new int[CAM_N];
            for (int i = 0; i < CAM_N; i++) {
                int g = clamp(W[i] * 2, 0, 255);
                px[i] = 0xFF000000 | (g << 16) | (g << 8) | g;
            }
            bmp.setPixels(px, 0, CAM_W, 0, 0, CAM_W, CAM_H);

            Canvas cv = new Canvas(bmp);
            Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
            for (int c = 0; c < PatternOverlayView.GRID_COLS; c++) {
                for (int r = 0; r < PatternOverlayView.GRID_ROWS; r++) {
                    int bi = gridToBlob[c][r];
                    if (bi < 0) continue;
                    Blob b = blobs.get(bi);
                    p.setStyle(Paint.Style.FILL);
                    p.setColor(dotParallax[c][r] > 2.2f ? 0xFFFF5252 : 0xFF00E676);
                    cv.drawCircle(b.u, b.v, 4f, p);
                }
            }

            // Draw mapped 16:9 solution quad on left camera panel
            double[] q0 = new double[2], q1 = new double[2], q2 = new double[2], q3 = new double[2];
            HomographySolver.project(Hback, lPx, tPx, q0);
            HomographySolver.project(Hback, rPx, tPx, q1);
            HomographySolver.project(Hback, rPx, bPx, q2);
            HomographySolver.project(Hback, lPx, bPx, q3);
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(2.5f);
            p.setColor(0xFFFFEA00);
            cv.drawLine((float) q0[0], (float) q0[1], (float) q1[0], (float) q1[1], p);
            cv.drawLine((float) q1[0], (float) q1[1], (float) q2[0], (float) q2[1], p);
            cv.drawLine((float) q2[0], (float) q2[1], (float) q3[0], (float) q3[1], p);
            cv.drawLine((float) q3[0], (float) q3[1], (float) q0[0], (float) q0[1], p);

            // Right panel (x offset 640): projector space 600x338 inside 640x480
            float ox = 660f, oy = 50f, sw = 600f, sh = 338f;
            p.setStyle(Paint.Style.FILL);
            p.setColor(0xFF141A22);
            cv.drawRect(640, 0, 1280, 480, p);

            float cw = sw / GW, ch = sh / GH;
            for (int gx = 0; gx < GW; gx++) {
                for (int gy = 0; gy < GH; gy++) {
                    p.setColor(safeValid[gx][gy] ? 0xFF264E36 : 0xFF4A1E24);
                    cv.drawRect(ox + gx * cw, oy + gy * ch, ox + (gx + 1) * cw + 0.5f, oy + (gy + 1) * ch + 0.5f, p);
                }
            }

            // Detected alcove wall seams in cyan
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(2.5f);
            p.setColor(0xFF00E5FF);
            cv.drawLine(ox + leftGx * cw, oy, ox + leftGx * cw, oy + sh, p);
            cv.drawLine(ox + (rightGx + 1) * cw, oy, ox + (rightGx + 1) * cw, oy + sh, p);
            cv.drawLine(ox, oy + topGy * ch, ox + sw, oy + topGy * ch, p);
            cv.drawLine(ox, oy + (botGy + 1) * ch, ox + sw, oy + (botGy + 1) * ch, p);

            // Final 16:9 rectangle in bright yellow
            p.setColor(0xFFFFEA00);
            p.setStrokeWidth(3f);
            cv.drawRect(
                    ox + (lPx / 1920f) * sw,
                    oy + (tPx / 1080f) * sh,
                    ox + (rPx / 1920f) * sw,
                    oy + (bPx / 1080f) * sh, p);

            p.setStyle(Paint.Style.FILL);
            p.setColor(Color.WHITE);
            p.setTextSize(15f);
            cv.drawText(summary, 20f, 462f, p);
            cv.drawText("Projector 1920x1080 Map (Green=Safe Back Wall, Red=Sidewall/Obstacle, Cyan=Alcove Seam, Yellow=16:9 Fit)",
                    655f, 32f, p);

            File pngFile = new File("/sdcard/alcove_debug.png");
            try (FileOutputStream fos = new FileOutputStream(pngFile)) {
                bmp.compress(Bitmap.CompressFormat.PNG, 100, fos);
            }
            bmp.recycle();

            try (FileWriter fw = new FileWriter("/sdcard/alcove_last_report.txt", false)) {
                fw.write(summary + "\n");
                fw.write("setkey=" + Arrays.toString(insets) + "\n");
            }
        } catch (Throwable t) {
            Log.w(TAG, "Failed saving diagnostic PNG: " + t.getMessage());
        }
    }
}

package com.hysd.hyscreen;

import android.content.ComponentName;
import android.content.Context;
import android.content.Intent;
import android.content.ServiceConnection;
import android.graphics.PixelFormat;
import android.os.Build;
import android.os.Handler;
import android.os.IBinder;
import android.os.Looper;
import android.os.SystemProperties;
import android.util.Log;
import android.view.Gravity;
import android.view.WindowManager;

import com.hysd.hyscreen.alcove.AlcoveVisionPipeline;
import com.hysd.hyscreen.alcove.PatternOverlayView;
import com.hysd.vafocus.HYSDVAF2;

import java.util.Arrays;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Upgraded VAF2S service extending the preserved stock VAF2T implementation.
 *
 * - Intercepts obstacle avoidance, screen align, and auto-keystone triggers with a fast
 *   4-frame structured-light + sidewall/alcove crease + defocus + 16:9 auto-resize pipeline.
 * - Preserves 100% compatibility with factory calibration, ToF test modes, and pure motor AF
 *   by delegating non-alcove modes directly to super (VAF2T).
 * - Runtime escape hatch: `setprop persist.hysd.turbo_disable 1` reverts immediately to stock VAF2T.
 */
public class VAF2S extends VAF2T {
    private static final String TAG = "TurboAlcoveVAF2S";
    private static final int YUYV_FRAME_BYTES = AlcoveVisionPipeline.CAM_W * AlcoveVisionPipeline.CAM_H * 2;

    private final AtomicBoolean running = new AtomicBoolean(false);
    private final Handler mainHandler = new Handler(Looper.getMainLooper());

    @Override
    public int onStartCommand(final Intent intent, int flags, int startId) {
        if ("1".equals(SystemProperties.get("persist.hysd.turbo_disable", "0"))) {
            Log.i(TAG, "persist.hysd.turbo_disable=1 -> delegating to stock VAF2T");
            return super.onStartCommand(intent, flags, startId);
        }

        if (intent == null) {
            return START_NOT_STICKY;
        }

        final int mode = intent.getIntExtra("mode", 1);
        final int dmodeProp = SystemProperties.getInt("persist.htp.hysd.dmode", 3);
        final int dmode = intent.getIntExtra("dmode", dmodeProp);
        final int afSwitch = intent.getIntExtra("afswitch", SystemProperties.getInt("persist.sys.autofocus", 0));
        final int keySwitch = intent.getIntExtra("keyswitch", SystemProperties.getInt("persist.sys.autotrapezoid", 1));
        final boolean obsOpen = "1".equals(SystemProperties.get("persist.hysd.obs_open", "1"));
        final boolean mbOpen = "1".equals(SystemProperties.get("persist.hysd.mb_open", "1"));

        Log.i(TAG, "onStartCommand mode=" + mode + " dmode=" + dmode + " af=" + afSwitch + " key=" + keySwitch);

        // Instant <20ms keystone reset for mode 5 / 6
        if (mode == 5 || mode == 6) {
            new Thread(new Runnable() {
                @Override
                public void run() {
                    resetKeystoneFast();
                }
            }, "TurboKeyReset").start();
            return START_NOT_STICKY;
        }

        // Delegate factory calibration, ToF hardware tests, and pure autofocus-only (mode==2) to stock VAF2T
        boolean isTurboCandidate =
                (mode == 3 || mode == 7 || mode == 99)
                || ((mode == 1 || mode == 4 || mode == 20 || mode == 21)
                    && (dmode > 0 || obsOpen || mbOpen || keySwitch == 1));

        if (!isTurboCandidate) {
            Log.i(TAG, "Delegating non-obstacle mode=" + mode + " to stock VAF2T");
            return super.onStartCommand(intent, flags, startId);
        }

        if (!running.compareAndSet(false, true)) {
            Log.w(TAG, "TurboAlcove scan already in progress; ignoring duplicate start.");
            return START_NOT_STICKY;
        }

        final boolean runCenterAfFirst = (afSwitch == 1 && mode != 3 && mode != 7)
                || intent.getIntExtra("force_af", 0) == 1;
        final boolean runDfdMotorBracket =
                "1".equals(SystemProperties.get("persist.hysd.alcove.dfd", "0"))
                || intent.getIntExtra("dfd", 0) == 1;

        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    executeTurboAlcovePipeline(runCenterAfFirst, runDfdMotorBracket);
                } finally {
                    running.set(false);
                }
            }
        }, "TurboAlcoveWorker").start();

        return START_NOT_STICKY;
    }

    private void resetKeystoneFast() {
        ServiceHolder holder = bindHysdClient(1500);
        try {
            if (holder.service != null) {
                holder.service.setkey(0, 0, 0, 0, 0, 0, 0, 0);
                holder.service.finishkey(1, 1, 0);
            }
        } catch (Throwable t) {
            Log.e(TAG, "Fast resetkey failed", t);
        } finally {
            holder.unbind(this);
            stopSelf();
        }
    }

    private void executeTurboAlcovePipeline(boolean runCenterAfFirst, boolean runDfdBracket) {
        final long tStart = System.nanoTime();
        SystemProperties.set("com.hysd.focusing", "1");
        SystemProperties.set("keystatus.hysd.sf", "0");

        ServiceHolder aidl = bindHysdClient(2000);
        PatternOverlayView overlay = null;
        WindowManager wm = (WindowManager) getSystemService(Context.WINDOW_SERVICE);
        int[] savedKey = null;
        boolean camOpened = false;

        try {
            if (aidl.service == null) {
                Log.e(TAG, "Could not bind com.hysd.client.VAFclientapi");
                return;
            }

            savedKey = aidl.service.getkey();
            // Reset to full 1920x1080 panel so structured-light pattern illuminates the entire wall & sidewalls
            aidl.service.setkey(0, 0, 0, 0, 0, 0, 0, 0);

            overlay = attachOverlay(wm);
            if (overlay == null) {
                Log.e(TAG, "Could not attach full-screen PatternOverlayView");
                return;
            }

            final int camId = SystemProperties.getInt("persist.keystone.camid", 0);
            int openRc = HYSDVAF2.s0cam(camId, 2);
            if (openRc != 1) {
                Log.w(TAG, "s0cam(" + camId + ", 2) returned " + openRc + "; retrying once after 60ms...");
                sleepQuiet(60);
                openRc = HYSDVAF2.s0cam(camId, 2);
            }
            camOpened = true;

            byte[] yuyv = new byte[YUYV_FRAME_BYTES];
            // Flush initial stale V4L2 ring buffers while screen settles to full 1920x1080
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_ANCHOR_SHARPNESS, 160);
            HYSDVAF2.s1cam(yuyv);
            HYSDVAF2.s1cam(yuyv);

            // Optional fast center-only back-wall autofocus (ignores closer sidewalls!)
            if (runCenterAfFirst) {
                runFastCenterBackWallAutofocus(aidl.service, yuyv);
            }

            int[] yDark = new int[AlcoveVisionPipeline.CAM_N];
            int[] yWhite = new int[AlcoveVisionPipeline.CAM_N];
            int[] yGrid = new int[AlcoveVisionPipeline.CAM_N];
            int[] yAnchorSharp = new int[AlcoveVisionPipeline.CAM_N];
            int[] yNearSharp = null;

            // Frame 3 first (already displayed above during initial buffer flush -> saves 1 full switch!)
            captureSettledLuma(yuyv, yAnchorSharp, 2);

            // Optional 2-step focus-motor Depth-from-Defocus bracket (+85ms forward nudge, then exact return)
            if (runDfdBracket) {
                yNearSharp = new int[AlcoveVisionPipeline.CAM_N];
                aidl.service.motorf();
                sleepQuiet(85);
                aidl.service.motors();
                captureSettledLuma(yuyv, yNearSharp, 2);
                aidl.service.motorb();
                sleepQuiet(90);
                aidl.service.motors();
                sleepQuiet(25);
            }

            // Frame 0: DARK (ambient cancellation baseline)
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_DARK, 150);
            sleepQuiet(38);
            captureSettledLuma(yuyv, yDark, 3);

            // Frame 1: WHITE (irradiance & photometric sidewall crease map)
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_WHITE, 150);
            sleepQuiet(38);
            captureSettledLuma(yuyv, yWhite, 3);

            // Frame 2: 91-dot fiducial lattice
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_GRID_91, 150);
            sleepQuiet(38);
            captureSettledLuma(yuyv, yGrid, 3);

            // Release V4L2 camera immediately before running CPU solver so hardware is free!
            HYSDVAF2.s2cam();
            camOpened = false;

            long captureMs = (System.nanoTime() - tStart) / 1_000_000L;
            float minArea = Float.parseFloat(SystemProperties.get("persist.hysd.alcove.min_area", "0.24"));
            boolean saveDebug = !"0".equals(SystemProperties.get("persist.hysd.alcove.debug", "1"));

            AlcoveVisionPipeline.Result res = AlcoveVisionPipeline.solve(
                    yDark, yWhite, yGrid, yAnchorSharp, yNearSharp, minArea, saveDebug);

            long totalMs = (System.nanoTime() - tStart) / 1_000_000L;
            if (res.success) {
                int[] k = res.insets;
                aidl.service.setkey(k[0], k[1], k[2], k[3], k[4], k[5], k[6], k[7]);
                aidl.service.finishkey(1, 1, 0);
                SystemProperties.set("keystatus.hysd.sf", "1");
                SystemProperties.set("keystatus.hysd.keyresult", "1");

                String hud = String.format("Alcove Fit %dx%d (%dms)",
                        (res.rectRightPx - res.rectLeftPx),
                        (res.rectBottomPx - res.rectTopPx),
                        totalMs);
                Log.i(TAG, "SUCCESS total=" + totalMs + "ms (capture=" + captureMs + "ms, solve=" + res.solveTimeMs
                        + "ms) insets=" + Arrays.toString(k));

                if (!"0".equals(SystemProperties.get("persist.hysd.alcove.hud", "1"))) {
                    overlay.showConfirmHud(k, hud);
                    sleepQuiet(260);
                }
            } else {
                Log.w(TAG, "Alcove solver did not converge (" + res.summary + "); restoring previous keystone.");
                if (savedKey != null && savedKey.length == 8) {
                    aidl.service.setkey(savedKey[0], savedKey[1], savedKey[2], savedKey[3],
                            savedKey[4], savedKey[5], savedKey[6], savedKey[7]);
                }
                aidl.service.finishkey(1, 0, -1);
            }
        } catch (Throwable t) {
            Log.e(TAG, "TurboAlcove pipeline error", t);
            try {
                if (savedKey != null && savedKey.length == 8 && aidl.service != null) {
                    aidl.service.setkey(savedKey[0], savedKey[1], savedKey[2], savedKey[3],
                            savedKey[4], savedKey[5], savedKey[6], savedKey[7]);
                }
            } catch (Throwable ignored) {}
        } finally {
            if (camOpened) {
                try { HYSDVAF2.s2cam(); } catch (Throwable ignored) {}
            }
            detachOverlay(wm, overlay);
            aidl.unbind(this);
            SystemProperties.set("com.hysd.focusing", "0");
            stopSelf();
        }
    }

    /**
     * Drains V4L2 queued buffers until consecutive global luma mean stabilizes (guaranteed fresh frame).
     */
    private static void captureSettledLuma(byte[] yuyv, int[] outY, int minReads) {
        double prevMean = -999.0;
        for (int attempt = 0; attempt < minReads + 3; attempt++) {
            int rc = HYSDVAF2.s1cam(yuyv);
            if (rc < 0) {
                sleepQuiet(15);
                continue;
            }
            double mean = sampleFastMeanLuma(yuyv);
            if (attempt >= minReads - 1 && Math.abs(mean - prevMean) < 2.2) {
                break;
            }
            prevMean = mean;
        }
        AlcoveVisionPipeline.extractLuma(yuyv, outY);
    }

    private static double sampleFastMeanLuma(byte[] yuyv) {
        long sum = 0;
        int cnt = 0;
        for (int i = 0; i < YUYV_FRAME_BYTES; i += 64) {
            sum += (yuyv[i] & 0xFF);
            cnt++;
        }
        return cnt > 0 ? (sum / (double) cnt) : 0.0;
    }

    /**
     * Closed-loop hill-climbing autofocus evaluated strictly on the central 160x120 back-wall ROI
     * so closer side walls or pillars never bias focus distance.
     */
    private static void runFastCenterBackWallAutofocus(HYSDInterface svc, byte[] yuyv) {
        try {
            HYSDVAF2.s1cam(yuyv);
            double s0 = AlcoveVisionPipeline.computeCenterFocusScore(yuyv);

            // Probe forward 70ms
            svc.motorf();
            sleepQuiet(70);
            svc.motors();
            HYSDVAF2.s1cam(yuyv);
            HYSDVAF2.s1cam(yuyv);
            double sFwd = AlcoveVisionPipeline.computeCenterFocusScore(yuyv);

            boolean goForward = sFwd >= s0 * 1.02;
            if (!goForward) {
                // Step back past origin
                svc.motorb();
                sleepQuiet(110);
                svc.motors();
                HYSDVAF2.s1cam(yuyv);
                HYSDVAF2.s1cam(yuyv);
                double sBack = AlcoveVisionPipeline.computeCenterFocusScore(yuyv);
                if (sBack < s0 * 0.99) {
                    // Already at peak -> return to s0 (+40ms forward) and finish in ~220ms!
                    svc.motorf();
                    sleepQuiet(40);
                    svc.motors();
                    return;
                }
            }

            double peak = Math.max(s0, sFwd);
            for (int step = 0; step < 8; step++) {
                if (goForward) svc.motorf(); else svc.motorb();
                sleepQuiet(55);
                svc.motors();
                HYSDVAF2.s1cam(yuyv);
                HYSDVAF2.s1cam(yuyv);
                double cur = AlcoveVisionPipeline.computeCenterFocusScore(yuyv);
                if (cur > peak) {
                    peak = cur;
                } else if (cur < peak * 0.95) {
                    // Backtrack 1 step to peak
                    if (goForward) svc.motorb(); else svc.motorf();
                    sleepQuiet(55);
                    svc.motors();
                    break;
                }
            }
        } catch (Throwable t) {
            Log.w(TAG, "Center AF skipped: " + t.getMessage());
            try { svc.motors(); } catch (Throwable ignored) {}
        }
    }

    private PatternOverlayView attachOverlay(final WindowManager wm) {
        if (wm == null) return null;
        final PatternOverlayView[] box = new PatternOverlayView[1];
        final CountDownLatch latch = new CountDownLatch(1);
        mainHandler.post(new Runnable() {
            @Override
            public void run() {
                try {
                    PatternOverlayView v = new PatternOverlayView(VAF2S.this);
                    int type = Build.VERSION.SDK_INT >= 26
                            ? WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY
                            : WindowManager.LayoutParams.TYPE_SYSTEM_ALERT;
                    int flags = WindowManager.LayoutParams.FLAG_FULLSCREEN
                            | WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN
                            | WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS
                            | WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE
                            | WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE
                            | WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON
                            | WindowManager.LayoutParams.FLAG_HARDWARE_ACCELERATED;
                    WindowManager.LayoutParams lp = new WindowManager.LayoutParams(
                            PatternOverlayView.PROJ_W,
                            PatternOverlayView.PROJ_H,
                            type, flags, PixelFormat.OPAQUE);
                    lp.gravity = Gravity.TOP | Gravity.LEFT;
                    if (Build.VERSION.SDK_INT >= 28) {
                        lp.layoutInDisplayCutoutMode =
                                WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_SHORT_EDGES;
                    }
                    wm.addView(v, lp);
                    box[0] = v;
                } catch (Throwable t) {
                    Log.e(TAG, "Failed adding overlay window", t);
                } finally {
                    latch.countDown();
                }
            }
        });
        try {
            latch.await(1000, TimeUnit.MILLISECONDS);
        } catch (InterruptedException ignored) {
            Thread.currentThread().interrupt();
        }
        return box[0];
    }

    private void detachOverlay(final WindowManager wm, final PatternOverlayView view) {
        if (wm == null || view == null) return;
        final CountDownLatch latch = new CountDownLatch(1);
        mainHandler.post(new Runnable() {
            @Override
            public void run() {
                try {
                    wm.removeViewImmediate(view);
                } catch (Throwable ignored) {
                } finally {
                    latch.countDown();
                }
            }
        });
        try {
            latch.await(500, TimeUnit.MILLISECONDS);
        } catch (InterruptedException ignored) {
            Thread.currentThread().interrupt();
        }
    }

    private ServiceHolder bindHysdClient(long timeoutMs) {
        final ServiceHolder holder = new ServiceHolder();
        String pkg = SystemProperties.get("persist.hysd.aidl.package", "com.hysd.client");
        String cls = SystemProperties.get("persist.hysd.aidl.class", "com.hysd.client.VAFclientapi");
        Intent i = new Intent();
        i.setAction(pkg);
        i.addCategory(Intent.CATEGORY_DEFAULT);
        i.setComponent(new ComponentName(pkg, cls));
        holder.bound = bindService(i, holder.conn, Context.BIND_AUTO_CREATE);
        if (holder.bound) {
            try {
                holder.latch.await(timeoutMs, TimeUnit.MILLISECONDS);
            } catch (InterruptedException ignored) {
                Thread.currentThread().interrupt();
            }
        }
        return holder;
    }

    private static void sleepQuiet(long ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException ignored) {
            Thread.currentThread().interrupt();
        }
    }

    private static final class ServiceHolder {
        final CountDownLatch latch = new CountDownLatch(1);
        volatile HYSDInterface service;
        volatile boolean bound;

        final ServiceConnection conn = new ServiceConnection() {
            @Override
            public void onServiceConnected(ComponentName name, IBinder binder) {
                service = HYSDInterface.Stub.asInterface(binder);
                latch.countDown();
            }

            @Override
            public void onServiceDisconnected(ComponentName name) {
                service = null;
            }
        };

        void unbind(Context ctx) {
            if (bound) {
                try { ctx.unbindService(conn); } catch (Throwable ignored) {}
                bound = false;
            }
        }
    }
}

