+    private static float sampleBilinearInt(int[] img, float u, float v) {
+        int u0 = (int) u, v0 = (int) v;
+        float fu = u - u0, fv = v - v0;
+        int off = v0 * CAM_W + u0;
+        float a = img[off] * (1f - fu) + img[off + 1] * fu;
+        float b = img[off + CAM_W] * (1f - fu) + img[off + CAM_W + 1] * fu;
+        return a * (1f - fv) + b * fv;
+    }
