arguments.file_text:
package com.hysd.hyscreen.alcove;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.view.View;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

/**
 * Unclipped mid-gray (RGB 78,78,78) 3-frame structured-light renderer for 1920x1080.
 * Avoids 255 CMOS blooming on high-lumen projectors while keeping >120 DN dot modulation.
 */
public final class PatternOverlayView extends View {
    public static final int PROJ_W = 1920;
    public static final int PROJ_H = 1080;

    // 13 x 7 coded fiducial lattice covering [96..1824] x [90..990]
    public static final int GRID_COLS = 13;
    public static final int GRID_ROWS = 7;
    public static final int GRID_X0 = 96;
    public static final int GRID_Y0 = 90;
    public static final int GRID_STEP_X = 144;
    public static final int GRID_STEP_Y = 150;
    public static final int DOT_HALF = 18; // 36x36 projector px (~9x9 camera px)

    public static final int CENTER_COL = 6; // X = 960
    public static final int CENTER_ROW = 3; // Y = 540

    // Unsaturated mid-gray level (~8% linear luminance) prevents CMOS 255 saturation
    public static final int ILLUM_GRAY = Color.rgb(82, 82, 82);

    public static final int MODE_DARK = 0;
    public static final int MODE_FLAT_GRAY = 1;
    public static final int MODE_CODED_GRID = 2;
    public static final int MODE_HUD_CONFIRM = 3;

    private volatile int mode = MODE_CODED_GRID;
    private volatile CountDownLatch drawLatch;
    private volatile String hudMessage = "";

    private final Paint blackPaint = new Paint();
    private final Paint borderPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final Paint textPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final Paint badgePaint = new Paint(Paint.ANTI_ALIAS_FLAG);

    public PatternOverlayView(Context context) {
        super(context);
        blackPaint.setColor(Color.BLACK);
        blackPaint.setStyle(Paint.Style.FILL);

        borderPaint.setColor(0xFF00E676);
        borderPaint.setStyle(Paint.Style.STROKE);
        borderPaint.setStrokeWidth(6f);

        badgePaint.setColor(0xCC101820);
        badgePaint.setStyle(Paint.Style.FILL);

        textPaint.setColor(Color.WHITE);
        textPaint.setTextSize(32f);
    }

    public static float dotProjX(int col) {
        return GRID_X0 + col * GRID_STEP_X;
    }

    public static float dotProjY(int row) {
        return GRID_Y0 + row * GRID_STEP_Y;
    }

    public void setPatternAndAwaitDraw(final int nextMode, long timeoutMs) {
        final CountDownLatch latch = new CountDownLatch(1);
        this.drawLatch = latch;
        this.mode = nextMode;
        post(new Runnable() {
            @Override
            public void run() {
                invalidate();
            }
        });
        try {
            latch.await(timeoutMs, TimeUnit.MILLISECONDS);
        } catch (InterruptedException ignored) {
            Thread.currentThread().interrupt();
        }
    }

    public void showConfirmHud(String msg) {
        this.hudMessage = (msg != null) ? msg : "";
        setPatternAndAwaitDraw(MODE_HUD_CONFIRM, 120);
    }

    @Override
    protected void onDraw(Canvas canvas) {
        final int w = getWidth() > 0 ? getWidth() : PROJ_W;
        final int h = getHeight() > 0 ? getHeight() : PROJ_H;
        final float sx = w / (float) PROJ_W;
        final float sy = h / (float) PROJ_H;

        final int m = this.mode;
        if (m == MODE_DARK) {
            canvas.drawColor(Color.BLACK);
        } else if (m == MODE_FLAT_GRAY) {
            canvas.drawColor(ILLUM_GRAY);
        } else if (m == MODE_CODED_GRID) {
            canvas.drawColor(ILLUM_GRAY);
            // 1. Draw 13x7 fiducial lattice with distinct shape-coded origin triad:
            //    - (6,3) Origin: large 58x58 square (~2.6x area of normal dot)
            //    - (7,3) +X axis: wide 68x28 horizontal bar
            //    - (6,4) +Y axis: tall 28x68 vertical bar
            //    - All other 88 nodes: 36x36 squares
            for (int r = 0; r < GRID_ROWS; r++) {
                float cy = dotProjY(r) * sy;
                for (int c = 0; c < GRID_COLS; c++) {
                    float cx = dotProjX(c) * sx;
                    float hw = DOT_HALF * sx;
                    float hh = DOT_HALF * sy;
                    if (c == CENTER_COL && r == CENTER_ROW) {
                        hw = 29f * sx;
                        hh = 29f * sy;
                    } else if (c == CENTER_COL + 1 && r == CENTER_ROW) {
                        hw = 34f * sx;
                        hh = 14f * sy;
                    } else if (c == CENTER_COL && r == CENTER_ROW + 1) {
                        hw = 14f * sx;
                        hh = 34f * sy;
                    }
                    canvas.drawRect(cx - hw, cy - hh, cx + hw, cy + hh, blackPaint);
                }
            }
            // 2. Draw vertical 8px acutance/defocus grating strips strictly inside the 6 horizontal
            //    inter-row corridors (midway between dot rows, height 48px) so dots stay 100% isolated!
            float barW = Math.max(2f, 8f * sx);
            float period = barW * 2f;
            for (int r = 0; r < GRID_ROWS - 1; r++) {
                float stripTop = (dotProjY(r) + 51f) * sy;
                float stripBot = (dotProjY(r + 1) - 51f) * sy;
                for (float x = 24f * sx; x < w - 24f * sx; x += period) {
                    canvas.drawRect(x, stripTop, x + barW, stripBot, blackPaint);
                }
            }
        } else if (m == MODE_HUD_CONFIRM) {
            canvas.drawColor(0x00000000);
            float pad = 6f;
            canvas.drawRect(pad, pad, w - pad, h - pad, borderPaint);
            if (!hudMessage.isEmpty()) {
                float tw = textPaint.measureText(hudMessage) + 48f;
                float bx = (w - tw) * 0.5f;
                float by = h * 0.5f - 36f;
                canvas.drawRoundRect(bx, by, bx + tw, by + 72f, 16f, 16f, badgePaint);
                canvas.drawText(hudMessage, bx + 24f, by + 47f, textPaint);
            }
        }

