    int startGx = scanLeft ? 82 : 110;
    int endGx = scanLeft ? 4 : (GW - 5);
    int step = scanLeft ? -1 : 1;

    int bestGx = defaultEdge;
    float bestScore = 0f;

    for (int gx = startGx; gx != endGx; gx += step) {
        // Compare a 5-cell inner strip (on the back wall side) vs 5-cell outer strip (on the sidewall side)
        int inStart = scanLeft ? (gx + 1) : (gx - 5);
        int outStart = scanLeft ? (gx - 5) : (gx + 1);
        if (inStart < 1 || inStart + 4 >= GW || outStart < 1 || outStart + 4 >= GW) continue;

        float sumInW = 0, sumOutW = 0;
        float sumEdge = 0, consistentSign = 0;
        float sumOutParallax = 0, sumInParallax = 0;
        float sumOutSharp = 0;
        float sumOutDfd = 0;
        int sharpCount = 0;
        int activeRows = 0;
        int unlitOuterRows = 0;

        for (int gy = 14; gy < GH - 16; gy++) {
            float inVal = 0, outVal = 0;
            for (int k = 0; k < 5; k++) {
                inVal += normW[inStart + k][gy];
                outVal += normW[outStart + k][gy];
            }
            inVal *= 0.2f;
            outVal *= 0.2f;

            if (projW[inStart + 2][gy] < beamThresh) continue;
            activeRows++;
            if (projW[outStart + 2][gy] < beamThresh * 0.9f) {
                unlitOuterRows++;
            }

            sumInW += inVal;
            sumOutW += outVal;
            float diff = inVal - outVal;
            sumEdge += Math.abs(diff);
            consistentSign += diff;

            sumInParallax += projParallax[inStart + 2][gy];
            sumOutParallax += projParallax[outStart + 2][gy];

            if (!isInsideCentralAnchorHalo(outStart + 2, gy)) {
                sumOutSharp += projSharp[outStart + 2][gy];
                sumOutDfd += projDfd[outStart + 2][gy];
                sharpCount++;
            }
        }

        if (activeRows < 22) continue;

        // Case A: Beam falls off physical wall edge / dark alcove border
        if (unlitOuterRows > activeRows * 0.65f) {
            return scanLeft ? (gx + 1) : (gx - 1);
        }

        float meanInW = sumInW / activeRows;
        float meanOutW = sumOutW / activeRows;
        // Photometric crease coherence: straight 90-deg corner has consistent sign all the way top-to-bottom!
        float signedJump = Math.abs(consistentSign) / Math.max(0.25f, sumInW);
        float localGrad = Math.abs(meanInW - meanOutW) / Math.max(0.25f, meanInW);
        float coherence = Math.abs(consistentSign) / Math.max(1e-4f, sumEdge);

        float meanOutPar = sumOutParallax / activeRows;
        float parRise = Math.max(0f, meanOutPar - (sumInParallax / activeRows));

        float sharpRatio = (sharpCount > 8 && refSharp > 0.05f)
                ? ((sumOutSharp / sharpCount) / refSharp) : 1.0f;
        float meanDfd = (sharpCount > 8) ? (sumOutDfd / sharpCount) : 1.0f;

        // Multi-cue fusion score for a true 3D wall/pillar crease:
        //   1. Straight photometric normal step (coherence > 0.72 & signedJump > 0.085)
        //   2. Homography parallax / grid foreshortening kink (meanOutPar > 1.8 or parRise > 0.9)
        //   3. Side-wall defocus / grazing blur (sharpRatio < 0.80 or DfD > 1.08)
