        float cueParallax = (meanOutPar > 1.65f) ? ((meanOutPar - 1.3f) * 0.85f + parRise * 0.6f) : 0f;
        float cueBlur = (sharpRatio < 0.82f) ? ((0.85f - sharpRatio) * 2.4f) : 0f;
        if (meanDfd > 1.07f) cueBlur += (meanDfd - 1.05f) * 3.0f;

        // Require either strong geometric+blur evidence OR a crisp straight photometric crease backed by blur/parallax/albedo step
        float totalScore = 0f;
