/**
 * Scans outward from the center main wall to detect vertical alcove boundaries:
 *   - Left protruding pillar / wall return (scanLeft = true: gx from 80 down to 3)
 *   - Right perpendicular side wall / corner crease (scanLeft = false: gx from 112 up to 188)
 * Fuses 4 physical cues:
 *   1. Photometric straight-line normal step / pillar shadow strip
 *   2. Homography parallax & foreshortening kink across the 91-dot lattice
 *   3. Beam top/bottom vertical span slope-break (closer side wall / pillar shrinks cone height!)
 *   4. Side-wall optical defocus / oblique grazing blur
 */
private static int detectVerticalWallSeam(
        float[][] normW, float[][] projW, float[][] projParallax,
        float[][] projSharp, float[][] projDfd,
        int beamThresh, float refSharp, boolean scanLeft) {

    // Precompute per-column vertical lit span [topGy..botGy] in projector space to catch cone-height kinks!
    int[] colSpan = new int[GW];
    int[] colTop = new int[GW];
    for (int x = 0; x < GW; x++) {
        int t = -1, b = -1;
        for (int y = 0; y < GH / 2; y++) {
            if (projW[x][y] >= beamThresh * 1.15f) { t = y; break; }
        }
        for (int y = GH - 1; y > GH / 2; y--) {
            if (projW[x][y] >= beamThresh * 1.15f) { b = y; break; }
        }
        colTop[x] = t;
        colSpan[x] = (t >= 0 && b > t) ? (b - t) : 0;
    }
    int refSpan = colSpan[GW / 2] > 0 ? colSpan[GW / 2] : GH - 8;

    int defaultEdge = scanLeft ? 1 : (GW - 2);
    int startGx = scanLeft ? 82 : 110;
    int endGx = scanLeft ? 4 : (GW - 5);
    int step = scanLeft ? -1 : 1;

    int bestGx = defaultEdge;
    float bestScore = 0f;

    for (int gx = startGx; gx != endGx; gx += step) {
        // Compare a 5-cell inner strip (on the back wall side) vs 5-cell outer strip (on the sidewall side)
        int inStart = scanLeft ? (gx + 1) : (gx - 5);
        int outStart = scanLeft ? (gx - 5) : (gx + 1);
        if (inStart < 1 || inStart + 4 >= GW || outStart < 1 || outStart + 4 >= GW) continue;

        float sumInW = 0, sumOutW = 0, sumSeamDark = 0;
        float sumEdge = 0, consistentSign = 0;
        float sumOutParallax = 0, sumInParallax = 0;
        float sumOutSharp = 0;
        float sumOutDfd = 0;
        int sharpCount = 0;
        int activeRows = 0;
        int unlitOuterRows = 0;

        for (int gy = 14; gy < GH - 16; gy++) {
            float inVal = 0, outVal = 0;
            for (int k = 0; k < 5; k++) {
                inVal += normW[inStart + k][gy];
                outVal += normW[outStart + k][gy];
            }
            inVal *= 0.2f;
            outVal *= 0.2f;

            if (projW[inStart + 2][gy] < beamThresh) continue;
            activeRows++;
            if (projW[outStart + 2][gy] < beamThresh * 0.9f) {
                unlitOuterRows++;
            }

            sumInW += inVal;
            sumOutW += outVal;
            // Pillar occlusion shadow notch right at gx (2-cell narrow vertical shadow strip!)
            float seamNotch = Math.max(0f, Math.min(inVal, outVal) - normW[gx][gy]);
            sumSeamDark += seamNotch;

            float diff = inVal - outVal;
            sumEdge += Math.abs(diff);
            consistentSign += diff;

            sumInParallax += projParallax[inStart + 2][gy];
            sumOutParallax += projParallax[outStart + 2][gy];

            if (!isInsideCentralAnchorHalo(outStart + 2, gy)) {
                sumOutSharp += projSharp[outStart + 2][gy];
                sumOutDfd += projDfd[outStart + 2][gy];
                sharpCount++;
            }
        }

        if (activeRows < 22) continue;

        if (unlitOuterRows > activeRows * 0.65f) {
            return scanLeft ? (gx + 1) : (gx - 1);
        }

        float meanInW = sumInW / activeRows;
        float meanOutW = sumOutW / activeRows;
        float signedJump = Math.abs(consistentSign) / Math.max(0.25f, sumInW);
        float localGrad = Math.abs(meanInW - meanOutW) / Math.max(0.25f, meanInW);
        float coherence = Math.abs(consistentSign) / Math.max(1e-4f, sumEdge);
        float shadowNotch = (sumSeamDark / activeRows) / Math.max(0.25f, meanInW);

        float meanOutPar = sumOutParallax / activeRows;
        float parRise = Math.max(0f, meanOutPar - (sumInParallax / activeRows));

        float sharpRatio = (sharpCount > 8 && refSharp > 0.05f)
                ? ((sumOutSharp / sharpCount) / refSharp) : 1.0f;
        float meanDfd = (sharpCount > 8) ? (sumOutDfd / sharpCount) : 1.0f;

        // Beam vertical span hinge (if outer 8 columns shrink vertically because sidewall/pillar is closer!)
        int farOutGx = clamp(gx + step * 8, 2, GW - 3);
        int nearInGx = clamp(gx - step * 4, 2, GW - 3);
        float spanShrink = 0f;
        if (colSpan[farOutGx] > 20 && colSpan[nearInGx] > 20 && refSpan > 40) {
            spanShrink = Math.max(0f, (colSpan[nearInGx] - colSpan[farOutGx]) / (float) refSpan);
        }

        float cueCrease = (coherence > 0.68f && localGrad > 0.065f) ? (signedJump * coherence * 4.5f) : 0f;
        if (shadowNotch > 0.075f) cueCrease += shadowNotch * 5.0f;
        float cueParallax = (meanOutPar > 1.55f) ? ((meanOutPar - 1.25f) * 0.9f + parRise * 0.65f) : 0f;
        float cueHinge = (spanShrink > 0.022f) ? (spanShrink * 12.0f) : 0f;
        float cueBlur = (sharpRatio < 0.84f) ? ((0.86f - sharpRatio) * 2.5f) : 0f;
        if (meanDfd > 1.07f) cueBlur += (meanDfd - 1.05f) * 3.0f;

        float totalScore = 0f;
        int supportingCues = (cueCrease > 0.22f ? 1 : 0)
                + (cueParallax > 0.30f ? 1 : 0)
                + (cueHinge > 0.22f ? 1 : 0)
                + (cueBlur > 0.14f ? 1 : 0);

        if (supportingCues >= 2 || cueParallax > 1.15f || (cueCrease > 0.42f && localGrad > 0.14f)) {
            totalScore = cueCrease + cueParallax + cueHinge + cueBlur;
        }

        if (totalScore > 0.50f && totalScore > bestScore) {
            bestScore = totalScore;
            bestGx = gx;
        } else if (bestScore > 0.62f && Math.abs(gx - bestGx) >= 6 && totalScore < bestScore * 0.58f) {
            break;
        }
    }

