// Overlap V4L2 camera open (USB UVC stream-on) concurrently with AIDL bind + overlay attach!
final int camId = SystemProperties.getInt("persist.keystone.camid", 0);
final AtomicBoolean camReady = new AtomicBoolean(false);
final CountDownLatch camLatch = new CountDownLatch(1);
new Thread(new Runnable() {
    @Override
    public void run() {
        try {
            int rc = HYSDVAF2.s0cam(camId, 2);
            if (rc != 1) {
                sleepQuiet(40);
                rc = HYSDVAF2.s0cam(camId, 2);
            }
            camReady.set(true);
        } catch (Throwable t) {
            Log.e(TAG, "Parallel s0cam error", t);
        } finally {
            camLatch.countDown();
        }
    }
}, "TurboCamOpen").start();

ServiceHolder aidl = bindHysdClient(1800);
PatternOverlayView overlay = null;
WindowManager wm = (WindowManager) getSystemService(Context.WINDOW_SERVICE);
int[] savedKey = null;
boolean camOpened = false;
Runnable deferredDebugSave = null;

try {
    if (aidl.service == null) {
        Log.e(TAG, "Could not bind com.hysd.client.VAFclientapi");
        camLatch.await(1200, TimeUnit.MILLISECONDS);
        camOpened = camReady.get();
        return;
    }

    savedKey = aidl.service.getkey();
    // Reset to full 1920x1080 panel and attach opaque overlay while s0cam finishes in parallel
    aidl.service.setkey(0, 0, 0, 0, 0, 0, 0, 0);
    overlay = attachOverlay(wm);
    if (overlay == null) {
        Log.e(TAG, "Could not attach full-screen PatternOverlayView");
        camLatch.await(1200, TimeUnit.MILLISECONDS);
        camOpened = camReady.get();
        return;
    }
    overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_ANCHOR_SHARPNESS, 140);

    camLatch.await(2000, TimeUnit.MILLISECONDS);
    camOpened = camReady.get();

    byte[] yuyv = new byte[YUYV_FRAME_BYTES];
    // Flush 1 initial V4L2 frame
    HYSDVAF2.s1cam(yuyv);

    // Optional fast center-only back-wall autofocus (ignores closer sidewalls!)
    if (runCenterAfFirst) {
        runFastCenterBackWallAutofocus(aidl.service, yuyv);
    }

    int[] yDark = new int[AlcoveVisionPipeline.CAM_N];
    int[] yWhite = new int[AlcoveVisionPipeline.CAM_N];
    int[] yGrid = new int[AlcoveVisionPipeline.CAM_N];
    int[] yAnchorSharp = new int[AlcoveVisionPipeline.CAM_N];
    int[] yNearSharp = null;

    // Frame 3 first (already displayed while camera opened -> zero switch wait!)
    captureSettledLuma(yuyv, yAnchorSharp, 2);

    // Optional 2-step focus-motor Depth-from-Defocus bracket (+80ms forward nudge, then exact return)
    if (runDfdBracket) {
        yNearSharp = new int[AlcoveVisionPipeline.CAM_N];
        aidl.service.motorf();
        sleepQuiet(80);
        aidl.service.motors();
        captureSettledLuma(yuyv, yNearSharp, 2);
        aidl.service.motorb();
        sleepQuiet(85);
        aidl.service.motors();
        sleepQuiet(20);
    }

    // Frame 0: DARK (ambient cancellation baseline)
    overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_DARK, 120);
    sleepQuiet(28);
    captureSettledLuma(yuyv, yDark, 2);

    // Frame 1: Unsaturated GRAY (linear irradiance, contour kink & sidewall crease map)
    overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_WHITE, 120);
    sleepQuiet(28);
    captureSettledLuma(yuyv, yWhite, 2);

    // Frame 2: 91-dot fiducial lattice
    overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_GRID_91, 120);
    sleepQuiet(28);
    captureSettledLuma(yuyv, yGrid, 2);

    // Release V4L2 camera asynchronously while CPU solves so zero serial close wait!
    camOpened = false;
    new Thread(new Runnable() {
        @Override
        public void run() {
            try { HYSDVAF2.s2cam(); } catch (Throwable ignored) {}
        }
    }, "TurboCamClose").start();

    long captureMs = (System.nanoTime() - tStart) / 1_000_000L;
    float minArea = Float.parseFloat(SystemProperties.get("persist.hysd.alcove.min_area", "0.24"));
    boolean saveDebug = !"0".equals(SystemProperties.get("persist.hysd.alcove.debug", "1"));

    AlcoveVisionPipeline.Result res = AlcoveVisionPipeline.solve(
            yDark, yWhite, yGrid, yAnchorSharp, yNearSharp, minArea, saveDebug);
    deferredDebugSave = res.deferredDebugSaver;

    long totalMs = (System.nanoTime() - tStart) / 1_000_000L;
    if (res.success) {
        int[] k = res.insets;
        aidl.service.setkey(k[0], k[1], k[2], k[3], k[4], k[5], k[6], k[7]);
        aidl.service.finishkey(1, 1, 0);
        SystemProperties.set("keystatus.hysd.sf", "1");
        SystemProperties.set("keystatus.hysd.keyresult", "1");

        String hud = String.format("Alcove Fit %dx%d (%dms)",
