/**
 * Explicitly flushes `discardCount` queued V4L2 mmap ring buffers and captures the next fresh frame.
 */
private static void captureFreshV4l2Frame(byte[] yuyv, int[] outY, int discardCount) {
    for (int i = 0; i < discardCount; i++) {
        HYSDVAF2.s1cam(yuyv);
    }
    int rc = HYSDVAF2.s1cam(yuyv);
    if (rc < 0) {
        sleepQuiet(20);
        HYSDVAF2.s1cam(yuyv);
    }
    AlcoveVisionPipeline.extractLuma(yuyv, outY);
}

arguments.old_str:
/**
 * Drains V4L2 queued buffers until consecutive global luma mean stabilizes (guaranteed fresh frame).
 */
private static void captureSettledLuma(byte[] yuyv, int[] outY, int minReads) {
    double prevMean = -999.0;
    for (int attempt = 0; attempt < minReads + 3; attempt++) {
        int rc = HYSDVAF2.s1cam(yuyv);
        if (rc < 0) {
            sleepQuiet(15);
            continue;
        }
        double mean = sampleFastMeanLuma(yuyv);
        if (attempt >= minReads - 1 && Math.abs(mean - prevMean) < 2.2) {
            break;
        }
        prevMean = mean;
    }
    AlcoveVisionPipeline.extractLuma(yuyv, outY);
}

