toolArgs.new_str:
overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_ANCHOR_SHARPNESS, 250);
// Allow initial OpenGLRenderer gralloc surface swap to hit the LCD panel
sleepQuiet(65);

camLatch.await(2000, TimeUnit.MILLISECONDS);
camOpened = camReady.get();

byte[] yuyv = new byte[YUYV_FRAME_BYTES];

// Optional fast center-only back-wall autofocus (ignores closer sidewalls!)
if (runCenterAfFirst) {
    runFastCenterBackWallAutofocus(aidl.service, yuyv);
    overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_ANCHOR_SHARPNESS, 120);
    sleepQuiet(45);
}

int[] yDark = new int[AlcoveVisionPipeline.CAM_N];
int[] yWhite = new int[AlcoveVisionPipeline.CAM_N];
int[] yGrid = new int[AlcoveVisionPipeline.CAM_N];
int[] yAnchorSharp = new int[AlcoveVisionPipeline.CAM_N];
int[] yNearSharp = null;

// HYCAM allocates 4 V4L2 mmap ring buffers -> discard 4 stale buffers and keep the 5th fresh frame!
captureFreshV4l2Frame(yuyv, yAnchorSharp, 4);

if (runDfdBracket) {
    yNearSharp = new int[AlcoveVisionPipeline.CAM_N];
    aidl.service.motorf();
    sleepQuiet(80);
    aidl.service.motors();
    sleepQuiet(35);
    captureFreshV4l2Frame(yuyv, yNearSharp, 4);
    aidl.service.motorb();
    sleepQuiet(85);
    aidl.service.motors();
    sleepQuiet(25);
}

// Frame 0: DARK (ambient cancellation baseline)
overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_DARK, 150);
sleepQuiet(45);
captureFreshV4l2Frame(yuyv, yDark, 4);

// Frame 1: Unsaturated GRAY 165 (linear irradiance, contour kink & sidewall crease map)
overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_WHITE, 150);
sleepQuiet(45);
captureFreshV4l2Frame(yuyv, yWhite, 4);

// Frame 2: 91-dot fiducial lattice
overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_GRID_91, 150);
sleepQuiet(45);
captureFreshV4l2Frame(yuyv, yGrid, 4);

