overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_ANCHOR_SHARPNESS, 140);

camLatch.await(2000, TimeUnit.MILLISECONDS);
camOpened = camReady.get();

byte[] yuyv = new byte[YUYV_FRAME_BYTES];
// Flush 1 initial V4L2 frame
HYSDVAF2.s1cam(yuyv);

// Optional fast center-only back-wall autofocus (ignores closer sidewalls!)
if (runCenterAfFirst) {
    runFastCenterBackWallAutofocus(aidl.service, yuyv);
}

int[] yDark = new int[AlcoveVisionPipeline.CAM_N];
int[] yWhite = new int[AlcoveVisionPipeline.CAM_N];
int[] yGrid = new int[AlcoveVisionPipeline.CAM_N];
int[] yAnchorSharp = new int[AlcoveVisionPipeline.CAM_N];
int[] yNearSharp = null;

// Frame 3 first (already displayed while camera opened -> zero switch wait!)
captureSettledLuma(yuyv, yAnchorSharp, 2);

// Optional 2-step focus-motor Depth-from-Defocus bracket (+80ms forward nudge, then exact return)
if (runDfdBracket) {
    yNearSharp = new int[AlcoveVisionPipeline.CAM_N];
    aidl.service.motorf();
    sleepQuiet(80);
    aidl.service.motors();
    captureSettledLuma(yuyv, yNearSharp, 2);
    aidl.service.motorb();
    sleepQuiet(85);
    aidl.service.motors();
    sleepQuiet(20);
}

// Frame 0: DARK (ambient cancellation baseline)
overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_DARK, 120);
sleepQuiet(28);
captureSettledLuma(yuyv, yDark, 2);

// Frame 1: Unsaturated GRAY (linear irradiance, contour kink & sidewall crease map)
overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_WHITE, 120);
sleepQuiet(28);
captureSettledLuma(yuyv, yWhite, 2);

// Frame 2: 91-dot fiducial lattice
overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_GRID_91, 120);
sleepQuiet(28);
captureSettledLuma(yuyv, yGrid, 2);

