// Unsaturated bright-gray (~56% linear light at gamma 2.2) gives crisp contrast without 255 clipping
public static final int ILLUM_GRAY = Color.rgb(195, 195, 195);

public static final int MODE_DARK = 0;
public static final int MODE_WHITE = 1;
public static final int MODE_GRID_91 = 2;
public static final int MODE_ANCHOR_SHARPNESS = 3;
public static final int MODE_HUD_CONFIRM = 4;

private volatile int mode = MODE_DARK;

