arguments.new_str:
// Start with pure DARK while s0cam opens so NO patterned ghost can ever pollute yDark or yWhite!
overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_DARK, 250);
sleepQuiet(50);

camLatch.await(2000, TimeUnit.MILLISECONDS);
camOpened = camReady.get();

byte[] yuyv = new byte[YUYV_FRAME_BYTES];

// Optional fast center-only back-wall autofocus (ignores closer sidewalls!)
if (runCenterAfFirst) {
    overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_ANCHOR_SHARPNESS, 140);
    sleepQuiet(60);
    captureFreshV4l2Frame(yuyv, null, 4);
    runFastCenterBackWallAutofocus(aidl.service, yuyv);
    overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_DARK, 140);
    sleepQuiet(60);
}

int[] yDark = new int[AlcoveVisionPipeline.CAM_N];
int[] yWhite = new int[AlcoveVisionPipeline.CAM_N];
int[] yGrid = new int[AlcoveVisionPipeline.CAM_N];
int[] yAnchorSharp = new int[AlcoveVisionPipeline.CAM_N];
int[] yNearSharp = null;

// 1. Capture DARK baseline (closed-loop settled)
double darkMean = captureSettledMode(yuyv, yDark, -1.0, true);

// 2. Capture pure uniform GRAY 195 (before ANY grid or halo pattern is ever drawn!)
overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_WHITE, 150);
sleepQuiet(35);
captureSettledMode(yuyv, yWhite, darkMean + 35.0, false);

// 3. Capture 91-dot fiducial lattice
