/**
 * Closed-loop frame arrival detector for DARK and uniform GRAY frames:
 * drains V4L2 buffers until brightness crosses target threshold AND frame-to-frame delta settles.
 */
private static double captureSettledMode(byte[] yuyv, int[] outY, double minTargetMean, boolean expectDark) {
    double prev = -999.0;
    double cur = 0.0;
    for (int i = 0; i < 9; i++) {
        HYSDVAF2.s1cam(yuyv);
        cur = sampleFastMeanLuma(yuyv);
        boolean levelOk = expectDark ? (cur < 55.0) : (cur >= minTargetMean);
        if (i >= 3 && levelOk && Math.abs(cur - prev) < 2.0) {
            break;
        }
        prev = cur;
    }
    if (outY != null) {
        AlcoveVisionPipeline.extractLuma(yuyv, outY);
    }
    return cur;
}

/**
 * Explicitly flushes `discardCount` queued V4L2 mmap ring buffers and captures the next fresh frame.
 */
private static void captureFreshV4l2Frame(byte[] yuyv, int[] outY, int discardCount) {
    for (int i = 0; i < discardCount; i++) {
        HYSDVAF2.s1cam(yuyv);
    }
    int rc = HYSDVAF2.s1cam(yuyv);
    if (rc < 0) {
        sleepQuiet(20);
        HYSDVAF2.s1cam(yuyv);
    }
    if (outY != null) {
        AlcoveVisionPipeline.extractLuma(yuyv, outY);
    }
}

