// Compute verified coplanar main-wall span from green fiducial lattice columns/rows (dotParallax < 1.9)
// so interior illumination gradients can NEVER falsely trigger a wall seam inside the flat back wall!
int coplanarMinGx = 78, coplanarMaxGx = 114;
int coplanarMinGy = 36, coplanarMaxGy = 72;
if (matchedDots >= 12) {
    int minCoplanarCol = PatternOverlayView.CENTER_COL;
    int maxCoplanarCol = PatternOverlayView.CENTER_COL;
    for (int c = PatternOverlayView.CENTER_COL; c >= 0; c--) {
        int good = 0, bad = 0;
        for (int r = 1; r < PatternOverlayView.GRID_ROWS; r++) {
            if (!dotObserved[c][r]) continue;
            if (dotParallax[c][r] <= 2.1f) good++; else bad++;
        }
        if (good >= 2 && bad <= 1) minCoplanarCol = c;
        else if (bad >= 2 || good == 0) break;
    }
    for (int c = PatternOverlayView.CENTER_COL; c < PatternOverlayView.GRID_COLS; c++) {
        int good = 0, bad = 0;
        for (int r = 1; r < PatternOverlayView.GRID_ROWS; r++) {
            if (!dotObserved[c][r]) continue;
            if (dotParallax[c][r] <= 2.1f) good++; else bad++;
        }
        if (good >= 2 && bad <= 1) maxCoplanarCol = c;
        else if (bad >= 2 || good == 0) break;
    }
    coplanarMinGx = Math.round(PatternOverlayView.dotProjX(minCoplanarCol) / CELL_PX);
    coplanarMaxGx = Math.round(PatternOverlayView.dotProjX(maxCoplanarCol) / CELL_PX);
    Log.i(TAG, "Coplanar lattice cols=[" + minCoplanarCol + ".." + maxCoplanarCol
            + "] -> X=[" + (coplanarMinGx * CELL_PX) + ".." + (coplanarMaxGx * CELL_PX) + "]");
}

// 7. Detect Alcove Sidewall / Pillar / Soffit Seams strictly outside the verified coplanar core!
