private static int detectVerticalWallSeam(
        float[][] normW, float[][] projW, float[][] projParallax,
        float[][] projSharp, float[][] projDfd,
        int beamThresh, float refSharp, boolean scanLeft, int coplanarBoundaryGx) {

    // Precompute per-column vertical lit span [topGy..botGy] in projector space to catch cone-height kinks!
    int[] colSpan = new int[GW];
    int[] colTop = new int[GW];
    for (int x = 0; x < GW; x++) {
        int t = -1, b = -1;
        for (int y = 0; y < GH / 2; y++) {
            if (projW[x][y] >= beamThresh * 1.15f) { t = y; break; }
        }
        for (int y = GH - 1; y > GH / 2; y--) {
            if (projW[x][y] >= beamThresh * 1.15f) { b = y; break; }
        }
        colTop[x] = t;
        colSpan[x] = (t >= 0 && b > t) ? (b - t) : 0;
    }
    int refSpan = colSpan[GW / 2] > 0 ? colSpan[GW / 2] : GH - 8;

    int defaultEdge = scanLeft ? 1 : (GW - 2);
    // Start scanning just at/outside the verified coplanar green-dot boundary!
    int startGx = scanLeft
            ? clamp(coplanarBoundaryGx + 2, 6, 82)
            : clamp(coplanarBoundaryGx - 2, 110, GW - 7);
    int endGx = scanLeft ? 4 : (GW - 5);
    int step = scanLeft ? -1 : 1;

