const fs = require("fs");
const zlib = require("zlib");

const buf = fs.readFileSync("C:\\Users\\ngantla\\.copilot\\session-state\\4c8ab7fc-bd1f-480c-99ab-4458bfed9b0e\\files\\alcove_upgrade\\alcove_debug_run4.png");
let off = 8, w = 0, h = 0, idat = [];
while (off < buf.length) {
  const len = buf.readUInt32BE(off);
  const type = buf.toString("ascii", off + 4, off + 8);
  if (type === "IHDR") { w = buf.readUInt32BE(off + 8); h = buf.readUInt32BE(off + 12); }
  else if (type === "IDAT") idat.push(buf.subarray(off + 8, off + 8 + len));
  off += 12 + len;
}
const raw = zlib.inflateSync(Buffer.concat(idat));
const stride = 1 + w * 4;
const px = new Uint8Array(w * h);
for (let y = 0; y < h; y++) {
  const f = raw[y * stride];
  let rPrev = 0;
  for (let x = 0; x < w; x++) {
    let val = raw[y * stride + 1 + x * 4];
    if (f === 1) val = (val + rPrev) & 0xFF;
    else if (f === 2 && y > 0) val = (val + px[(y - 1) * w + x]) & 0xFF;
    else if (f === 3) val = (val + ((rPrev + (y > 0 ? px[(y - 1) * w + x] : 0)) >> 1)) & 0xFF;
    else if (f === 4) {
      const a = rPrev, b = y > 0 ? px[(y - 1) * w + x] : 0, c = (y > 0 && x > 0) ? px[(y - 1) * w + x - 1] : 0;
      const p = a + b - c;
      const pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
      val = (val + ((pa <= pb && pa <= pc) ? a : (pb <= pc ? b : c))) & 0xFF;
    }
    px[y * w + x] = val;
    rPrev = val;
  }
}

// Print W(u, v=190) at fine 8px steps around left seam (u=0..120) and right seam (u=390..590)
const leftProf = [], rightProf = [], vertProf = [];
for (let u = 0; u <= 128; u += 8) leftProf.push(`${u}:${Math.round(px[190 * w + u] / 2)}`);
for (let u = 392; u <= 592; u += 8) rightProf.push(`${u}:${Math.round(px[190 * w + u] / 2)}`);
for (let v = 0; v <= 390; v += 15) vertProf.push(`${v}:${Math.round(px[v * w + 250] / 2)}`);
console.log("LEFT  seam W(u, v=190):", leftProf.join(" "));
console.log("RIGHT seam W(u, v=190):", rightProf.join(" "));
console.log("VERT  span W(u=250, v):", vertProf.join(" "));
