        cv.drawLine(ox + (rightGx + 1) * cw, oy, ox + (rightGx + 1) * cw, oy + sh, p);
        cv.drawLine(ox, oy + topGy * ch, ox + sw, oy + topGy * ch, p);
        cv.drawLine(ox, oy + (botGy + 1) * ch, ox + sw, oy + (botGy + 1) * ch, p);

