                oy + (bPx / 1080f) * sh, p);

        p.setStyle(Paint.Style.FILL);
        p.setColor(Color.WHITE);
        p.setTextSize(15f);
        cv.drawText(summary, 20f, 462f, p);
        cv.drawText("Projector 1920x1080 Map (Green=Bright Center Wall, Red=Grey Sidewall/Obstacle, Cyan=Seam, Yellow=16:9)",
