        int off = v * CAM_W;
        for (int u = 0; u < CAM_W; u++) {
            int m = 0;
            int u0 = Math.max(0, u - radius), u1 = Math.min(CAM_W - 1, u + radius);
            for (int x = u0; x <= u1; x++) {
                int val = src[off + x];
                if (val > m) m = val;
            }
