    int[] queue = new int[4096];
    List<Blob> out = new ArrayList<>(128);

    for (int v = 4; v < CAM_H - 4; v++) {
        int rowOff = v * CAM_W;
        for (int u = 4; u < CAM_W - 4; u++) {
            int idx = rowOff + u;
            if (D2[idx] < thresh || visited[idx]) continue;

            int head = 0, tail = 0;
            queue[tail++] = idx;
            visited[idx] = true;

            double sumW = 0, sumU = 0, sumV = 0, sumD3 = 0;
            int peak = 0, area = 0;
            int minU = u, maxU = u, minV = v, maxV = v;

            while (head < tail) {
                int cur = queue[head++];
                int cv = cur / CAM_W;
                int cu = cur - cv * CAM_W;
                int val = D2[cur];
                area++;
                sumW += val;
                sumU += cu * (double) val;
                sumV += cv * (double) val;
                sumD3 += D3[cur];
                if (val > peak) peak = val;
                if (cu < minU) minU = cu;
                if (cu > maxU) maxU = cu;
                if (cv < minV) minV = cv;
                if (cv > maxV) maxV = cv;

                if (tail + 4 < queue.length) {
                    int n1 = cur - 1, n2 = cur + 1, n3 = cur - CAM_W, n4 = cur + CAM_W;
                    if (cu > 2 && !visited[n1] && D2[n1] >= thresh) { visited[n1] = true; queue[tail++] = n1; }
                    if (cu < CAM_W - 3 && !visited[n2] && D2[n2] >= thresh) { visited[n2] = true; queue[tail++] = n2; }
                    if (cv > 2 && !visited[n3] && D2[n3] >= thresh) { visited[n3] = true; queue[tail++] = n3; }
                    if (cv < CAM_H - 3 && !visited[n4] && D2[n4] >= thresh) { visited[n4] = true; queue[tail++] = n4; }
                }
            }

            int bw = maxU - minU + 1;
            int bh = maxV - minV + 1;
            // Expected 28x28 projector dot -> ~4x4 to 14x14 camera pixels
            if (area >= 4 && area <= 260 && bw <= 24 && bh <= 24 && bw <= bh * 3 && bh <= bw * 3) {
                Blob b = new Blob();
                b.u = (float) (sumU / sumW);
                b.v = (float) (sumV / sumW);
                b.area = area;
                b.peakD2 = peak;
                b.meanD3 = (float) (sumD3 / area);
                out.add(b);
            }
        }
    }
    return out;
}

/**
 * Identifies the L-triad {(6,3), (7,3), (6,4)} from Frame 3's exclusive central anchors,
 * then propagates outward across all walls using local step extrapolation.
 */
private static int assignLattice(List<Blob> blobs, int[][] gridToBlob) {
    final int n = blobs.size();
    if (n < 6) return 0;

    // Score every ordered triple (iOrigin, iPlusX, iPlusY) for L-triad match:
    //   1. High D3 on all 3 triad members
    //   2. Nearly orthogonal ~equal-scale step vectors ex = P_x - P_o, ey = P_y - P_o
    //   3. Positive orientation det(ex, ey) > 0 (standard non-mirrored camera) or highest support
    //   4. Opposite neighbors P_o - ex and P_o - ey exist in D2 blobs with LOW D3 (white halo!)
    int bestO = -1, bestX = -1, bestY = -1;
    double bestTriadScore = -1.0;

    for (int i = 0; i < n; i++) {
        Blob bo = blobs.get(i);
        if (bo.meanD3 < 55f) continue;
        for (int j = 0; j < n; j++) {
            if (j == i) continue;
            Blob bx = blobs.get(j);
            if (bx.meanD3 < 55f) continue;
            float exU = bx.u - bo.u, exV = bx.v - bo.v;
            float lenX = (float) Math.hypot(exU, exV);
            if (lenX < 12f || lenX > 95f) continue;

            for (int k = 0; k < n; k++) {
                if (k == i || k == j) continue;
                Blob by = blobs.get(k);
                if (by.meanD3 < 55f) continue;
                float eyU = by.u - bo.u, eyV = by.v - bo.v;
                float lenY = (float) Math.hypot(eyU, eyV);
                if (lenY < 12f || lenY > 95f) continue;

                float ratio = lenX / lenY;
                if (ratio < 0.62f || ratio > 1.55f) continue;

                float cosAng = (exU * eyU + exV * eyV) / (lenX * lenY);
                if (Math.abs(cosAng) > 0.42f) continue;

                // Verify opposite lattice neighbors (-X = (5,3) and -Y = (6,2)) exist in D2 and have LOW D3!
                int minusX = findNearestBlob(blobs, bo.u - exU, bo.v - exV, lenX * 0.35f);
                int minusY = findNearestBlob(blobs, bo.u - eyU, bo.v - eyU, lenY * 0.35f);
                double haloBonus = 0.0;
                if (minusX >= 0 && blobs.get(minusX).meanD3 < 45f) haloBonus += 80.0;
                if (minusY >= 0 && blobs.get(minusY).meanD3 < 45f) haloBonus += 80.0;

                // Check cross-orientation: in standard front camera view, +X is right and +Y is down (cross > 0)
                float cross = exU * eyV - exV * eyU;
                double orientWeight = (cross > 0) ? 1.15 : 0.90;

                double score = orientWeight * (bo.meanD3 + bx.meanD3 + by.meanD3 + haloBonus
                        - Math.abs(cosAng) * 90.0 - Math.abs(lenX - lenY) * 1.5);
                if (score > bestTriadScore) {
                    bestTriadScore = score;
                    bestO = i;
                    bestX = j;
                    bestY = k;
                }
            }
        }
    }

    if (bestO < 0) {
        Log.w(TAG, "L-triad anchor not found via D3; attempting central geometric lattice seed.");
        int centerIdx = findNearestBlob(blobs, CAM_W * 0.5f, CAM_H * 0.5f, 120f);
        if (centerIdx < 0) return 0;
        Blob bo = blobs.get(centerIdx);
        int rightIdx = -1, downIdx = -1;
        float bestRx = 999f, bestDy = 999f;
        for (int i = 0; i < n; i++) {
            if (i == centerIdx) continue;
            Blob b = blobs.get(i);
            float du = b.u - bo.u, dv = b.v - bo.v;
            float dist = (float) Math.hypot(du, dv);
            if (dist >= 14f && dist <= 85f) {
                if (du > Math.abs(dv) * 1.5f && dist < bestRx) { bestRx = dist; rightIdx = i; }
                if (dv > Math.abs(du) * 1.5f && dist < bestDy) { bestDy = dist; downIdx = i; }
            }
        }
        if (rightIdx < 0 || downIdx < 0) return 0;
        bestO = centerIdx; bestX = rightIdx; bestY = downIdx;
    }

    // Seed BFS lattice assignment from {(6,3), (7,3), (6,4)}
    int oc = PatternOverlayView.CENTER_COL;
    int or = PatternOverlayView.CENTER_ROW;
    assignNode(blobs, gridToBlob, oc, or, bestO);
    assignNode(blobs, gridToBlob, oc + 1, or, bestX);
    assignNode(blobs, gridToBlob, oc, or + 1, bestY);

    int[] qCol = new int[PatternOverlayView.GRID_COLS * PatternOverlayView.GRID_ROWS * 2];
    int[] qRow = new int[PatternOverlayView.GRID_COLS * PatternOverlayView.GRID_ROWS * 2];
    int qHead = 0, qTail = 0;
    qCol[qTail] = oc; qRow[qTail++] = or;
    qCol[qTail] = oc + 1; qRow[qTail++] = or;
    qCol[qTail] = oc; qRow[qTail++] = or + 1;

    float baseStepX = (float) Math.hypot(
            blobs.get(bestX).u - blobs.get(bestO).u,
            blobs.get(bestX).v - blobs.get(bestO).v);
    float baseStepY = (float) Math.hypot(
            blobs.get(bestY).u - blobs.get(bestO).u,
            blobs.get(bestY).v - blobs.get(bestO).v);
    float globalExU = blobs.get(bestX).u - blobs.get(bestO).u;
    float globalExV = blobs.get(bestX).v - blobs.get(bestO).v;
    float globalEyU = blobs.get(bestY).u - blobs.get(bestO).u;
    float globalEyV = blobs.get(bestY).v - blobs.get(bestO).v;

    int[][] dirs = { {1, 0}, {-1, 0}, {0, 1}, {0, -1} };
    int matched = 3;

    while (qHead < qTail) {
        int c = qCol[qHead];
        int r = qRow[qHead++];
        Blob cur = blobs.get(gridToBlob[c][r]);

        for (int[] d : dirs) {
            int nc = c + d[0];
            int nr = r + d[1];
            if (nc < 0 || nc >= PatternOverlayView.GRID_COLS || nr < 0 || nr >= PatternOverlayView.GRID_ROWS) continue;
            if (gridToBlob[nc][nr] >= 0) continue;

            // Extrapolate locally from immediate back-neighbor so side-wall slope kinks still track cleanly!
            float stepU, stepV;
            int backC = c - d[0], backR = r - d[1];
            if (backC >= 0 && backC < PatternOverlayView.GRID_COLS
                    && backR >= 0 && backR < PatternOverlayView.GRID_ROWS
                    && gridToBlob[backC][backR] >= 0) {
                Blob prev = blobs.get(gridToBlob[backC][backR]);
                stepU = cur.u - prev.u;
                stepV = cur.v - prev.v;
            } else {
                stepU = d[0] * globalExU + d[1] * globalEyU;
                stepV = d[0] * globalExV + d[1] * globalEyV;
            }

            float predU = cur.u + stepU;
            float predV = cur.v + stepV;
            float tol = Math.max(8f, 0.42f * (d[0] != 0 ? baseStepX : baseStepY));
            int cand = findNearestUnassignedBlob(blobs, predU, predV, tol);
            if (cand >= 0) {
                assignNode(blobs, gridToBlob, nc, nr, cand);
                qCol[qTail] = nc;
                qRow[qTail++] = nr;
                matched++;
            }
        }
    }
    return matched;
}

