        for (int u = 0; u < CAM_W; u++) {
            float m = 0f;
            int u0 = Math.max(0, u - r), u1 = Math.min(CAM_W - 1, u + r);
            for (int x = u0; x <= u1; x++) if (raw[off + x] > m) m = raw[off + x];
            tmp[off + u] = m;
        }
    }
    for (int v = 0; v < CAM_H; v++) {
        int v0 = Math.max(0, v - 4), v1 = Math.min(CAM_H - 1, v + 4);
        for (int u = 0; u < CAM_W; u++) {
            float m = 0f;
            for (int y = v0; y <= v1; y++) if (tmp[y * CAM_W + u] > m) m = tmp[y * CAM_W + u];
            out[v * CAM_W + u] = m;
        }
    }
    return out;
}

private static float interpolateCheckerParallax(float[][] dotPar, boolean[][] obs, float px, float py) {
