            int idx = rowOff + u;
            if (D2[idx] < thresh || visited[idx]) continue;

            int head = 0, tail = 0;
            queue[tail++] = idx;
            visited[idx] = true;

            double sumW = 0, sumU = 0, sumV = 0, sumD3 = 0;
            int peak = 0, area = 0;
            int minU = u, maxU = u, minV = v, maxV = v;

            while (head < tail) {
                int cur = queue[head++];
                int cv = cur / CAM_W;
                int cu = cur - cv * CAM_W;
                int val = D2[cur];
                area++;
                sumW += val;
                sumU += cu * (double) val;
                sumV += cv * (double) val;
                sumD3 += D3[cur];
                if (val > peak) peak = val;
                if (cu < minU) minU = cu;
                if (cu > maxU) maxU = cu;
                if (cv < minV) minV = cv;
