const net = require("net");
async function probe(ip) {
  return new Promise(res => {
    const s = new net.Socket();
    s.setTimeout(350);
    s.once("connect", () => { s.destroy(); res(ip); });
    s.once("timeout", () => { s.destroy(); res(null); });
    s.once("error", () => { s.destroy(); res(null); });
    s.connect(5555, ip);
  });
}
(async () => {
  const ips = ["192.168.137.81"];
  for (let i = 2; i < 255; i++) ips.push(`192.168.137.${i}`);
  for (let i = 2; i < 255; i++) ips.push(`192.168.0.${i}`);
  for (let b = 0; b < ips.length; b += 64) {
    const hits = (await Promise.all(ips.slice(b, b + 64).map(probe))).filter(Boolean);
    if (hits.length) console.log("Found ADB 5555 on:", [...new Set(hits)]);
  }
})();
