                && c0[0] > -80 && c1[0] < CAM_W + 80 && c0[1] > -80 && c3[1] < CAM_H + 80;
    }

    private static float[] computeCheckerEdgeSharpness(int[] S, int[] W, int beamThresh, int normFloor) {
        float[] raw = new float[CAM_N];
        for (int v = 2; v < CAM_H - 2; v++) {
            int off = v * CAM_W;
            for (int u = 2; u < CAM_W - 2; u++) {
                int i = off + u;
                if (W[i] < beamThresh) continue;
                int g = Math.abs(S[i + 1] - S[i - 1]);
                raw[i] = g / (float) (2 * Math.max(W[i], normFloor));
            }
        }
        float[] tmp = new float[CAM_N];
        float[] out = new float[CAM_N];
        final int r = 14;
        for (int v = 0; v < CAM_H; v++) {
            int off = v * CAM_W;
            for (int u = 0; u < CAM_W; u++) {
                float m = 0f;
                int u0 = Math.max(0, u - r), u1 = Math.min(CAM_W - 1, u + r);
                for (int x = u0; x <= u1; x++) if (raw[off + x] > m) m = raw[off + x];
                tmp[off + u] = m;
            }
        }
        for (int v = 0; v < CAM_H; v++) {
            int v0 = Math.max(0, v - 4), v1 = Math.min(CAM_H - 1, v + 4);
            for (int u = 0; u < CAM_W; u++) {
                float m = 0f;
                for (int y = v0; y <= v1; y++) if (tmp[y * CAM_W + u] > m) m = tmp[y * CAM_W + u];
