             if (activeCols < 18) continue;
             if (unlitOuter > activeCols * 0.65f) {
                 return scanTop ? (gy + 1) : (gy - 1);
             }

             float coherence = Math.abs(consistentSign) / Math.max(1e-4f, sumEdge);
             float localGrad = Math.abs(sumInW - sumOutW) / Math.max(0.25f, sumInW);
             float meanPar = sumOutPar / activeCols;
             float sharpRatio = (sharpCnt > 8 && refSharp > 0.05f) ? ((sumOutSharp / sharpCnt) / refSharp) : 1.0f;

             float score = 0f;
             if (coherence > 0.72f && localGrad > 0.09f && (sharpRatio < 0.84f || meanPar > 1.8f || localGrad > 0.16f)) {
