     */
    private static void captureSettledCheckerBase(byte[] yuyv, int[] outY) {
        int[] prevSample = new int[1200];
        boolean hasPrev = false;
        for (int i = 0; i < 8; i++) {
            HYSDVAF2.s1cam(yuyv);
            double diff = 0;
            int k = 0;
            for (int v = 80; v < 320; v += 8) {
                int row = v * AlcoveVisionPipeline.CAM_W;
                for (int u = 80; u < 480; u += 10) {
                    int val = yuyv[(row + u) << 1] & 0xFF;
                    if (hasPrev) diff += Math.abs(val - prevSample[k]);
                    prevSample[k++] = val;
                }
            }
            if (hasPrev && i >= 4 && (diff / k) < 2.2) {
                break;
            }
            hasPrev = true;
        }
        AlcoveVisionPipeline.extractLuma(yuyv, outY);
    }

    /**
     * Closed-loop pattern-flip detector: reads V4L2 frames until pixels in the outer checker zone
     * invert relative to `refFrame` (meanAbsDiff >= minFlipDiff) AND settle frame-to-frame!
     */
    private static void captureFlippedCheckerFrame(byte[] yuyv, int[] refFrame, int[] outY, double minFlipDiff) {
        int[] prevSample = new int[900];
        boolean flippedOnce = false;
        for (int i = 0; i < 22; i++) {
            HYSDVAF2.s1cam(yuyv);
            double flipDiff = 0;
            double settleDiff = 0;
            int k = 0;
            // Sample outer checker region (excluding central 3-tile origin tag)
            for (int v = 70; v < 310; v += 10) {
                int row = v * AlcoveVisionPipeline.CAM_W;
                for (int u = 90; u < 420; u += 10) {
                    if (u >= 210 && u <= 330 && v >= 135 && v <= 235) continue;
                    int val = yuyv[(row + u) << 1] & 0xFF;
                    flipDiff += Math.abs(val - refFrame[row + u]);
                    settleDiff += Math.abs(val - prevSample[k]);
                    prevSample[k++] = val;
                }
            }
            double meanFlip = flipDiff / Math.max(1, k);
            double meanSettle = settleDiff / Math.max(1, k);
            if (meanFlip >= minFlipDiff) {
                if (flippedOnce && meanSettle < 3.5) {
                    break;
                }
                flippedOnce = true;
            } else {
                sleepQuiet(15);
            }
        }
        AlcoveVisionPipeline.extractLuma(yuyv, outY);
    }

