        this.pendingDfdBracket = runDfdMotorBracket;
        this.savedExitType = SystemProperties.get("persist.hysd.exittype", "2");
        if ("0".equals(this.savedExitType)) {
            this.savedExitType = "2";
        }
        this.chainStage2AfterStage1.set(true);

        Intent stage1Intent = new Intent(intent);
        stage1Intent.putExtra("mode", 1);
        stage1Intent.putExtra("afswitch", afSwitch);
        stage1Intent.putExtra("keyswitch", (keySwitch == 1 || mode == 3 || mode == 7) ? 1 : 0);
        stage1Intent.putExtra("dmode", 0);

        String origObs = SystemProperties.get("persist.hysd.obs_open", "1");
        String origMb = SystemProperties.get("persist.hysd.mb_open", "1");
        SystemProperties.set("persist.hysd.obs_open", "0");
        SystemProperties.set("persist.hysd.mb_open", "0");
        SystemProperties.set("persist.hysd.exittype", "0");

        final long stage1Token = System.nanoTime();
        startStage1Watchdog(stage1Token);

        try {
            Log.i(TAG, "Stage 1 starting: factory AF (af=" + afSwitch + ") + 3D Tsai/IMU trapezoid (dmode=0)");
            return super.onStartCommand(stage1Intent, flags, startId);
        } catch (Throwable t) {
            Log.e(TAG, "Stage 1 launch failed; falling back to Stage 2", t);
            chainStage2AfterStage1.set(false);
            SystemProperties.set("persist.hysd.exittype", savedExitType);
            running.set(false);
            return START_NOT_STICKY;
        } finally {
            // VAF2T.onStartCommand reads obs_open & mb_open synchronously on main thread before returning
            SystemProperties.set("persist.hysd.obs_open", origObs);
            SystemProperties.set("persist.hysd.mb_open", origMb);
        }
    }

    private volatile long activeStage1Token = 0L;

    private void startStage1Watchdog(final long token) {
        this.activeStage1Token = token;
        new Thread(new Runnable() {
            @Override
            public void run() {
                sleepQuiet(16000);
                if (activeStage1Token == token && chainStage2AfterStage1.compareAndSet(true, false)) {
                    Log.w(TAG, "Stage 1 watchdog expired after 16s; restoring state.");
                    SystemProperties.set("persist.hysd.exittype", savedExitType);
                    running.set(false);
                }
            }
        }, "TurboStage1Watchdog").start();
    }

    @Override
    public int workfinished() {
        final boolean chainStage2 = chainStage2AfterStage1.compareAndSet(true, false);
        if (chainStage2) {
            SystemProperties.set("persist.hysd.exittype", "0");
        }
        int rc = super.workfinished();
        if (!chainStage2) {
            return rc;
        }

        SystemProperties.set("persist.hysd.exittype", savedExitType);
        SystemProperties.set("com.hysd.focusing", "1");
        Log.i(TAG, "Stage 1 complete (rc=" + rc + ") -> chaining Stage 2 Alcove sidewall + obstacle fit!");

        // Let VAF2T's UI cleanup runnable finish removing its focus reticle view cleanly
        sleepQuiet(70);
        try {
            executeTurboAlcovePipeline(true, null, pendingDfdBracket);
        } finally {
            running.set(false);
        }
        return rc;
    }

    private void resetKeystoneFast() {
        SystemProperties.set("persist.hysd.base_trap", "");
        ServiceHolder holder = bindHysdClient(1500);
        try {
            if (holder.service != null) {
                holder.service.setkey(0, 0, 0, 0, 0, 0, 0, 0);
                holder.service.finishkey(1, 1, 0);
            }
        } catch (Throwable t) {
            Log.e(TAG, "Fast resetkey failed", t);
        } finally {
            holder.unbind(this);
            stopSelf();
        }
    }

    private static String formatBaseTrap(int[] q) {
        if (q == null || q.length != 8) return "";
        return q[0] + "," + q[1] + "," + q[2] + "," + q[3] + ","
                + q[4] + "," + q[5] + "," + q[6] + "," + q[7];
    }

    private static int[] parseBaseTrap(String s) {
        if (s == null || s.isEmpty()) return null;
        String[] parts = s.split(",");
        if (parts.length != 8) return null;
        int[] q = new int[8];
        try {
            for (int i = 0; i < 8; i++) q[i] = Integer.parseInt(parts[i].trim());
            return q;
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private void executeTurboAlcovePipeline(
            boolean readFreshStage1Trap, int[] explicitBaseTrap, boolean runDfdBracket) {
        final long tStart = System.nanoTime();
        SystemProperties.set("com.hysd.focusing", "1");
        SystemProperties.set("keystatus.hysd.sf", "0");

        // Overlap V4L2 camera open (USB UVC stream-on) concurrently with AIDL bind + overlay attach!
        final int camId = SystemProperties.getInt("persist.keystone.camid", 0);
        final AtomicBoolean camReady = new AtomicBoolean(false);
        final CountDownLatch camLatch = new CountDownLatch(1);
        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    int rc = HYSDVAF2.s0cam(camId, 2);
                    if (rc != 1) {
                        sleepQuiet(50);
                        rc = HYSDVAF2.s0cam(camId, 2);
                    }
                    camReady.set(true);
                } catch (Throwable t) {
                    Log.e(TAG, "Parallel s0cam error", t);
                } finally {
                    camLatch.countDown();
                }
            }
        }, "TurboCamOpen").start();

        ServiceHolder aidl = bindHysdClient(1800);
        PatternOverlayView overlay = null;
        WindowManager wm = (WindowManager) getSystemService(Context.WINDOW_SERVICE);
        int[] baseTrap = null;
        boolean camOpened = false;
        Runnable deferredDebugSave = null;

        try {
            if (aidl.service == null) {
                Log.e(TAG, "Could not bind com.hysd.client.VAFclientapi");
                camLatch.await(1200, TimeUnit.MILLISECONDS);
                camOpened = camReady.get();
                return;
            }

            if (readFreshStage1Trap) {
                // Stage 1 just wrote the exact uncropped 3D perspective trapezoid Q_trap!
                // Keep Q_trap active on DisplayEngine so our 1920x1080 checkerboard is ALREADY
                // perspective-rectified into dead-level 16:9 wall coordinates!
                baseTrap = aidl.service.getkey();
                if (baseTrap == null || baseTrap.length != 8) {
                    baseTrap = new int[8];
                }
                SystemProperties.set("persist.hysd.base_trap", formatBaseTrap(baseTrap));
                Log.i(TAG, "Stage 2 active 3D baseTrap=" + Arrays.toString(baseTrap));
            } else if (explicitBaseTrap != null && explicitBaseTrap.length == 8) {
                baseTrap = explicitBaseTrap.clone();
                aidl.service.setkey(baseTrap[0], baseTrap[1], baseTrap[2], baseTrap[3],
                        baseTrap[4], baseTrap[5], baseTrap[6], baseTrap[7]);
            } else {
                baseTrap = new int[8];
                aidl.service.setkey(0, 0, 0, 0, 0, 0, 0, 0);
            }

            overlay = attachOverlay(wm);
            if (overlay == null) {
                Log.e(TAG, "Could not attach full-screen PatternOverlayView");
                camLatch.await(1200, TimeUnit.MILLISECONDS);
                camOpened = camReady.get();
                return;
            }
            // Start with constant-50%-flux CHECKER_POS while s0cam opens so camera AE stays locked!
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_CHECKER_POS, 250);
            sleepQuiet(55);

            camLatch.await(2000, TimeUnit.MILLISECONDS);
            camOpened = camReady.get();

            byte[] yuyv = new byte[YUYV_FRAME_BYTES];
            int[] yPos = new int[AlcoveVisionPipeline.CAM_N];
            int[] yNeg = new int[AlcoveVisionPipeline.CAM_N];
            int[] yOrigin = new int[AlcoveVisionPipeline.CAM_N];
            int[] yNearPos = null;

            // 1. Capture settled CHECKER_POS (50% flux, lens already focused razor-sharp by Stage 1!)
            captureSettledCheckerBase(yuyv, yPos);

            // 2. Switch to exact pixelwise complement CHECKER_NEG (50% flux -> zero AE shift!)
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_CHECKER_NEG, 150);
            sleepQuiet(25);
            captureFlippedCheckerFrame(yuyv, yPos, yNeg, 24.0);

            // 3. Switch to ORIGIN_TAG (flips outer tiles back to POS while keeping 3 L-triad center tiles inverted)
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_ORIGIN_TAG, 150);
            sleepQuiet(25);
            captureFlippedCheckerFrame(yuyv, yNeg, yOrigin, 20.0);

            if (runDfdBracket) {
                yNearPos = new int[AlcoveVisionPipeline.CAM_N];
                aidl.service.motorf();
                sleepQuiet(80);
                aidl.service.motors();
                sleepQuiet(30);
                captureFreshV4l2Frame(yuyv, yNearPos, 4);
                aidl.service.motorb();
                sleepQuiet(85);
                aidl.service.motors();
                sleepQuiet(20);
            }

            // Release V4L2 camera asynchronously while CPU solves so zero serial close wait!
            camOpened = false;
            new Thread(new Runnable() {
                @Override
                public void run() {
                    try { HYSDVAF2.s2cam(); } catch (Throwable ignored) {}
                }
            }, "TurboCamClose").start();

            long captureMs = (System.nanoTime() - tStart) / 1_000_000L;
            float minArea = Float.parseFloat(SystemProperties.get("persist.hysd.alcove.min_area", "0.24"));
            boolean saveDebug = !"0".equals(SystemProperties.get("persist.hysd.alcove.debug", "1"));

            AlcoveVisionPipeline.Result res = AlcoveVisionPipeline.solveChecker(
                    yPos, yNeg, yOrigin, yNearPos, baseTrap, minArea, saveDebug);
            deferredDebugSave = res.deferredDebugSaver;

            long totalMs = (System.nanoTime() - tStart) / 1_000_000L;
            if (res.success) {
                int[] k = res.insets;
                aidl.service.setkey(k[0], k[1], k[2], k[3], k[4], k[5], k[6], k[7]);
                aidl.service.finishkey(1, 1, 0);
                SystemProperties.set("keystatus.hysd.sf", "1");
                SystemProperties.set("keystatus.hysd.keyresult", "1");

                String hud = String.format("Alcove Fit %dx%d (%dms)",
                        (res.rectRightPx - res.rectLeftPx),
                        (res.rectBottomPx - res.rectTopPx),
                        totalMs);
                Log.i(TAG, "SUCCESS stage2=" + totalMs + "ms (capture=" + captureMs + "ms, solve=" + res.solveTimeMs
                        + "ms) baseTrap=" + Arrays.toString(baseTrap) + " finalInsets=" + Arrays.toString(k));

                if (!"0".equals(SystemProperties.get("persist.hysd.alcove.hud", "1"))) {
                    overlay.showConfirmHud(k, hud);
                    sleepQuiet(180);
                }

