public class VAF2S extends VAF2T {
    private static final String TAG = "TurboAlcoveVAF2S";
    private static final int YUYV_FRAME_BYTES = AlcoveVisionPipeline.CAM_W * AlcoveVisionPipeline.CAM_H * 2;

    private final AtomicBoolean running = new AtomicBoolean(false);
    private final Handler mainHandler = new Handler(Looper.getMainLooper());

    @Override
    public int onStartCommand(final Intent intent, int flags, int startId) {
        if ("1".equals(SystemProperties.get("persist.hysd.turbo_disable", "0"))) {
            Log.i(TAG, "persist.hysd.turbo_disable=1 -> delegating to stock VAF2T");
            return super.onStartCommand(intent, flags, startId);
        }

        if (intent == null) {
            return START_NOT_STICKY;
        }

        final int mode = intent.getIntExtra("mode", 1);
        final int dmodeProp = SystemProperties.getInt("persist.htp.hysd.dmode", 3);
        final int dmode = intent.getIntExtra("dmode", dmodeProp);
        final int afSwitch = intent.getIntExtra("afswitch", SystemProperties.getInt("persist.sys.autofocus", 0));
        final int keySwitch = intent.getIntExtra("keyswitch", SystemProperties.getInt("persist.sys.autotrapezoid", 1));
        final boolean obsOpen = "1".equals(SystemProperties.get("persist.hysd.obs_open", "1"));
        final boolean mbOpen = "1".equals(SystemProperties.get("persist.hysd.mb_open", "1"));

        Log.i(TAG, "onStartCommand mode=" + mode + " dmode=" + dmode + " af=" + afSwitch + " key=" + keySwitch);

        // Instant <20ms keystone reset for mode 5 / 6
        if (mode == 5 || mode == 6) {
            new Thread(new Runnable() {
                @Override
                public void run() {
                    resetKeystoneFast();
                }
            }, "TurboKeyReset").start();
            return START_NOT_STICKY;
        }

        // Delegate factory calibration, ToF hardware tests, and pure autofocus-only (mode==2) to stock VAF2T
        boolean isTurboCandidate =
                (mode == 3 || mode == 7 || mode == 99)
                || ((mode == 1 || mode == 4 || mode == 20 || mode == 21)
                    && (dmode > 0 || obsOpen || mbOpen || keySwitch == 1));

        if (!isTurboCandidate) {
            Log.i(TAG, "Delegating non-obstacle mode=" + mode + " to stock VAF2T");
            return super.onStartCommand(intent, flags, startId);
        }

        if (!running.compareAndSet(false, true)) {
            Log.w(TAG, "TurboAlcove scan already in progress; ignoring duplicate start.");
            return START_NOT_STICKY;
        }

        final boolean runCenterAfFirst = (afSwitch == 1 && mode != 3 && mode != 7)
                || intent.getIntExtra("force_af", 0) == 1;
        final boolean runDfdMotorBracket =
                "1".equals(SystemProperties.get("persist.hysd.alcove.dfd", "0"))
                || intent.getIntExtra("dfd", 0) == 1;

        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    executeTurboAlcovePipeline(runCenterAfFirst, runDfdMotorBracket);
                } finally {
                    running.set(false);
                }
            }
        }, "TurboAlcoveWorker").start();

        return START_NOT_STICKY;
    }

    private void resetKeystoneFast() {
        ServiceHolder holder = bindHysdClient(1500);
        try {
            if (holder.service != null) {
                holder.service.setkey(0, 0, 0, 0, 0, 0, 0, 0);
                holder.service.finishkey(1, 1, 0);
            }
        } catch (Throwable t) {
            Log.e(TAG, "Fast resetkey failed", t);
        } finally {
            holder.unbind(this);
            stopSelf();
        }
    }

    private void executeTurboAlcovePipeline(boolean runCenterAfFirst, boolean runDfdBracket) {
        final long tStart = System.nanoTime();
        SystemProperties.set("com.hysd.focusing", "1");
        SystemProperties.set("keystatus.hysd.sf", "0");

        // Overlap V4L2 camera open (USB UVC stream-on) concurrently with AIDL bind + overlay attach!
        final int camId = SystemProperties.getInt("persist.keystone.camid", 0);
        final AtomicBoolean camReady = new AtomicBoolean(false);
        final CountDownLatch camLatch = new CountDownLatch(1);
        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    int rc = HYSDVAF2.s0cam(camId, 2);
                    if (rc != 1) {
                        sleepQuiet(40);
                        rc = HYSDVAF2.s0cam(camId, 2);
                    }
                    camReady.set(true);
                } catch (Throwable t) {
                    Log.e(TAG, "Parallel s0cam error", t);
                } finally {
                    camLatch.countDown();
                }
            }
        }, "TurboCamOpen").start();

        ServiceHolder aidl = bindHysdClient(1800);
        PatternOverlayView overlay = null;
        WindowManager wm = (WindowManager) getSystemService(Context.WINDOW_SERVICE);
        int[] savedKey = null;
        boolean camOpened = false;
        Runnable deferredDebugSave = null;

        try {
            if (aidl.service == null) {
                Log.e(TAG, "Could not bind com.hysd.client.VAFclientapi");
                camLatch.await(1200, TimeUnit.MILLISECONDS);
                camOpened = camReady.get();
                return;
            }

            savedKey = aidl.service.getkey();
            // Reset to full 1920x1080 panel and attach opaque overlay while s0cam finishes in parallel
            aidl.service.setkey(0, 0, 0, 0, 0, 0, 0, 0);
            overlay = attachOverlay(wm);
            if (overlay == null) {
                Log.e(TAG, "Could not attach full-screen PatternOverlayView");
                camLatch.await(1200, TimeUnit.MILLISECONDS);
                camOpened = camReady.get();
                return;
            }
            // Start with constant-50%-flux CHECKER_POS while s0cam opens so camera AE stays locked!
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_CHECKER_POS, 250);
            sleepQuiet(60);

            camLatch.await(2000, TimeUnit.MILLISECONDS);
            camOpened = camReady.get();

            byte[] yuyv = new byte[YUYV_FRAME_BYTES];

            // Optional fast center-only back-wall autofocus (evaluated on high-contrast checker edges!)
            if (runCenterAfFirst) {
                captureFreshV4l2Frame(yuyv, null, 4);
                runFastCenterBackWallAutofocus(aidl.service, yuyv);
                sleepQuiet(35);
            }

            int[] yPos = new int[AlcoveVisionPipeline.CAM_N];
            int[] yNeg = new int[AlcoveVisionPipeline.CAM_N];
            int[] yOrigin = new int[AlcoveVisionPipeline.CAM_N];
            int[] yNearPos = null;

            // 1. Capture settled CHECKER_POS (50% flux)
            captureSettledCheckerBase(yuyv, yPos);

            // 2. Switch to exact pixelwise complement CHECKER_NEG (50% flux -> zero AE shift!)
            //    Gate closed-loop until central pixel difference |cur - yPos| flips > 28 DN and settles!
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_CHECKER_NEG, 150);
            sleepQuiet(25);
            captureFlippedCheckerFrame(yuyv, yPos, yNeg, 26.0);

            // 3. Switch to ORIGIN_TAG (flips outer tiles back to POS while keeping 3 L-triad center tiles inverted)
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_ORIGIN_TAG, 150);
            sleepQuiet(25);
            captureFlippedCheckerFrame(yuyv, yNeg, yOrigin, 22.0);

            if (runDfdBracket) {
                yNearPos = new int[AlcoveVisionPipeline.CAM_N];
                aidl.service.motorf();
                sleepQuiet(80);
                aidl.service.motors();
                sleepQuiet(30);
                captureFreshV4l2Frame(yuyv, yNearPos, 4);
                aidl.service.motorb();
                sleepQuiet(85);
                aidl.service.motors();
                sleepQuiet(20);
            }

            // Release V4L2 camera asynchronously while CPU solves so zero serial close wait!
            camOpened = false;
            new Thread(new Runnable() {
                @Override
                public void run() {
                    try { HYSDVAF2.s2cam(); } catch (Throwable ignored) {}
                }
            }, "TurboCamClose").start();

            long captureMs = (System.nanoTime() - tStart) / 1_000_000L;
            float minArea = Float.parseFloat(SystemProperties.get("persist.hysd.alcove.min_area", "0.24"));
            boolean saveDebug = !"0".equals(SystemProperties.get("persist.hysd.alcove.debug", "1"));

            AlcoveVisionPipeline.Result res = AlcoveVisionPipeline.solveChecker(
                    yPos, yNeg, yOrigin, yNearPos, minArea, saveDebug);
            deferredDebugSave = res.deferredDebugSaver;

            long totalMs = (System.nanoTime() - tStart) / 1_000_000L;
            if (res.success) {
                int[] k = res.insets;
                aidl.service.setkey(k[0], k[1], k[2], k[3], k[4], k[5], k[6], k[7]);
                aidl.service.finishkey(1, 1, 0);
                SystemProperties.set("keystatus.hysd.sf", "1");
                SystemProperties.set("keystatus.hysd.keyresult", "1");

                String hud = String.format("Alcove Fit %dx%d (%dms)",
                        (res.rectRightPx - res.rectLeftPx),
                        (res.rectBottomPx - res.rectTopPx),
                        totalMs);
                Log.i(TAG, "SUCCESS total=" + totalMs + "ms (capture=" + captureMs + "ms, solve=" + res.solveTimeMs
                        + "ms) insets=" + Arrays.toString(k));

                if (!"0".equals(SystemProperties.get("persist.hysd.alcove.hud", "1"))) {
                    overlay.showConfirmHud(k, hud);
                    sleepQuiet(180);
                }

