/**
 * Closed-loop pattern-flip detector: reads V4L2 frames until pixels in the outer checker zone
 * invert relative to `refFrame` (meanAbsDiff >= minFlipDiff) AND settle frame-to-frame!
 */
private static void captureFlippedCheckerFrame(byte[] yuyv, int[] refFrame, int[] outY, double minFlipDiff) {
    int[] prevSample = new int[900];
    boolean flippedOnce = false;
    for (int i = 0; i < 22; i++) {
        HYSDVAF2.s1cam(yuyv);
        double flipDiff = 0;
        double settleDiff = 0;
        int k = 0;
        // Sample outer checker region (excluding central 3-tile origin tag)
        for (int v = 70; v < 310; v += 10) {
            int row = v * AlcoveVisionPipeline.CAM_W;
            for (int u = 90; u < 420; u += 10) {
                if (u >= 210 && u <= 330 && v >= 135 && v <= 235) continue;
                int val = yuyv[(row + u) << 1] & 0xFF;
                flipDiff += Math.abs(val - refFrame[row + u]);
                settleDiff += Math.abs(val - prevSample[k]);
                prevSample[k++] = val;
            }
        }
        double meanFlip = flipDiff / Math.max(1, k);
        double meanSettle = settleDiff / Math.max(1, k);
        if (meanFlip >= minFlipDiff) {
            if (flippedOnce && meanSettle < 3.5) {
                break;
            }
            flippedOnce = true;
        } else {
            sleepQuiet(15);
        }
    }
    AlcoveVisionPipeline.extractLuma(yuyv, outY);
}

/**
 * Explicitly flushes `discardCount` queued V4L2 mmap ring buffers and captures the next fresh frame.
 */
private static void captureFreshV4l2Frame(byte[] yuyv, int[] outY, int discardCount) {
    for (int i = 0; i < discardCount; i++) {
        HYSDVAF2.s1cam(yuyv);
    }
    int rc = HYSDVAF2.s1cam(yuyv);
    if (rc < 0) {
        sleepQuiet(20);
        HYSDVAF2.s1cam(yuyv);
    }
    if (outY != null) {
        AlcoveVisionPipeline.extractLuma(yuyv, outY);
    }
}

private static double sampleFastMeanLuma(byte[] yuyv) {
    long sum = 0;
    int cnt = 0;
    for (int i = 0; i < YUYV_FRAME_BYTES; i += 64) {
        sum += (yuyv[i] & 0xFF);
        cnt++;
    }
    return cnt > 0 ? (sum / (double) cnt) : 0.0;
}

/**
 * Closed-loop hill-climbing autofocus evaluated strictly on the central 160x120 back-wall ROI
 * so closer side walls or pillars never bias focus distance.
 */
private static void runFastCenterBackWallAutofocus(HYSDInterface svc, byte[] yuyv) {
    try {
        HYSDVAF2.s1cam(yuyv);
        double s0 = AlcoveVisionPipeline.computeCenterFocusScore(yuyv);

        // Probe forward 70ms
        svc.motorf();
        sleepQuiet(70);
        svc.motors();
        HYSDVAF2.s1cam(yuyv);
        HYSDVAF2.s1cam(yuyv);
        double sFwd = AlcoveVisionPipeline.computeCenterFocusScore(yuyv);

        boolean goForward = sFwd >= s0 * 1.02;
        if (!goForward) {
            // Step back past origin
            svc.motorb();
            sleepQuiet(110);
            svc.motors();
            HYSDVAF2.s1cam(yuyv);
            HYSDVAF2.s1cam(yuyv);
            double sBack = AlcoveVisionPipeline.computeCenterFocusScore(yuyv);
            if (sBack < s0 * 0.99) {
                // Already at peak -> return to s0 (+40ms forward) and finish in ~220ms!
                svc.motorf();
                sleepQuiet(40);
                svc.motors();
                return;
            }
        }

        double peak = Math.max(s0, sFwd);
        for (int step = 0; step < 8; step++) {
            if (goForward) svc.motorf(); else svc.motorb();
            sleepQuiet(55);
            svc.motors();
            HYSDVAF2.s1cam(yuyv);
            HYSDVAF2.s1cam(yuyv);
            double cur = AlcoveVisionPipeline.computeCenterFocusScore(yuyv);
            if (cur > peak) {
                peak = cur;
            } else if (cur < peak * 0.95) {
                // Backtrack 1 step to peak
                if (goForward) svc.motorb(); else svc.motorf();
                sleepQuiet(55);
                svc.motors();
                break;
            }
        }
    } catch (Throwable t) {
        Log.w(TAG, "Center AF skipped: " + t.getMessage());
        try { svc.motors(); } catch (Throwable ignored) {}
    }
}

