toolArgs.new_str:
/**
 * Flushes stale V4L2 ring buffers and waits until CHECKER_POS spatial contrast (P90 - P10 >= 14 DN)
 * is visibly projected on the wall AND frame-to-frame luma has settled (< 2.0 DN).
 * Never exits early on pre-overlay black frames!
 */
private static void captureSettledCheckerBase(byte[] yuyv, int[] outY) {
    // Flush 4 queued ring buffers first so pre-overlay black frames are discarded immediately
    for (int f = 0; f < 4; f++) {
        HYSDVAF2.s1cam(yuyv);
    }
    int[] prevSample = new int[2000];
    int[] hist = new int[256];
    boolean hasPrev = false;
    for (int i = 0; i < 16; i++) {
        HYSDVAF2.s1cam(yuyv);
        Arrays.fill(hist, 0);
        double diff = 0;
        int k = 0;
        for (int v = 60; v < 400; v += 10) {
            int row = v * AlcoveVisionPipeline.CAM_W;
            for (int u = 60; u < 560; u += 12) {
                int val = yuyv[(row + u) << 1] & 0xFF;
                hist[val]++;
                if (hasPrev) diff += Math.abs(val - prevSample[k]);
                prevSample[k++] = val;
            }
        }
        int p10 = 0, p90 = 0, cum = 0;
        for (int b = 0; b < 256; b++) {
            cum += hist[b];
            if (cum <= k * 0.10) p10 = b;
            if (cum <= k * 0.90) p90 = b;
        }
        int contrast = p90 - p10;
        if (hasPrev && contrast >= 14 && (diff / Math.max(1, k)) < 2.0) {
            break;
        }
        if (contrast < 14) {
            sleepQuiet(15);
        }
        hasPrev = true;
    }
    AlcoveVisionPipeline.extractLuma(yuyv, outY);
}

/**
 * Closed-loop signed correlation-inversion detector:
 * Identifies bright tiles vs dark tiles in `refFrame` (excluding the central 3-tile origin tag),
 * and reads V4L2 frames until pixels that were DARK in `refFrame` become genuinely BRIGHTER than
 * pixels that were BRIGHT in `refFrame` (meanAtRefDark - meanAtRefBright >= invThresh) AND settle!
 */
private static void captureFlippedCheckerFrame(byte[] yuyv, int[] refFrame, int[] outY) {
    int[] hist = new int[256];
    int cnt = 0;
    for (int v = 60; v < 400; v += 10) {
        int row = v * AlcoveVisionPipeline.CAM_W;
        for (int u = 60; u < 560; u += 10) {
            hist[refFrame[row + u] & 0xFF]++;
            cnt++;
        }
    }
    int p15 = 0, p88 = 0, cum = 0;
    for (int b = 0; b < 256; b++) {
        cum += hist[b];
        if (cum <= cnt * 0.15) p15 = b;
        if (cum <= cnt * 0.88) p88 = b;
    }
    final int refSpan = Math.max(12, p88 - p15);
    final int highThresh = p15 + (refSpan * 65) / 100;
    final int lowThresh  = p15 + (refSpan * 30) / 100;
    final double reqInversion = Math.max(8.0, refSpan * 0.32);

    long sumU = 0, sumV = 0, cntC = 0;
    for (int v = 45; v < 425; v += 10) {
        int row = v * AlcoveVisionPipeline.CAM_W;
        for (int u = 45; u < 585; u += 10) {
            if (refFrame[row + u] >= highThresh) {
                sumU += u; sumV += v; cntC++;
            }
        }
    }
    final int centU = cntC > 10 ? (int) (sumU / cntC) : 290;
    final int centV = cntC > 10 ? (int) (sumV / cntC) : 200;

    // Also determine local ambient floor outside the beam so unlit background pixels aren't counted as "dark tiles"
    final int beamFloor = p15 + Math.max(3, refSpan / 10);

    int[] prevSample = new int[3200];
    boolean hasPrev = false;
    boolean invertedOnce = false;
    for (int i = 0; i < 22; i++) {
        HYSDVAF2.s1cam(yuyv);
        long sumAtRefBright = 0, nBright = 0;
        long sumAtRefDark = 0, nDark = 0;
        double settleDiff = 0;
        int sampleIdx = 0;

        for (int v = 45; v < 425; v += 10) {
            int row = v * AlcoveVisionPipeline.CAM_W;
            for (int u = 45; u < 585; u += 10) {
                if (Math.abs(u - centU) <= 58 && Math.abs(v - centV) <= 46) continue;
                int val = yuyv[(row + u) << 1] & 0xFF;
                int refVal = refFrame[row + u];
                if (hasPrev) {
                    settleDiff += Math.abs(val - prevSample[sampleIdx]);
                }
                prevSample[sampleIdx++] = val;

                if (refVal >= highThresh) {
                    sumAtRefBright += val;
                    nBright++;
                } else if (refVal <= lowThresh && val >= beamFloor) {
                    sumAtRefDark += val;
                    nDark++;
                }
            }
        }
        double meanSettle = hasPrev ? (settleDiff / Math.max(1, sampleIdx)) : 99.0;
        hasPrev = true;

        double meanAtBright = nBright > 8 ? (sumAtRefBright / (double) nBright) : 0.0;
        double meanAtDark   = nDark > 8 ? (sumAtRefDark / (double) nDark) : 0.0;
        double invScore = (nBright > 8 && nDark > 8) ? (meanAtDark - meanAtBright) : -99.0;

        if (invScore >= reqInversion) {
            if (invertedOnce && meanSettle < 2.8) {
                break;
            }
            invertedOnce = true;
        } else {
            sleepQuiet(15);
        }
    }
    AlcoveVisionPipeline.extractLuma(yuyv, outY);
}

