/**
 * Closed-loop pattern-flip detector invariant to 3D trapezoid size/shift:
 * measures pixel inversion strictly over active illuminated tiles (outside the 3-tile origin tag)
 * so trapezoid-cropped beams never dilute `meanFlip` with dark unlit border pixels!
 */
private static void captureFlippedCheckerFrame(byte[] yuyv, int[] refFrame, int[] outY, double minFlipDiff) {
    int maxRef = 0;
    int minRef = 255;
    for (int v = 50; v < 420; v += 12) {
        int row = v * AlcoveVisionPipeline.CAM_W;
        for (int u = 50; u < 580; u += 12) {
            int rv = refFrame[row + u];
            if (rv > maxRef) maxRef = rv;
            if (rv < minRef) minRef = rv;
        }
    }
    final int activeGate = minRef + Math.max(18, (maxRef - minRef) / 4);
    long sumU = 0, sumV = 0, cntC = 0;
    for (int v = 40; v < 430; v += 10) {
        int row = v * AlcoveVisionPipeline.CAM_W;
        for (int u = 40; u < 590; u += 10) {
            if (refFrame[row + u] >= activeGate) {
                sumU += u; sumV += v; cntC++;
            }
        }
    }
    final int centU = cntC > 10 ? (int) (sumU / cntC) : 290;
    final int centV = cntC > 10 ? (int) (sumV / cntC) : 200;

    int[] prevSample = new int[3200];
    boolean hasPrev = false;
    boolean flippedOnce = false;
    for (int i = 0; i < 20; i++) {
        HYSDVAF2.s1cam(yuyv);
        double flipDiff = 0;
        double settleDiff = 0;
        int activeK = 0;
        int sampleIdx = 0;
        for (int v = 40; v < 430; v += 10) {
            int row = v * AlcoveVisionPipeline.CAM_W;
            for (int u = 40; u < 590; u += 10) {
                if (Math.abs(u - centU) <= 55 && Math.abs(v - centV) <= 45) continue;
                int val = yuyv[(row + u) << 1] & 0xFF;
                int refVal = refFrame[row + u];
                if (hasPrev) {
                    settleDiff += Math.abs(val - prevSample[sampleIdx]);
                }
                prevSample[sampleIdx++] = val;
                if (val >= activeGate || refVal >= activeGate) {
                    flipDiff += Math.abs(val - refVal);
                    activeK++;
                }
            }
        }
        double meanSettle = hasPrev ? (settleDiff / Math.max(1, sampleIdx)) : 99.0;
        hasPrev = true;
        double meanFlip = activeK >= 20 ? (flipDiff / activeK) : 0.0;
        if (meanFlip >= minFlipDiff || (activeK < 20 && i >= 5 && meanSettle < 2.5)) {
            if (flippedOnce && meanSettle < 3.5) {
                break;
            }
            flippedOnce = true;
        } else {
            sleepQuiet(15);
        }
    }
    AlcoveVisionPipeline.extractLuma(yuyv, outY);
}

