                 float localBg = Math.max(0.28f, smoothNormW[gx][gy]);
                 // Preserve natural 1/r^2 shading across wide walls while rejecting genuinely dark obstacles
                 if (nw < plateauRef * 0.42f || nw < localBg * 0.68f) continue;

                 if (camDfdRatio != null && projDfd[gx][gy] > 1.18f) continue;
                 rawValid[gx][gy] = true;
                 if (insideInterior) interiorValid++;
             }
         }

         // Fill isolated checkerboard-seam ripples / dust specks (< 3x3) so single-cell noise never
         // splits the monotonic histogram and shrinks the 16:9 projection!
         boolean[][] closed = fillSmallHoles5x5(morphClose2(rawValid), leftSeamGx, rightSeamGx, topSeamGy, bottomSeamGy);
         boolean[][] safeValid = erode(closed, 1);

         int lPx, tPx, rPx, bPx;
         boolean isOpenClearWall = (leftSeamGx <= 2 && rightSeamGx >= GW - 3
                 && topSeamGy <= 2 && bottomSeamGy >= GH - 3
                 && interiorTotal > 100 && (interiorValid / (float) interiorTotal) >= 0.93f);

         if (isOpenClearWall) {
             // Open unobstructed wall -> preserve 100% of factory 3D trapezoid size!
             lPx = 0;
             tPx = 0;
             rPx = PatternOverlayView.PROJ_W;
             bPx = PatternOverlayView.PROJ_H;
         } else {
             // 9. Optimal 16:9 unobstructed rectangle centered cleanly inside [leftSeamGx..rightSeamGx]
             int[] bestRectCells = findOptimal16x9Rect(safeValid, leftSeamGx, rightSeamGx, topSeamGy, bottomSeamGy);
             int gx0 = bestRectCells[0], gy0 = bestRectCells[1], gx1 = bestRectCells[2], gy1 = bestRectCells[3];

             // Snap to full edge if no seam was detected on that side
             lPx = (gx0 <= 2 && leftSeamGx <= 2) ? 0 : clamp(gx0 * CELL_PX, 0, 1280);
             tPx = (gy0 <= 2 && topSeamGy <= 2) ? 0 : clamp(gy0 * CELL_PX, 0, 720);
             rPx = (gx1 >= GW - 3 && rightSeamGx >= GW - 3)
                     ? PatternOverlayView.PROJ_W : clamp((gx1 + 1) * CELL_PX, lPx + 480, PatternOverlayView.PROJ_W);
             bPx = (gy1 >= GH - 3 && bottomSeamGy >= GH - 3)
                     ? PatternOverlayView.PROJ_H : clamp((gy1 + 1) * CELL_PX, tPx + 270, PatternOverlayView.PROJ_H);

             // Enforce strict exact 16:9 aspect ratio inside [lPx..rPx] x [tPx..bPx] on EVERY path!
             int availW = rPx - lPx;
             int availH = bPx - tPx;
             int exactW = Math.min(availW, Math.round(availH * 16f / 9f));
             int exactH = Math.round(exactW * 9f / 16f);
             exactW = Math.round(exactH * 16f / 9f);
             int cx = (lPx + rPx) / 2;
             int cy = (tPx + bPx) / 2;
             lPx = clamp(cx - exactW / 2, lPx, rPx - exactW);
             rPx = lPx + exactW;
             tPx = clamp(cy - exactH / 2, tPx, bPx - exactH);
             bPx = tPx + exactH;
         }

         float areaRatio = ((rPx - lPx) * (bPx - tPx)) / (float) (PatternOverlayView.PROJ_W * PatternOverlayView.PROJ_H);
         long solveMs = (System.nanoTime() - t0) / 1_000_000L;

         if (areaRatio < minAreaRatio) {
             Log.w(TAG, "Area ratio " + areaRatio + " below floor " + minAreaRatio + "; clamping to safe 16:9 floor.");
             int targetH = Math.min(1080, (int) Math.round(Math.sqrt(minAreaRatio * 1920.0 * 1080.0 * 9.0 / 16.0)));
             int targetW = Math.round(targetH * 16f / 9f);
             int cx = ((leftSeamGx + rightSeamGx + 1) * CELL_PX) / 2;
             int cy = ((topSeamGy + bottomSeamGy + 1) * CELL_PX) / 2;
             lPx = clamp(cx - targetW / 2, 0, 1920 - targetW);
             tPx = clamp(cy - targetH / 2, 0, 1080 - targetH);
             rPx = lPx + targetW;
             bPx = tPx + targetH;
         }

         // Compose rectified 16:9 alcove crop [lPx..rPx] x [tPx..bPx] onto factory 3D trapezoid `baseTrapOptional`!
         int[] insets = composeTrapezoidAndCrop(baseTrapOptional, lPx, tPx, rPx, bPx);

         String summary = String.format(
                 "Alcove 16:9 [%d..%d x %d..%d] (%dx%d, %.0f%%) | Walls L=%d R=%d T=%d B=%d | Corners=%d | %dms",
                 lPx, rPx, tPx, bPx, (rPx - lPx), (bPx - tPx),
                 100f * ((rPx - lPx) * (bPx - tPx)) / (1920f * 1080f),
                 leftSeamGx * CELL_PX, (rightSeamGx + 1) * CELL_PX,
                 topSeamGy * CELL_PX, (bottomSeamGy + 1) * CELL_PX,
                 matchedDots, solveMs);
         Log.i(TAG, summary);

         Runnable debugSaver = null;
         if (saveDebug) {
             final double[] fHback = Hback;
             final int fLPx = lPx, fTPx = tPx, fRPx = rPx, fBPx = bPx;
             final int fLeftGx = leftSeamGx, fRightGx = rightSeamGx, fTopGy = topSeamGy, fBotGy = bottomSeamGy;
             final int[] fInsets = insets;
             final String fSummary = summary;
             debugSaver = new Runnable() {
                 @Override
                 public void run() {
                     saveCheckerDiagnostic(W, corners, gridToCorner, dotParallax, fHback,
                             safeValid, fLeftGx, fRightGx, fTopGy, fBotGy,
                             fLPx, fTPx, fRPx, fBPx, fInsets, fSummary);
                 }
             };
         }

         return new Result(
                 true, insets, lPx, tPx, rPx, bPx,
                 leftSeamGx * CELL_PX, (rightSeamGx + 1) * CELL_PX,
                 topSeamGy * CELL_PX, (bottomSeamGy + 1) * CELL_PX,
                 matchedDots, solveMs, summary, debugSaver);
     }

     /**
      * Detects the vertical boundary between the bright central projection wall and darker grey
      * angled side walls / protruding pillars (e.g., +54% jump at left pillar, -32% drop at right sidewall),
      * reinforced by 3D checkerboard homography parallax kink and cone-height slope break.
      */
     private static int detectBrightPlateauVerticalSeam(
             float[][] normW, float[][] projW, float[][] projParallax,
             float[][] projSharp, float[][] projDfd,
             int beamThresh, float refSharp, boolean scanLeft) {

         int[] colSpan = new int[GW];
         for (int x = 0; x < GW; x++) {
             int t = -1, b = -1;
             for (int y = 0; y < GH / 2; y++) {
                 if (projW[x][y] >= beamThresh * 1.15f) { t = y; break; }
             }
             for (int y = GH - 1; y > GH / 2; y--) {
                 if (projW[x][y] >= beamThresh * 1.15f) { b = y; break; }
             }
             colSpan[x] = (t >= 0 && b > t) ? (b - t) : 0;
         }
         int refSpan = colSpan[GW / 2] > 0 ? colSpan[GW / 2] : GH - 8;

         // Dynamically locate the brightest central plateau column so repointing left/right
         // always anchors inside the true bright main wall!
         float[] colMean = new float[GW];
         for (int x = 20; x < GW - 20; x++) {
             float s = 0; int cnt = 0;
             for (int y = 22; y < GH - 22; y++) {
                 if (projW[x][y] >= beamThresh * 1.15f) { s += normW[x][y]; cnt++; }
             }
             colMean[x] = cnt > 16 ? (s / cnt) : 0f;
         }
         int plateauCenterGx = GW / 2;
         float bestBand = -1f;
         for (int x = 42; x <= GW - 43; x++) {
             float band = 0f;
             for (int d = -12; d <= 12; d++) band += colMean[x + d];
             // Mild preference toward optical center so two equally bright flat zones stay centered
             band *= (1.0f - 0.08f * Math.abs(x - GW * 0.5f) / (GW * 0.5f));
             if (band > bestBand) { bestBand = band; plateauCenterGx = x; }
         }

         int defaultEdge = scanLeft ? 1 : (GW - 2);
         int startGx = scanLeft ? clamp(plateauCenterGx - 12, 24, 96) : clamp(plateauCenterGx + 12, 90, GW - 25);
         int endGx = scanLeft ? 4 : (GW - 5);
         int step = scanLeft ? -1 : 1;

         float[] scores = new float[GW];
         float maxScore = 0f;

         for (int gx = startGx; gx != endGx; gx += step) {
             int inStart = scanLeft ? (gx + 1) : (gx - 5);
             int outStart = scanLeft ? (gx - 5) : (gx + 1);
             if (inStart < 1 || inStart + 4 >= GW || outStart < 1 || outStart + 4 >= GW) continue;

             float sumInW = 0, sumOutW = 0, sumEdge = 0, positiveStepSum = 0;
             float sumOutPar = 0, sumInPar = 0, sumOutSharp = 0;
             int sharpCnt = 0, activeRows = 0, unlitOuter = 0;

             for (int gy = 14; gy < GH - 14; gy++) {
                 if (projW[inStart + 2][gy] < beamThresh * 1.2f) continue;
                 activeRows++;
                 if (projW[outStart + 2][gy] < beamThresh) {
                     unlitOuter++;
                 }

                 float inV = 0, outV = 0;
                 for (int k = 0; k < 5; k++) {
                     inV += normW[inStart + k][gy];
                     outV += normW[outStart + k][gy];
                 }
                 inV *= 0.2f;
                 outV *= 0.2f;

                 sumInW += inV;
                 sumOutW += outV;
                 // Positive step = inner back wall is BRIGHTER than outer grey side wall / pillar!
                 float diff = inV - outV;
                 sumEdge += Math.abs(diff);
                 positiveStepSum += diff;

                 sumInPar += projParallax[inStart + 2][gy];
                 sumOutPar += projParallax[outStart + 2][gy];
                 sumOutSharp += projSharp[outStart + 2][gy];
                 sharpCnt++;
             }

             if (activeRows < 24) continue;
             if (unlitOuter > activeRows * 0.65f) {
                 if (maxScore < 0.55f) return scanLeft ? (gx + 1) : (gx - 1);
                 break;
             }

             float meanInW = sumInW / activeRows;
             float meanOutW = Math.max(0.05f, sumOutW / activeRows);
             float brightnessDropRatio = meanInW / meanOutW; // e.g., 1.54 at left pillar, 1.47 at right sidewall!
             float coherence = positiveStepSum / Math.max(1e-4f, sumEdge); // +1.0 when inner is consistently brighter!
             float relDrop = (meanInW - meanOutW) / Math.max(0.25f, meanInW);

             float meanOutPar = sumOutPar / activeRows;
             float parRise = Math.max(0f, meanOutPar - (sumInPar / activeRows));
             float sharpRatio = (sharpCnt > 8 && refSharp > 0.04f)
                     ? ((sumOutSharp / sharpCount(sharpCnt)) / refSharp) : 1.0f;

             int farOutGx = clamp(gx + step * 8, 2, GW - 3);
             int nearInGx = clamp(gx - step * 4, 2, GW - 3);
             float spanShrink = (colSpan[farOutGx] > 20 && colSpan[nearInGx] > 20 && refSpan > 40)
                     ? Math.max(0f, (colSpan[nearInGx] - colSpan[farOutGx]) / (float) refSpan) : 0f;

             float score = 0f;
             // Direct bright-backwall -> grey-sidewall vertical step (coherence > 0.80 and >= 19% drop)
             if (coherence > 0.80f && brightnessDropRatio >= 1.19f && relDrop >= 0.16f) {
                 score = relDrop * coherence * 5.0f;
                 if (spanShrink > 0.020f) score += spanShrink * 8.0f;
                 if (sharpRatio < 0.85f) score += (0.86f - sharpRatio) * 1.5f;
             }

             scores[gx] = score;
             if (score > maxScore) maxScore = score;
         }

         if (maxScore < 0.72f) return defaultEdge;

         // Lock onto the FIRST (innermost) clear wall-crease peak (>= 0.72) scanning outward from center!
         // This stops immediately at the alcove wall corner instead of marching onto outer switchboards.
         int bestGx = defaultEdge;
         for (int gx = startGx; gx != endGx; gx += step) {
             float s = scores[gx];
             if (s >= 0.72f
                     && s >= scores[clamp(gx - 1, 0, GW - 1)]
                     && s >= scores[clamp(gx + 1, 0, GW - 1)]
                     && s >= scores[clamp(gx + 2 * step, 0, GW - 1)]) {
                 bestGx = gx;
                 break;
             }
         }
         if (bestGx == defaultEdge) {
             for (int gx = startGx; gx != endGx; gx += step) {
                 if (scores[gx] == maxScore) { bestGx = gx; break; }
             }
         }
         Log.i(TAG, (scanLeft ? "LEFT" : "RIGHT") + " bright-wall seam locked at X="
                 + (bestGx * CELL_PX) + "px (score=" + String.format("%.2f", scores[bestGx]) + ")");
         return bestGx;
     }

     private static int sharpCount(int c) { return Math.max(1, c); }

     private static int detectHorizontalWallSeam(
             float[][] normW, float[][] projW, float[][] projParallax,
             float[][] projSharp, float[][] projDfd,
             int beamThresh, float refSharp, boolean scanTop, int gxMin, int gxMax) {

         int defaultEdge = scanTop ? 1 : (GH - 2);
         int startGy = scanTop ? 40 : 68;
         int endGy = scanTop ? 3 : (GH - 4);
         int step = scanTop ? -1 : 1;

         int x0 = Math.max(8, gxMin + 4);
         int x1 = Math.min(GW - 9, gxMax - 4);
         if (x1 - x0 < 20) {
             x0 = 32; x1 = GW - 32;
         }

         int bestGy = defaultEdge;
         float bestScore = 0f;

         for (int gy = startGy; gy != endGy; gy += step) {
             int inStart = scanTop ? (gy + 1) : (gy - 4);
             int outStart = scanTop ? (gy - 4) : (gy + 1);
             if (inStart < 1 || inStart + 3 >= GH || outStart < 1 || outStart + 3 >= GH) continue;

             float sumInW = 0, sumOutW = 0, sumEdge = 0, consistentSign = 0;
             float sumOutPar = 0, sumOutSharp = 0;
             int sharpCnt = 0, activeCols = 0, unlitOuter = 0;

result.content:
                    camLatch.countDown();
                }
            }
        }, "TurboCamOpen").start();

        ServiceHolder aidl = bindHysdClient(1800);
        PatternOverlayView overlay = null;
        WindowManager wm = (WindowManager) getSystemService(Context.WINDOW_SERVICE);
        int[] baseTrap = null;
        boolean camOpened = false;
        Runnable deferredDebugSave = null;

        try {
            if (aidl.service == null) {
                Log.e(TAG, "Could not bind com.hysd.client.VAFclientapi");
                camLatch.await(1200, TimeUnit.MILLISECONDS);
                camOpened = camReady.get();
                return;
            }

            if (readFreshStage1Trap) {
                // Stage 1 just wrote the exact uncropped 3D perspective trapezoid Q_trap!
                // Keep Q_trap active on DisplayEngine so our 1920x1080 checkerboard is ALREADY
                // perspective-rectified into dead-level 16:9 wall coordinates!
                baseTrap = aidl.service.getkey();
                if (baseTrap == null || baseTrap.length != 8) {
                    baseTrap = new int[8];
                }
                SystemProperties.set("persist.hysd.base_trap", formatBaseTrap(baseTrap));
                Log.i(TAG, "Stage 2 active 3D baseTrap=" + Arrays.toString(baseTrap));
            } else if (explicitBaseTrap != null && explicitBaseTrap.length == 8) {
                baseTrap = explicitBaseTrap.clone();
                aidl.service.setkey(baseTrap[0], baseTrap[1], baseTrap[2], baseTrap[3],
                        baseTrap[4], baseTrap[5], baseTrap[6], baseTrap[7]);
            } else {
                baseTrap = new int[8];
                aidl.service.setkey(0, 0, 0, 0, 0, 0, 0, 0);
            }

            overlay = attachOverlay(wm);
            if (overlay == null) {
                Log.e(TAG, "Could not attach full-screen PatternOverlayView");
                camLatch.await(1200, TimeUnit.MILLISECONDS);
                camOpened = camReady.get();
                return;
            }
            // Start with constant-50%-flux CHECKER_POS while s0cam opens so camera AE stays locked!
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_CHECKER_POS, 250);
            sleepQuiet(75);

            camLatch.await(2000, TimeUnit.MILLISECONDS);
            camOpened = camReady.get();

            byte[] yuyv = new byte[YUYV_FRAME_BYTES];
            int[] yPos = new int[AlcoveVisionPipeline.CAM_N];
            int[] yNeg = new int[AlcoveVisionPipeline.CAM_N];
            int[] yOrigin = new int[AlcoveVisionPipeline.CAM_N];
            int[] yNearPos = null;

            // 1. Flush initial V4L2 ring buffers and wait until CHECKER_POS spatial contrast is live & settled!
            captureSettledCheckerBase(yuyv, yPos);

            // 2. Switch to exact pixelwise complement CHECKER_NEG (50% flux -> zero AE shift!)
            //    Gate on SIGNED correlation inversion (dark-in-POS pixels become BRIGHTER than bright-in-POS pixels!)
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_CHECKER_NEG, 150);
            sleepQuiet(25);
            captureFlippedCheckerFrame(yuyv, yPos, yNeg);

            // 3. Switch to ORIGIN_TAG (flips outer tiles back to POS while keeping 3 L-triad center tiles inverted)
            overlay.setPatternAndAwaitDraw(PatternOverlayView.MODE_ORIGIN_TAG, 150);
            sleepQuiet(25);
            captureFlippedCheckerFrame(yuyv, yNeg, yOrigin);

            if (runDfdBracket) {
                yNearPos = new int[AlcoveVisionPipeline.CAM_N];
                aidl.service.motorf();
                sleepQuiet(80);
                aidl.service.motors();
                sleepQuiet(30);
                captureFreshV4l2Frame(yuyv, yNearPos, 4);
                aidl.service.motorb();
                sleepQuiet(85);
                aidl.service.motors();
                sleepQuiet(20);
            }

            // Release V4L2 camera asynchronously while CPU solves so zero serial close wait!
            camOpened = false;
            new Thread(new Runnable() {
                @Override
                public void run() {
                    try { HYSDVAF2.s2cam(); } catch (Throwable ignored) {}
                }
            }, "TurboCamClose").start();

            long captureMs = (System.nanoTime() - tStart) / 1_000_000L;
            float minArea = Float.parseFloat(SystemProperties.get("persist.hysd.alcove.min_area", "0.24"));
            boolean saveDebug = !"0".equals(SystemProperties.get("persist.hysd.alcove.debug", "1"));

            AlcoveVisionPipeline.Result res = AlcoveVisionPipeline.solveChecker(
                    yPos, yNeg, yOrigin, yNearPos, baseTrap, minArea, saveDebug);
            deferredDebugSave = res.deferredDebugSaver;

            long totalMs = (System.nanoTime() - tStart) / 1_000_000L;
            if (res.success) {
                int[] k = res.insets;
                aidl.service.setkey(k[0], k[1], k[2], k[3], k[4], k[5], k[6], k[7]);
                aidl.service.finishkey(1, 1, 0);
                SystemProperties.set("keystatus.hysd.sf", "1");
                SystemProperties.set("keystatus.hysd.keyresult", "1");

                String hud = String.format("Alcove Fit %dx%d (%dms)",
                        (res.rectRightPx - res.rectLeftPx),
                        (res.rectBottomPx - res.rectTopPx),
                        totalMs);
                Log.i(TAG, "SUCCESS stage2=" + totalMs + "ms (capture=" + captureMs + "ms, solve=" + res.solveTimeMs
                        + "ms) baseTrap=" + Arrays.toString(baseTrap) + " finalInsets=" + Arrays.toString(k));

                if (!"0".equals(SystemProperties.get("persist.hysd.alcove.hud", "1"))) {
                    overlay.showConfirmHud(k, hud);
                    sleepQuiet(180);
                }
            } else {
                Log.w(TAG, "Alcove solver did not converge (" + res.summary + "); preserving 3D base trapezoid.");
                if (baseTrap != null && baseTrap.length == 8) {
                    aidl.service.setkey(baseTrap[0], baseTrap[1], baseTrap[2], baseTrap[3],
                            baseTrap[4], baseTrap[5], baseTrap[6], baseTrap[7]);
                }
                aidl.service.finishkey(1, 0, -1);
            }
        } catch (Throwable t) {
            Log.e(TAG, "TurboAlcove pipeline error", t);
            try {
                if (baseTrap != null && baseTrap.length == 8 && aidl.service != null) {
                    aidl.service.setkey(baseTrap[0], baseTrap[1], baseTrap[2], baseTrap[3],
                            baseTrap[4], baseTrap[5], baseTrap[6], baseTrap[7]);
                }
            } catch (Throwable ignored) {}
        } finally {
            if (camOpened) {
                try { HYSDVAF2.s2cam(); } catch (Throwable ignored) {}
            }
            detachOverlay(wm, overlay);
            aidl.unbind(this);
            SystemProperties.set("com.hysd.focusing", "0");
            if (deferredDebugSave != null) {
                try { deferredDebugSave.run(); } catch (Throwable ignored) {}
            }
            stopSelf();
        }
    }

    /**
     * Flushes stale V4L2 ring buffers and waits until CHECKER_POS spatial contrast (P90 - P10 >= 14 DN)
     * is visibly projected on the wall AND frame-to-frame luma has settled (< 2.0 DN).
     * Never exits early on pre-overlay black frames!
     */
    private static void captureSettledCheckerBase(byte[] yuyv, int[] outY) {
        // Flush 4 queued ring buffers first so pre-overlay black frames are discarded immediately
        for (int f = 0; f < 4; f++) {
            HYSDVAF2.s1cam(yuyv);
        }
        int[] prevSample = new int[2000];
        int[] hist = new int[256];
        boolean hasPrev = false;
        for (int i = 0; i < 16; i++) {
            HYSDVAF2.s1cam(yuyv);
            Arrays.fill(hist, 0);
            double diff = 0;
            int k = 0;
            for (int v = 60; v < 400; v += 10) {
                int row = v * AlcoveVisionPipeline.CAM_W;
                for (int u = 60; u < 560; u += 12) {
                    int val = yuyv[(row + u) << 1] & 0xFF;
                    hist[val]++;
                    if (hasPrev) diff += Math.abs(val - prevSample[k]);
                    prevSample[k++] = val;
                }
            }
            int p10 = 0, p90 = 0, cum = 0;
            for (int b = 0; b < 256; b++) {
                cum += hist[b];
                if (cum <= k * 0.10) p10 = b;
                if (cum <= k * 0.90) p90 = b;
            }
            int contrast = p90 - p10;
            if (hasPrev && contrast >= 14 && (diff / Math.max(1, k)) < 2.0) {
                break;
            }
            if (contrast < 14) {
                sleepQuiet(15);
            }
            hasPrev = true;
        }
        AlcoveVisionPipeline.extractLuma(yuyv, outY);
    }

    /**
     * Closed-loop signed correlation-inversion detector:
     * Identifies bright tiles vs dark tiles in `refFrame` (excluding the central 3-tile origin tag),
     * and reads V4L2 frames until pixels that were DARK in `refFrame` become genuinely BRIGHTER than
     * pixels that were BRIGHT in `refFrame` (meanAtRefDark - meanAtRefBright >= invThresh) AND settle!
     */
    private static void captureFlippedCheckerFrame(byte[] yuyv, int[] refFrame, int[] outY) {
        int[] hist = new int[256];
        int cnt = 0;
        for (int v = 60; v < 400; v += 10) {
            int row = v * AlcoveVisionPipeline.CAM_W;
            for (int u = 60; u < 560; u += 10) {
                hist[refFrame[row + u] & 0xFF]++;
                cnt++;
            }
        }
        int p15 = 0, p88 = 0, cum = 0;
        for (int b = 0; b < 256; b++) {
            cum += hist[b];
            if (cum <= cnt * 0.15) p15 = b;
            if (cum <= cnt * 0.88) p88 = b;
        }
        final int refSpan = Math.max(12, p88 - p15);
        final int highThresh = p15 + (refSpan * 62) / 100;
        final int lowThresh  = p15 + (refSpan * 38) / 100;
        final int midThresh  = p15 + (refSpan * 50) / 100;

        long sumU = 0, sumV = 0, cntC = 0;
        for (int v = 45; v < 425; v += 10) {
            int row = v * AlcoveVisionPipeline.CAM_W;
            for (int u = 45; u < 585; u += 10) {
                if (refFrame[row + u] >= highThresh) {
                    sumU += u; sumV += v; cntC++;
                }
            }
        }
        final int centU = cntC > 10 ? (int) (sumU / cntC) : 290;
