        pref[0] = 0f;
        for (int gy = 0; gy < GH; gy++) pref[gy + 1] = pref[gy] + tmp[gx][gy];
        for (int gy = 0; gy < GH; gy++) {
            int lo = Math.max(0, gy - radius), hi = Math.min(GH - 1, gy + radius);
            out[gx][gy] = (pref[hi + 1] - pref[lo]) / (float) (hi - lo + 1);
        }
    }
