    stage1Intent.putExtra("mode", 1);
    stage1Intent.putExtra("afswitch", 0); // Defer focus until AFTER sidewall crop!
    stage1Intent.putExtra("keyswitch", 1);
    stage1Intent.putExtra("dmode", 0);

