private final AtomicBoolean running = new AtomicBoolean(false);
private final AtomicBoolean chainStage2AfterStage1 = new AtomicBoolean(false);
private volatile boolean pendingDfdBracket = false;
private volatile String savedExitType = "2";
private final Handler mainHandler = new Handler(Looper.getMainLooper());

@Override
public int onStartCommand(final Intent intent, int flags, int startId) {
    if ("1".equals(SystemProperties.get("persist.hysd.turbo_disable", "0"))) {
        Log.i(TAG, "persist.hysd.turbo_disable=1 -> delegating to stock VAF2T");
        return super.onStartCommand(intent, flags, startId);
    }

    if (intent == null) {
        return START_NOT_STICKY;
    }

    final int mode = intent.getIntExtra("mode", 1);
    final int dmodeProp = SystemProperties.getInt("persist.htp.hysd.dmode", 3);
    final int dmode = intent.getIntExtra("dmode", dmodeProp);
    final int afSwitch = intent.getIntExtra("afswitch", SystemProperties.getInt("persist.sys.autofocus", 0));
    final int keySwitch = intent.getIntExtra("keyswitch", SystemProperties.getInt("persist.sys.autotrapezoid", 1));
    final boolean obsOpen = "1".equals(SystemProperties.get("persist.hysd.obs_open", "1"));
    final boolean mbOpen = "1".equals(SystemProperties.get("persist.hysd.mb_open", "1"));

    Log.i(TAG, "onStartCommand mode=" + mode + " dmode=" + dmode + " af=" + afSwitch + " key=" + keySwitch);

    // Instant <20ms keystone + base_trap reset for mode 5 / 6
    if (mode == 5 || mode == 6) {
        new Thread(new Runnable() {
            @Override
            public void run() {
                resetKeystoneFast();
            }
        }, "TurboKeyReset").start();
        return START_NOT_STICKY;
    }

    // Pure autofocus-only (mode==2), factory calibration (mode==0, 51), ToF tests (22..30),
    // or auto-keystone when obstacle/screen-fit switches are disabled -> stock VAF2T directly
    final boolean wantAlcoveAvoidance =
            (mode == 3 || mode == 7 || mode == 99)
            || ((mode == 1 || mode == 4 || mode == 20 || mode == 21) && (dmode > 0 || obsOpen || mbOpen));

    if (!wantAlcoveAvoidance) {
        Log.i(TAG, "Delegating non-obstacle mode=" + mode + " directly to stock VAF2T");
        return super.onStartCommand(intent, flags, startId);
    }

    if (!running.compareAndSet(false, true)) {
        Log.w(TAG, "TurboAlcove pipeline already in progress; ignoring overlapping trigger.");
        return START_NOT_STICKY;
    }

    final boolean runDfdMotorBracket =
            "1".equals(SystemProperties.get("persist.hysd.alcove.dfd", "0"))
            || intent.getIntExtra("dfd", 0) == 1;

    // Manual obstacle-avoidance-only button (mode==3/7/99 with af==0) when we ALREADY have a
    // valid 3D base trapezoid for the current pose -> run Stage 2 directly in ~1.4s!
    final int[] cachedBaseTrap = parseBaseTrap(SystemProperties.get("persist.hysd.base_trap", ""));
    final boolean forceStage1 = (mode == 1 || mode == 4 || mode == 20 || mode == 21)
            || afSwitch == 1
            || (keySwitch == 1 && cachedBaseTrap == null);

    if (!forceStage1) {
        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    executeTurboAlcovePipeline(false, cachedBaseTrap, runDfdMotorBracket);
                } finally {
                    running.set(false);
                }
            }
        }, "TurboAlcoveStage2Only").start();
        return START_NOT_STICKY;
    }

    // TWO-STAGE HYBRID PIPELINE (Bootup, Repointing, Auto Focus + Trapezoid + Alcove):
    //   Stage 1: Run stock VAF2T with detectmode=0 (factory motor AF + 3D stereo Tsai/IMU trapezoid,
    //            skipping slow/inaccurate stock obstacle avoidance).
    //   Stage 2: Hook VAF2T.workfinished() -> immediately project our 1.1s constant-flux checkerboard
    //            inside Stage 1's rectified 3D trapezoid Q_trap and compose exact projective 16:9 fit!
    this.pendingDfdBracket = runDfdMotorBracket;
    this.savedExitType = SystemProperties.get("persist.hysd.exittype", "2");
    if ("0".equals(this.savedExitType)) {
        this.savedExitType = "2";
    }
    this.chainStage2AfterStage1.set(true);

    Intent stage1Intent = new Intent(intent);
    stage1Intent.putExtra("mode", 1);
    stage1Intent.putExtra("afswitch", afSwitch);
    stage1Intent.putExtra("keyswitch", (keySwitch == 1 || mode == 3 || mode == 7) ? 1 : 0);
    stage1Intent.putExtra("dmode", 0);

    String origObs = SystemProperties.get("persist.hysd.obs_open", "1");
    String origMb = SystemProperties.get("persist.hysd.mb_open", "1");
    SystemProperties.set("persist.hysd.obs_open", "0");
    SystemProperties.set("persist.hysd.mb_open", "0");
    SystemProperties.set("persist.hysd.exittype", "0");

    final long stage1Token = System.nanoTime();
    startStage1Watchdog(stage1Token);

    try {
        Log.i(TAG, "Stage 1 starting: factory AF (af=" + afSwitch + ") + 3D Tsai/IMU trapezoid (dmode=0)");
        return super.onStartCommand(stage1Intent, flags, startId);
    } catch (Throwable t) {
        Log.e(TAG, "Stage 1 launch failed; falling back to Stage 2", t);
        chainStage2AfterStage1.set(false);
        SystemProperties.set("persist.hysd.exittype", savedExitType);
        running.set(false);
        return START_NOT_STICKY;
    } finally {
        // VAF2T.onStartCommand reads obs_open & mb_open synchronously on main thread before returning
        SystemProperties.set("persist.hysd.obs_open", origObs);
        SystemProperties.set("persist.hysd.mb_open", origMb);
    }
}

private volatile long activeStage1Token = 0L;

private void startStage1Watchdog(final long token) {
    this.activeStage1Token = token;
    new Thread(new Runnable() {
        @Override
        public void run() {
            sleepQuiet(16000);
            if (activeStage1Token == token && chainStage2AfterStage1.compareAndSet(true, false)) {
                Log.w(TAG, "Stage 1 watchdog expired after 16s; restoring state.");
                SystemProperties.set("persist.hysd.exittype", savedExitType);
                running.set(false);
            }
        }
    }, "TurboStage1Watchdog").start();
}

@Override
public int workfinished() {
    final boolean chainStage2 = chainStage2AfterStage1.compareAndSet(true, false);
    if (chainStage2) {
        SystemProperties.set("persist.hysd.exittype", "0");
    }
    int rc = super.workfinished();
    if (!chainStage2) {
        return rc;
    }

    SystemProperties.set("persist.hysd.exittype", savedExitType);
    SystemProperties.set("com.hysd.focusing", "1");
    Log.i(TAG, "Stage 1 complete (rc=" + rc + ") -> chaining Stage 2 Alcove sidewall + obstacle fit!");

    // Let VAF2T's UI cleanup runnable finish removing its focus reticle view cleanly
    sleepQuiet(70);
    try {
        executeTurboAlcovePipeline(true, null, pendingDfdBracket);
    } finally {
        running.set(false);
    }
    return rc;
}

