private static float parseFloatSafe(String s, float defVal) {
    if (s == null || s.isEmpty()) return defVal;
    try {
        float v = Float.parseFloat(s.trim());
        return (Float.isNaN(v) || Float.isInfinite(v)) ? defVal : v;
    } catch (NumberFormatException e) {
        return defVal;
    }
}

