                sleepQuiet(180);
            }
        } else {
            Log.w(TAG, "Alcove solver did not converge (" + res.summary + "); preserving 3D base trapezoid.");
            if (baseTrap != null && baseTrap.length == 8) {
                aidl.service.setkey(baseTrap[0], baseTrap[1], baseTrap[2], baseTrap[3],
