const fs = require("fs");
const buf = fs.readFileSync("C:\\Users\\ngantla\\Backups\\Wzatco-Yuva-Blaze\\partitions\\bootloader_a.img");
// Search for ASCII filenames in FAT16 directory entries (.BMP)
for (let i = 0; i < 512 * 256; i += 32) {
  const ext = buf.slice(i + 8, i + 11).toString("ascii");
  if (ext === "BMP" || ext === "LZ4" || ext === "PNG") {
    const name = buf.slice(i, i + 8).toString("ascii").trim();
    const size = buf.readUInt32LE(i + 28);
    console.log(`FAT entry @${i}: ${name}.${ext} (${size} bytes)`);
  }
}
// Inspect BMP header at 262760 or scan for real BMP headers (bfSize matches)
for (let i = 0; i < buf.length - 54; i++) {
  if (buf[i] === 0x42 && buf[i+1] === 0x4D) {
    const bfSize = buf.readUInt32LE(i + 2);
    const biSize = buf.readUInt32LE(i + 14);
    const w = buf.readInt32LE(i + 18);
    const h = buf.readInt32LE(i + 22);
    const bpp = buf.readUInt16LE(i + 28);
    if (biSize === 40 && w > 100 && w <= 3840 && Math.abs(h) > 100 && Math.abs(h) <= 2160 && (bpp === 24 || bpp === 32)) {
      console.log(`BMP @${i}: ${w}x${h}, ${bpp}-bit, bfSize=${bfSize}`);
    }
  }
}
