const fs = require("fs");
const buf = fs.readFileSync("C:\\Users\\ngantla\\Backups\\Wzatco-Yuva-Blaze\\partitions\\bootloader_a.img");
console.log("Header magic:", buf.slice(0, 64).toString("ascii").replace(/[^\x20-\x7e]/g, "."));
// Check FAT16 BPB at offset 0
const bps = buf.readUInt16LE(11);
const spc = buf.readUInt8(13);
const resSec = buf.readUInt16LE(14);
const numFats = buf.readUInt8(16);
const rootEnt = buf.readUInt16LE(17);
const spf = buf.readUInt16LE(22);
console.log({ bps, spc, resSec, numFats, rootEnt, spf });
const rootOff = (resSec + numFats * spf) * bps;
console.log("Root dir offset:", rootOff);
for (let i = rootOff; i < rootOff + rootEnt * 32; i += 32) {
  const b0 = buf[i];
  if (b0 === 0x00) break;
  if (b0 === 0xE5 || buf[i + 11] === 0x0F) continue;
  const name = buf.slice(i, i + 8).toString("ascii").trim();
  const ext = buf.slice(i + 8, i + 11).toString("ascii").trim();
  const attr = buf[i + 11];
  const clus = buf.readUInt16LE(i + 26);
  const size = buf.readUInt32LE(i + 28);
  const dataStartSec = resSec + numFats * spf + Math.ceil((rootEnt * 32) / bps);
  const fileOff = (dataStartSec + (clus - 2) * spc) * bps;
  console.log(`ENTRY: ${name}.${ext} attr=0x${attr.toString(16)} clus=${clus} off=${fileOff} size=${size}`);
}
// Also check BMP header at 10412544
const o = 10412544;
console.log("BMP@10412544:", {
  bfSize: buf.readUInt32LE(o + 2),
  bfOffBits: buf.readUInt32LE(o + 10),
  biSize: buf.readUInt32LE(o + 14),
  biWidth: buf.readInt32LE(o + 18),
  biHeight: buf.readInt32LE(o + 22),
  biBitCount: buf.readUInt16LE(o + 28),
  biCompression: buf.readUInt32LE(o + 30)
});
