arguments.command:
$sess = "C:\Users\ngantla\.copilot\session-state\4c8ab7fc-bd1f-480c-99ab-4458bfed9b0e"

# Build map of SHA256 -> known file path across $sess\files (excluding transcript-images & published-updates)
$known = @{}
Get-ChildItem "$sess\files" -Recurse -File |
    Where-Object { $_.FullName -notmatch 'transcript-images|published-updates' } |
    ForEach-Object {
        $h = (Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLower()
        $known[$h] = $_.FullName.Substring("$sess\files\".Length)
    }

Write-Host "=== transcript-images SHA256 mapping ==="
Get-ChildItem "$sess\files\transcript-images" -File | ForEach-Object {
    $h = (Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLower()
    $match = if ($known.ContainsKey($h)) { $known[$h] } else { "USER_UPLOADED_OR_EARLIER_TURN_IMAGE" }
    [PSCustomObject]@{ File = $_.Name; Bytes = $_.Length; Source = $match }
} | Format-Table -AutoSize

# Check if events.jsonl contains base64 blobs or GH_TOKEN / Wi-Fi passwords
@'
const fs = require("fs");
const s = fs.readFileSync("C:\\Users\\ngantla\\.copilot\\session-state\\4c8ab7fc-bd1f-480c-99ab-4458bfed9b0e\\events.jsonl", "utf8");
const lines = s.split("\n").filter(Boolean);
let b64Count = 0, b64Bytes = 0, secretHits = 0;
for (const l of lines) {
  if (l.includes("/9j/4AAQ") || l.includes("iVBORw0KGgo")) {
    b64Count++;
    b64Bytes += l.length;
  }
  if (/ghp_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|PSK=[REDACTED_WIFI_SECRET]
    secretHits++;
  }
}
console.log({ totalLines: lines.length, b64Lines: b64Count, b64MB: (b64Bytes/1048576).toFixed(2), secretHits });
'@ | node -

